import type { Host } from '../host';
import { getDocument } from '../document/manager';
import { logInfo, logWarn } from '../config/logger';

/** Copy the visible (substituted) text of the active editor to the clipboard. */
export async function copyWithSubstitutions(host: Host): Promise<void> {
  const editor = host.activeTextEditor;
  if (!editor) {
    logWarn('copyWithSubstitutions: no active editor');
    return;
  }

  const doc = getDocument(editor.document);
  if (!doc) {
    logWarn(`copyWithSubstitutions: document is not pretty: ${editor.document.uri}`);
    return;
  }

  await doc.copyDecorated(editor);
  logInfo('Copied text with substitutions');
}

import { disablePrettySymbols, enablePrettySymbols } from './toggle';

/** Disable then re-enable everything — a full refresh of all documents. */
export const refreshPage = (): void => {
  disablePrettySymbols();
  enablePrettySymbols();
};

import type { Disposable } from '../host';
import { logInfo, logWarn } from '../config/logger';
import { getHost, reloadConfiguration } from '../config/settings';
import { getDocument, unloadAllDocuments } from '../document/manager';
import { requireRootStore } from '../store';

export type OnEnabledChangeHandler = (enabled: boolean) => void;

export function onEnabledChange(handler: OnEnabledChangeHandler): Disposable {
  const root = requireRootStore();
  root.enabledHandlers.add(handler);
  return {
    dispose() {
      root.enabledHandlers.delete(handler);
    },
  };
}

export function notifyEnabledChange(enabled: boolean): void {
  for (const h of requireRootStore().enabledHandlers) h(enabled);
}

export function setEnabled(value: boolean): void {
  const root = requireRootStore();
  if (root.enabled === value) return;
  root.enabled = value;
  if (!value) unloadAllDocuments();
  else reloadConfiguration();
  notifyEnabledChange(value);
}

export function enablePrettySymbols(): void {
  setEnabled(true);
}

export function disablePrettySymbols(): void {
  setEnabled(false);
}

/**
 * Toggles pretty symbols on the line under the active editor's cursor.
 * Unlike enable/disable, this is per-line: the rest of the file keeps
 * rendering normally.
 */
export function togglePrettySymbols(): void {
  const host = getHost();
  const editor = host?.activeTextEditor;
  if (!editor) {
    logWarn('togglePrettySymbols: no active editor');
    return;
  }
  const controller = getDocument(editor.document);
  if (!controller) {
    logInfo(`togglePrettySymbols: no controller for ${editor.document.fileName}`);
    return;
  }
  const line = editor.selections[0]?.active.line;
  if (line === undefined) {
    logWarn('togglePrettySymbols: no cursor position');
    return;
  }
  const disabled = controller.toggleLine(line);
  logInfo(`togglePrettySymbols: line ${line} ${disabled ? 'disabled' : 'enabled'}`);
}

import type { Disposable } from '../host';
import type { LanguageEntry } from './configuration';

/**
 * The public API surface exposed by the extension (see the `mdPrettify`
 * activation return value). The `LanguageEntry` type is the canonical one
 * from `./configuration` — it is a superset of what third-party extensions
 * need, so no separate (narrower) copy is kept here.
 */
export interface mdPrettify {
  /** Register a handler to receive notifications when PSM is enabled or disabled.
   * @returns a disposable object to unregister the handler
   */
  onDidEnabledChange: (handler: (enabled: boolean) => void) => Disposable,
  /** Query whether PSM is "enabled" - this refers to the user's ability to
   * temporarily enable/disable the mode for an instance of the IDE.
   * @returns `true` iff PSM is currently enabled
   */
  isEnabled: () => boolean,
  /** Temporarily add more substitutions.
   * @returns a disposable object to remove the provided substitutions
   */
  registerSubstitutions: (substitutions: LanguageEntry) => Disposable,
}

/** Describes conditions in which a symbol may be temporarily revealed */
export type UglyRevelation = 
	  'cursor'        // the cursor reveals any ugly symbol it touches
	| 'cursor-inside' // the cursor reveals any symbol it enters
	| 'active-line'   // the cursor reveals all symbols on the same line
	| 'selection'     // the cursor reveals all symbols within a selection
	| 'none';         // the cursor does not reveal any symbol

/** Controls how a symbol is rendered when a cursor is on it */
export type PrettyCursor =
    'boxed' // render an outline around the symbol
	| 'none'  // do change to the symbol

/** Essentially mirrors DecorationRenderOptions, but restricted to the
 * properties that apply to both :before/:after decorations and plain decorations */
export interface PrettyStyleProperties {
  border?: string,
	textDecoration?: string,
	/** A theme color name (resolved by the IDE adapter) or a plain CSS color. */
	color?: string,
	backgroundColor?: string,
	hackCSS?: string,
}
export interface PrettyStyle extends PrettyStyleProperties {
	dark?: PrettyStyleProperties,
	light?: PrettyStyleProperties,
}

/** Build the `textDecoration` value, appending the hack CSS if present */
const buildTextDecoration = (textDecoration: string | undefined, hackCSS: string | undefined): string | undefined => {
	if (textDecoration)
		return textDecoration + (hackCSS ? '; ' + hackCSS : "");
	if (hackCSS)
		return 'none; ' + hackCSS;
	return undefined;
};

/** Pick only the defined styling properties from a source style */
const definedStyleProperties = (source: PrettyStyleProperties): PrettyStyleProperties => {
	const decoration = buildTextDecoration(source.textDecoration, source.hackCSS);
	const properties: PrettyStyleProperties = {};
	if (source.backgroundColor) properties.backgroundColor = source.backgroundColor;
	if (source.border) properties.border = source.border;
	if (source.color) properties.color = source.color;
	if (decoration) properties.textDecoration = decoration;

	return properties;
};

/** Merge all defined styling properties from the source onto the target, returning a new object */
export function assignStyleProperties<T extends PrettyStyleProperties>(target: T, source: PrettyStyleProperties | undefined): T {
	const defined = source ? definedStyleProperties(source) : {};

	return { ...target, ...defined } as T;
}

/** An individual substitution */
export interface Substitution {
	ugly: RegExp | string, // regular expression (source string or pre-compiled RegExp) describing the text to replace
	pretty: string,      // plain-text symbol to show instead
	pre?: string,        // regular expression guard on text before "ugly"
	post?: string,       // regular expression guard on text after "ugly"
	style?: PrettyStyle, // stylings to apply to the "pretty" text, if specified, or else the ugly text
	scope?: string | string[],      // TextMate scope; if specified, the ugly portion's range must be exactly within the given scope
}

/** The substitution settings for a language (or group of languages) */
export interface LanguageEntry {
	/** language(s) to apply these substitutions on */
	language:  string | string[];
	/** substitution rules */
	substitutions: Substitution[];
	/** A list of TextMate scope prefixes to completely ignore for all substitutions in this language entry. */
	excludedScopes?: string[];
	/** If `true`, combine adjacent tokens if they have the same scope name */
	combineIdenticalScopes: boolean;
	/** try to make pretty-symbol act like a single character */
	adjustCursorMovement?: boolean;
	/** when to unfold a symbol to reveal its underlying text; in response to cursors or selections */
	revealOn?: UglyRevelation;
	/** rendering tweaks to a symbol when in proximity to the cursor */
	prettyCursor?: PrettyCursor;
	/** The filename of the language's grammar. If specified, substitutions' scope entries refer to scope names in the given grammar. If undefined, then search for a grammar.*/
	textMateGrammar?: string;
	/** Override the TextMate scope for the language */
	textMateInitialScope?: string;
}

export type HideTextMethod = "hack-fontSize" | "hack-letterSpacing" | "none";

/** A predefined substitution configuration (a named language entry) */
export type PredefinedConfig = {
	substitutions: Substitution[];
	settings: Partial<LanguageEntry>;
};

/** The settings for `mdPrettify.substitutions`. Every field is optional in
 * the raw host configuration; `reloadConfiguration` fills in defaults before
 * the settings are stored on the root store. */
export interface Settings {
	/** Main substitution settings, each targetting a different set of languages.
	 * If more than one entry matches a document, we will pick the one with the
	 * highest match-score, as determined by vscode.languages.match()
	*/
  substitutions?: LanguageEntry[],
  // Defaults loaded from the top-level settings; applied to language entries that do not specify each property */
	/** try to make pretty-symbol act like a single character */
  adjustCursorMovement?: boolean, 
	/** when to unfold a symbol to reveal its underlying text; in response to cursors or selections */
  revealOn?: UglyRevelation,
	/** rendering tweaks to a symbol when in proximity to the cursor */
  prettyCursor?: PrettyCursor,
	/** */
	hideTextMethod?: HideTextMethod,
	predefinedConfig?: string,
	debug?: boolean,
}

import type * as tm from '../grammar/text-mate';
import { loadGrammar } from '../document/manager';
import { logError, logInfo, logWarn } from './logger';
import { getHost } from './settings';

// The grammar locator bridges the TextMate registry to the host's grammar
// discovery (installed IDE extensions), not a vscode import.
const logLoadGrammarError = (err: unknown): void => logError('loadGrammar:', err);

const injectionScopeNames = (injections: { scopeName: string }[]): string[] => {
  const names: string[] = [];
  for (const injection of injections) names.push(injection.scopeName);
  return names;
};

const resolveGrammarFilePath = (scopeName: string): string => {
  try {
    const file = getHost()?.getGrammarFilePath(scopeName) ?? null;
    if (file) logInfo(`Found grammar for ${scopeName} at ${file}`);
    else logWarn(`No grammar found for ${scopeName}`);
    return file;
  } catch (err) {
    logError(`Error getting file path for ${scopeName}:`, err);
    // Falsy, like the original `undefined` — loadGrammarViaLocator treats any
    // falsy path as "grammar not found".
    return '';
  }
};

const resolveGrammarInjections = (scopeName: string): string[] => {
  logInfo(`Getting injections for ${scopeName}`);
  const injections = getHost()?.getGrammarInjections(scopeName) ?? [];
  if (injections.length > 0) {
    logInfo(`Found injections for ${scopeName}: ${injectionScopeNames(injections).join(', ')}`);
    // fire-and-forget: the registry loads the grammars once the scope names
    // are handed back
    for (const injection of injections) {
      void loadGrammar(injection.scopeName).catch(logLoadGrammarError);
    }
    return injectionScopeNames(injections);
  }
  logInfo(`No injections found for ${scopeName}`);
  return [];
};

export const createGrammarLocator = (): tm.IGrammarLocator => ({
  getFilePath: resolveGrammarFilePath,
  getInjections: resolveGrammarInjections,
});

/**
 * Host event and service types shared across features: document changes,
 * configuration changes, disposables, and the logging output channel.
 */
import type { Range } from '../utils/range';

export interface TextDocumentChange {
  readonly range: Range;
  readonly text: string;
}

export interface ConfigurationChangeEvent {
  affectsConfiguration(section: string): boolean;
}

export interface Disposable {
  dispose(): void;
}

/** A logging sink. The adapter maps this to the IDE's output channel. */
export interface OutputChannel extends Disposable {
  appendLine(value: string): void;
}

import type { TextDocument } from '../host';
import type { LanguageEntry, Substitution } from './configuration';
import { logInfo } from './logger';
import { requireRootStore } from '../store';

/** Substitutions registered programmatically via the public API. */
export const getAdditionalSubstitutions = (): Set<LanguageEntry> => requireRootStore().additionalSubstitutions;

/** Rank a language entry against the document (0 = no match). */
const rankLanguageEntry = (entry: LanguageEntry, doc: TextDocument): { rank: number; entry: LanguageEntry } => ({
  rank: requireRootStore().host?.matchLanguage(entry.language, doc) ?? 0,
  entry,
});

const compareByRankDesc = (x: { rank: number }, y: { rank: number }): number => (x.rank > y.rank ? -1 : x.rank == y.rank ? 0 : 1);

/** Find the best-matching user-defined language entry for the document. */
const findBestUserEntry = (doc: TextDocument): LanguageEntry | undefined => {
  const userRankings = [];
  for (const entry of requireRootStore().settings.substitutions ?? []) {
    const ranked = rankLanguageEntry(entry, doc);
    if (ranked.rank > 0) userRankings.push(ranked);
  }
  userRankings.sort(compareByRankDesc);

  return userRankings.length > 0 ? userRankings[0].entry : undefined;
};

/** Return a copy of the entry with defaults filled in (used by settings reload). */
export const applyDefaultsToEntry = (entry: LanguageEntry): LanguageEntry => {
  const settings = requireRootStore().settings;

  return {
    ...entry,
    revealOn: entry.revealOn ?? settings.revealOn,
    adjustCursorMovement: entry.adjustCursorMovement ?? settings.adjustCursorMovement,
    prettyCursor: entry.prettyCursor ?? settings.prettyCursor,
    combineIdenticalScopes: entry.combineIdenticalScopes ?? true,
  };
};

/** Append `values` to an optional array, treating `undefined` as empty. */
const appendArray = <T,>(target: T[] | undefined, values: T[]): T[] => [...(target ?? []), ...values];

/** Merge the user entry's settings onto a predefined entry, returning a new entry. */
const mergeUserEntry = (baseEntry: LanguageEntry, userEntry: LanguageEntry): LanguageEntry => ({
  ...baseEntry,
  substitutions: userEntry.substitutions?.length ? appendArray(baseEntry.substitutions, userEntry.substitutions) : baseEntry.substitutions,
  revealOn: userEntry.revealOn ?? baseEntry.revealOn,
  adjustCursorMovement: userEntry.adjustCursorMovement ?? baseEntry.adjustCursorMovement,
  prettyCursor: userEntry.prettyCursor ?? baseEntry.prettyCursor,
  combineIdenticalScopes: userEntry.combineIdenticalScopes ?? baseEntry.combineIdenticalScopes,
  excludedScopes: userEntry.excludedScopes ? appendArray(baseEntry.excludedScopes, userEntry.excludedScopes) : baseEntry.excludedScopes,
});

/** Resolve the selected predefined configuration entry for the document, if it matches. */
const resolveSelectedPredefinedEntry = (doc: TextDocument): LanguageEntry | undefined => {
  const selectedPredefinedName = requireRootStore().settings.predefinedConfig;
  if (!selectedPredefinedName || !requireRootStore().predefined.has(selectedPredefinedName)) return undefined;
  const predefinedEntry = requireRootStore().predefined.get(selectedPredefinedName);
  if (!predefinedEntry || (requireRootStore().host?.matchLanguage(predefinedEntry.language, doc) ?? 0) <= 0) return undefined;

  return predefinedEntry;
};

/** Build an entry from the selected predefined configuration, if it matches. */
const getPredefinedEntry = (doc: TextDocument, userEntry: LanguageEntry | undefined): LanguageEntry | undefined => {
  const predefinedEntry = resolveSelectedPredefinedEntry(doc);
  if (!predefinedEntry) return undefined;
  let finalEntry = applyDefaultsToEntry(JSON.parse(JSON.stringify(predefinedEntry))); // deep clone
  if (userEntry) finalEntry = mergeUserEntry(finalEntry, userEntry);

  return finalEntry;
};

/** Collect the substitutions matching the document from the registered additional entries. */
const collectAdditionalSubstitutions = (doc: TextDocument): Substitution[] => {
  const subs: Substitution[] = [];
  for (const language of getAdditionalSubstitutions()) {
    if ((requireRootStore().host?.matchLanguage(language.language, doc) ?? 0) > 0) {
      subs.push(...language.substitutions);
    }
  }

  return subs;
};

/** Build an entry from programmatically registered substitutions alone. */
const getAdditionalOnlyEntry = (doc: TextDocument): LanguageEntry | undefined => {
  if (getAdditionalSubstitutions().size === 0) return undefined;
  const settings = requireRootStore().settings;
  const additionalOnlyEntry: LanguageEntry = {
    language: doc.languageId,
    substitutions: collectAdditionalSubstitutions(doc),
    combineIdenticalScopes: true,
    adjustCursorMovement: settings.adjustCursorMovement,
    revealOn: settings.revealOn,
    prettyCursor: settings.prettyCursor,
  };

  return additionalOnlyEntry;
};

/** Find the best-matching language entry for the document, merging predefined
 * and user configurations if necessary. */
export function getLanguageEntry(doc: TextDocument): LanguageEntry | undefined {
  // 1. Best matching user-defined language entry
  const userEntry = findBestUserEntry(doc);

  // 2. A selected predefined configuration, if it matches this document
  let finalEntry = getPredefinedEntry(doc, userEntry);

  // 3. Fall back to the user entry alone
  if (!finalEntry && userEntry) finalEntry = JSON.parse(JSON.stringify(userEntry));

  // 4. If only registered (programmatic) substitutions apply, build an entry
  if (!finalEntry) finalEntry = getAdditionalOnlyEntry(doc);

  if (!finalEntry) logInfo(`No configuration found for ${doc.languageId} after all checks.`);

  return finalEntry;
}

import type { OutputChannel } from '../host';
import { getRootStore } from '../store';

// All backend logging goes through here — never straight to console.*.
// Before the channel is configured (e.g. at module-load time) the messages
// are dropped except errors, which must always be visible.
export function configureLogger(outputChannel: OutputChannel): void {
  const store = getRootStore();
  if (store) store.loggerChannel = outputChannel;
}

export const logInfo = (message: string): void => {
  const channel = getRootStore()?.loggerChannel;
  if (channel) channel.appendLine(message);
};

export const logWarn = (message: string): void => {
  getRootStore()?.loggerChannel?.appendLine(`[warn] ${message}`);
};

export const logError = (message: string, error?: unknown): void => {
  const detail = error instanceof Error ? error.stack ?? error.message : String(error);
  console.error(message, detail);
  getRootStore()?.loggerChannel?.appendLine(`[error] ${message} ${detail}`);
};

/** Namespaced logger (registry.ts style). */
export const log = {
  info: logInfo,
  warn: logWarn,
  error: logError,
};

import type { Host, OutputChannel } from '../host';
import type { LanguageEntry, Settings } from './configuration';
import { configureLogger, logError, logInfo } from './logger';
import { requireRootStore } from '../store';
import {
  openDocument,
  setTextMateRegistry,
  unloadAllDocuments,
} from '../document/manager';
import { createGrammarLocator } from './grammar-locator';
import { applyDefaultsToEntry } from './language-entry';
export { unloadAllDocuments } from '../document/manager';
/** Raw `mdPrettify` host configuration: the (all-optional) `Settings` fields
 *  plus the predefined configurations map that only the raw config carries. */
interface MdPrettifyConfiguration extends Settings {
  predefinedConfigurations?: { [key: string]: LanguageEntry };
}

const logOpenDocumentError = (err: unknown): void => logError('openDocument:', err);

export function setHost(host: Host): void {
  requireRootStore().host = host;
}

export function getHost(): Host | undefined {
  return requireRootStore().host;
}

export function getOutputChannel(): OutputChannel {
  return requireRootStore().outputChannel;
}

export function getSettings(): Settings {
  return requireRootStore().settings;
}

/** Re-initialize the TextMate registry from the host's grammar locator. */
const reloadTextMateRegistry = (): void => {
  const root = requireRootStore();
  try {
    logInfo('Initializing TextMate registry');
    root.loadedGrammars.clear();
    const registry = root.grammar.createRegistryAction(createGrammarLocator());
    setTextMateRegistry(registry ?? undefined);
    if (!registry) logError('Failed to initialize TextMate registry');
  } catch (err) {
    setTextMateRegistry(undefined);
    logError('Error initializing TextMate registry:', err);
  }
};

/** Store the raw host configuration on the root store as `Settings`. */
const storeSettings = (configuration: MdPrettifyConfiguration): void => {
  requireRootStore().settings = {
    substitutions: configuration.substitutions ?? [],
    revealOn: configuration.revealOn ?? 'cursor',
    adjustCursorMovement: configuration.adjustCursorMovement ?? false,
    prettyCursor: configuration.prettyCursor ?? 'boxed',
    hideTextMethod: configuration.hideTextMethod ?? 'hack-letterSpacing',
    predefinedConfig: configuration.predefinedConfig ?? '',
    debug: configuration.debug ?? false,
  };
};

/** Load predefined configurations from settings.json onto the root store. */
const loadPredefinedConfigurations = (configuration: MdPrettifyConfiguration): void => {
  requireRootStore().predefined.clear();
  const predefinedConfigurations = configuration.predefinedConfigurations ?? {};
  for (const key of Object.keys(predefinedConfigurations)) {
    const entry = predefinedConfigurations[key];
    requireRootStore().predefined.set(key, entry);
    requireRootStore().predefinedConfigs.set(key, { substitutions: entry.substitutions ?? [], settings: entry });
    logInfo(`Loaded predefined config: ${key}`);
  }
};

/** Apply defaults to language properties not specified in the user's substitutions. */
const applyLanguageDefaults = (): void => {
  for (const language of requireRootStore().settings.substitutions ?? []) {
    applyDefaultsToEntry(language);
  }
};

/** Recreate all documents from the host's open text documents. */
const reopenDocuments = (): void => {
  unloadAllDocuments();
  for (const doc of requireRootStore().host?.textDocuments ?? []) {
    logInfo(`Opening document ${doc.fileName}`);
    void openDocument(doc).catch(logOpenDocumentError);
  }
};

/** Re-read the settings and recreate substitutions for all documents. */
export function reloadConfiguration(): void {
  reloadTextMateRegistry();
  const configuration = (requireRootStore().host?.getConfiguration('mdPrettify') ?? {}) as MdPrettifyConfiguration;
  storeSettings(configuration);
  loadPredefinedConfigurations(configuration);
  applyLanguageDefaults();
  reopenDocuments();
}

/** Configure the output channel + logger; called by the adapter at activation. */
export function initialize(host: Host): void {
  setHost(host);
  requireRootStore().outputChannel = host.createOutputChannel('MD Prettify Debug');
  configureLogger(requireRootStore().outputChannel);
  reloadConfiguration();
}

import type { TextEditor, Selection } from '../host';
import { positionIsEqual, selectionFrom } from '../host';
import * as pos from '../utils/position';
import { applyActiveEditorDecorations } from './editor-decorations';
import type { ControllerData } from './type';

const defaultEqual = <T>(x: T, y: T): boolean => x === y;

/** Compares two arrays element-wise using the given equality check. */
const arrayEqual = <T>(a1: T[], a2: T[], isEqual: (x: T, y: T) => boolean = defaultEqual): boolean => {
  if (a1.length != a2.length)
    return false;
  for (let idx = 0; idx < a1.length; ++idx) {
    if (!isEqual(a1[idx], a2[idx]))
      return false;
  }
  return true;
};

/**
 * Adjusts the editor selections so cursors stay on the pretty text after
 * the document changed. Returns the adjusted selections, or null if nothing
 * changed.
 */
const adjustOneSelection = (
  state: ControllerData,
  beforeSel: Selection,
  sel: Selection,
  adjustedSelections: Selection[],
): boolean => {
  const adjusted = pos.adjustCursorMovement(beforeSel.active, sel.active, state.document, state.prettyModel.getPrettySubstitutionsRanges());

  if (!positionIsEqual(adjusted.pos, sel.active)) {
    return true;
  }

  const adjustedAnchor = positionIsEqual(sel.anchor, beforeSel.active) ? adjusted.pos : sel.anchor;
  adjustedSelections.push(selectionFrom(adjustedAnchor, adjusted.pos));
  return false;
};

/** Records the editor's current selections as the baseline for cursor adjustment. */
const seedSelectionRecord = (state: ControllerData, editor: TextEditor): void => {
  state.lastSelections.set(editor, editor.selections);
};

/** Adjusts every selection against its baseline; returns the adjusted list. */
const adjustAllSelections = (
  state: ControllerData,
  before: Selection[],
  after: Selection[],
): Selection[] => {
  const adjustedSelections: Selection[] = [];
  for (let idx = 0; idx < after.length; idx++) {
    const sel = after[idx];
    const beforeSel = before.length > idx ? before[idx] : sel;
    adjustOneSelection(state, beforeSel, sel, adjustedSelections);
  }

  return adjustedSelections;
};

/** Whether any adjusted selection moved away from the editor's current position. */
const anySelectionMoved = (after: Selection[], adjustedSelections: Selection[]): boolean => {
  for (let idx = 0; idx < adjustedSelections.length; idx++) {
    if (!positionIsEqual(after[idx].active, adjustedSelections[idx].active)) return true;
  }

  return false;
};

/** Records the adjusted selections as the new baseline. */
const recordAdjustedSelections = (state: ControllerData, editor: TextEditor, adjustedSelections: Selection[]): void => {
  state.lastSelections.set(editor, adjustedSelections);
};

/** True when the editor's selections are unchanged from the stored baseline. */
const selectionsUnchanged = (editor: TextEditor, before: Selection[]): boolean =>
  arrayEqual(before, editor.selections);

/** Commits the adjusted selections to the editor when any of them moved. */
const commitAdjustedSelections = (state: ControllerData, editor: TextEditor, adjustedSelections: Selection[]): null | Selection[] => {
  if (anySelectionMoved(editor.selections, adjustedSelections)) return state.commitSelections(editor, adjustedSelections);

  return null;
};

export const adjustCursor = (state: ControllerData, editor: TextEditor): null | Selection[] => {
  if (!state.prettyModel || !state.document) return null;
  const before = state.lastSelections.get(editor);
  if (!before) {
    seedSelectionRecord(state, editor);
    return null;
  }
  if (selectionsUnchanged(editor, before)) return null;

  const adjustedSelections = adjustAllSelections(state, before, editor.selections);
  recordAdjustedSelections(state, editor, adjustedSelections);

  return commitAdjustedSelections(state, editor, adjustedSelections);
};

/** The debounced selection update body. */
const runSelectionUpdate = (state: ControllerData, editor: TextEditor): void => {
  if (!state.prettyModel || !state.document || editor.document.uri !== state.document.uri) return;
  if (state.adjustCursorMovement) adjustCursor(state, editor);

  const currentEditorSelections = editor.selections;
  const cursors = state.prettyModel.renderPrettyCursor(currentEditorSelections);
  const cR = cursors == null ? [] : Array.from(cursors.ranges);
  const revealed = state.prettyModel.revealSelections(currentEditorSelections);

  if (!arrayEqual(revealed.ranges, state.revealedRanges) || !arrayEqual(cR, state.cursorRanges)) {
    applyActiveEditorDecorations(
      state,
      [editor],
      Array.from(state.prettyModel.getDecorationsList()),
      revealed.ranges,
      cursors,
    );
    state.revealedRanges = revealed.ranges;
    state.cursorRanges = cR;
  }
};

/** Debounced selection handler: adjusts cursors and re-reveals if the revealed ranges changed. */
export const selectionChanged = (state: ControllerData, editor: TextEditor): void => {
  if (!state.prettyModel || !state.document || editor.document.uri !== state.document.uri) {
    return;
  }

  state.updateSelection.call(function () {
    runSelectionUpdate(state, editor);
  });
};

import type { Substitution } from '../config/configuration';
import * as decorations from '../resolve/ranges';
import type { DocumentData } from './type';
import { getDecorationCacheKey, hasPriorityScopes } from '../resolve/cache';

/** Creates the hide/reveal decoration set for the configured hide-text method. */
const makeHideTextDecorations = (state: DocumentData): { uglyDecoration: NonNullable<DocumentData['hiddenDecoration']>, revealedUglyDecoration: NonNullable<DocumentData['revealedUglyDecoration']>, boxedSymbolDecoration: NonNullable<DocumentData['boxedSymbolDecoration']> } => {
  if (state.hideTextMethod === "hack-fontSize") return decorations.makeDecorationsFontSizeHack(state.host);
  if (state.hideTextMethod === "hack-letterSpacing") return decorations.makeDecorationsLetterSpacingHack(state.host);
  return decorations.makeDecorationsNone(state.host);
};

export const loadDecorations = (state: DocumentData, substitutions: Substitution[]): void => {
  state.unloadDecorations(); // Clear previous state including cache

  const dec = makeHideTextDecorations(state);
  state.hiddenDecoration = dec.uglyDecoration;
  state.revealedUglyDecoration = dec.revealedUglyDecoration;
  state.boxedSymbolDecoration = dec.boxedSymbolDecoration;

  state.prettySubstitutions = new Set();
  for (const subst of substitutions) {
    addSubstitution(state, subst);
  }
};

/** Pre-creates the cache entry for a high-priority rule (decoration itself is created on demand). */
const precacheHighPriorityRule = (state: DocumentData, subst: Substitution, re: RegExp, scope: string | string[]): void => {
  const key = getDecorationCacheKey({
    ugly: re,
    pretty: subst.pretty,
    style: subst.style,
    scope,
  });

  if (!state.decorationCache.has(key)) {
    const newDecoration = decorations.makePrettyDecorationLetterSpacingHack(state.host, {
      ugly: subst.ugly,
      pretty: subst.pretty,
      scope,
      style: subst.style,
    });
    state.decorationCache.set(key, {
      decorationType: newDecoration,
      ranges: new Set(),
      pretty: subst.pretty,
      priority: 2 // Explicitly set high priority
    });
  }
};

/** Compiles one substitution rule, storing it and pre-caching high-priority rules. */
const addSubstitution = (state: DocumentData, subst: Substitution): void => {
  const uglyStr = subst.ugly;
  try {
    const re = new RegExp(uglyStr, "g");
    if (re.test("")) {
      console.warn(`Substitution ignored because it matches the empty string: "${uglyStr}" --> "${subst.pretty}"`);
      return;
    }

    // Auto-add defaultScope to rules that don't specify scopes
    let scopeToUse = subst.scope;
    if (!scopeToUse && state.defaultScope) {
      scopeToUse = [state.defaultScope];
    }

    // Store the raw configuration, decorations will be created on demand and cached
    state.prettySubstitutions.add({
      ugly: re,
      pretty: subst.pretty,
      // No decorationType or ranges here
      style: subst.style,
      scope: scopeToUse, // Use the scope with defaultScope if needed
    });

    // Pre-create cache entry with priority if this is a high-priority rule
    if (subst.pretty && scopeToUse && hasPriorityScopes(scopeToUse)) {
      precacheHighPriorityRule(state, subst, re, scopeToUse);
    }
  } catch (e) {
    console.warn(`Could not add rule "${uglyStr}" --> "${subst.pretty}"; invalid regular expression`)
  }
};

import type { TextDocument, TextEditor, TextDocumentChange, Range } from '../host';
import { rangeIntersection } from '../host';
import type { UpdateDecorationEntry, UpdateDecorationInstanceEntry } from './type';
import { logError, logWarn } from '../config/logger';
import type { ControllerData } from './type';

/** All visible editors showing the controlled document. */
export const getEditors = (state: ControllerData): TextEditor[] => {
  const editors: TextEditor[] = [];
  for (const editor of state.host.visibleTextEditors) {
    if (editor && editor.document && editor.document.uri === state.document?.uri) editors.push(editor);
  }
  return editors;
};

/** Applies one decoration entry's ranges to one editor, skipping revealed ranges. */
const applyDecorationEntry = (state: ControllerData, editor: TextEditor, d: UpdateDecorationEntry, reveal: Range[]): void => {
  if (d && d.decoration) {
    const visible: Range[] = [];
    for (const r of d.ranges) {
      let intersectsReveal = false;
      for (const s of reveal) {
        if (rangeIntersection(s, r) !== null) { intersectsReveal = true; break; }
      }
      if (!intersectsReveal) visible.push(r);
    }
    editor.setDecorations(d.decoration, visible)
  } else {
    logWarn(`Skipping invalid decoration entry in applyActiveEditorDecorations for ${state.document?.uri}`);
  }
};

/** Computes the reveal ranges: explicit ones, or derived from the active editor's selections. */
const computeRevealRanges = (state: ControllerData, prettyModel: NonNullable<ControllerData['prettyModel']>, document: NonNullable<ControllerData['document']>, revealRanges?: Range[]): Range[] => {
  if (revealRanges) return revealRanges;
  const activeEditor = state.host.activeTextEditor;
  const currentSelections = activeEditor?.document?.uri === document.uri
    ? activeEditor.selections
    : [];
  return prettyModel.revealSelections(currentSelections).ranges;
};

/** Applies every decoration entry to one open editor. */
const applyEntriesToEditor = (state: ControllerData, editor: TextEditor, decs: UpdateDecorationEntry[], reveal: Range[]): void => {
  for (const d of decs) {
    applyDecorationEntry(state, editor, d, reveal);
  }
};

/** Whether the editor is usable for decoration updates. */
const isEditorUsable = (editor: TextEditor | undefined): boolean =>
  !!editor && !!editor.document && !editor.document.isClosed;

/** The debounced decoration-application body. */
const runDecorationUpdate = (
  state: ControllerData,
  editors: Iterable<TextEditor>,
  decs: UpdateDecorationEntry[],
  revealRanges?: Range[],
): void => {
  if (!state.prettyModel || !state.document) return;
  try {
    const reveal = computeRevealRanges(state, state.prettyModel, state.document, revealRanges);

    for (const editor of editors) {
      if (!isEditorUsable(editor)) continue;
      applyEntriesToEditor(state, editor, decs, reveal);
    }
  } catch (err) {
    logError(`Error in applyActiveEditorDecorations callback for ${state.document?.uri}:`, err)
  }
};

/** Debounced application of decorations to the given editors plus the active one. */
export const applyActiveEditorDecorations = (
  state: ControllerData,
  editors: Iterable<TextEditor>,
  decs: UpdateDecorationEntry[],
  revealRanges?: Range[],
  _prettyCursors?: UpdateDecorationInstanceEntry,
): void => {
  if (!state.prettyModel || !state.document) return;
  state.updateActiveEditor.call(function () {
    runDecorationUpdate(state, editors, decs, revealRanges);
  });
};

/** Stores the decorations and applies them to the given editors plus the active one. */
export const applyDecorations = (state: ControllerData, editors: Iterable<TextEditor>, decs: UpdateDecorationEntry[]): void => {
  if (!state.prettyModel || !state.document) return;
  state.currentDecorations = decs;
  const activeEditor = state.host.activeTextEditor;
  const editorSet = new Set(editors);
  if (activeEditor && activeEditor.document.uri === state.document.uri) {
    editorSet.add(activeEditor);
  }
  applyActiveEditorDecorations(state, Array.from(editorSet), decs);
};

/** Applies the document changes to the model and reapplies the decorations. */
export const onChangeDocument = (state: ControllerData, document: TextDocument, changes: TextDocumentChange[]): void => {
  if (!state.prettyModel || !state.document || document.uri !== state.document.uri) return;

  state.prettyModel.applyChanges(changes);
  state.prettyModel.recomputeDecorations();

  applyDecorations(state, getEditors(state), Array.from(state.prettyModel.getDecorationsList()));
};

/** Recomputes the decorations and reapplies them to all editors of the document. */
export const refresh = (state: ControllerData): void => {
  if (!state.prettyModel || !state.document) return;
  state.prettyModel.recomputeDecorations();
  applyDecorations(state, getEditors(state), Array.from(state.prettyModel.getDecorationsList()));
};

import type { Host, IGrammar, ITextMateRegistry, TextDocument, TextEditor } from '../host';
import type { ControllerOptions } from './type';
import { logError, logInfo, logWarn } from '../config/logger';
import { getLanguageEntry } from '../config/language-entry';
import { getSettings, getOutputChannel } from '../config/settings';
import { createPrettyDocumentController, type PrettyDocumentController } from '../editor/controller';
import { requireRootStore } from '../store';

/**
 * The document manager: the per-document lifecycle (open, close, unload)
 * and the shared state for all documents (the host, the TextMate registry,
 * the grammar cache, and the open documents), held in the root store.
 */

export function getDocument(doc: TextDocument): PrettyDocumentController | undefined {
  return requireRootStore().documents.get(doc.uri);
}

export function setHost(host: Host): void {
  requireRootStore().host = host;
}

export function setTextMateRegistry(registry: ITextMateRegistry | undefined): void {
  requireRootStore().textMateRegistry = registry;
}

/** Cache for loaded grammars. */
export const loadedGrammars = () => requireRootStore().loadedGrammars;

export async function loadGrammar(scopeName: string): Promise<IGrammar | null> {
  logInfo(`Loading grammar for scope: ${scopeName}`);

  const root = requireRootStore();

  if (!root.textMateRegistry) {
    logWarn(`TextMate registry not available, cannot load grammar for ${scopeName}`);
    return null;
  }

  const cached = root.loadedGrammars.get(scopeName);
  if (cached) {
    logInfo(`Using cached grammar for ${scopeName}`);
    return cached;
  }

  try {
    const grammar = await root.textMateRegistry.loadGrammar(scopeName);
    if (grammar) {
      logInfo(`Successfully loaded grammar for ${scopeName}`);
      root.loadedGrammars.set(scopeName, grammar);
      return grammar;
    }
    logWarn(`Grammar not found for ${scopeName}`);
    return null;
  } catch (err) {
    logError(`Exception in loadGrammar for ${scopeName}:`, err);
    return null;
  }
}

/** Resolves the TextMate scope name for a document, falling back to a language-derived scope. */
const resolveScopeName = (entry: { textMateInitialScope?: string }, host: Host | undefined, languageId: string): string =>
  entry.textMateInitialScope || host?.getLanguageScopeName(languageId) || 'source.' + languageId;

/** Loads the TextMate grammar for a scope, logging and returning null on failure. */
const loadGrammarForScope = async (scopeName: string): Promise<IGrammar | null> => {
  logInfo(`Attempting to load TextMate grammar for scope ${scopeName}`);
  try {
    const grammar = await loadGrammar(scopeName);
    if (!grammar) logWarn(`Could not load TextMate grammar for scope ${scopeName}`);
    return grammar;
  } catch (err) {
    logError(`Error loading TextMate grammar for scope ${scopeName}:`, err);
    return null;
  }
};

/** Create a controller for the given document, loading its grammar first. */
export async function openDocument(doc: TextDocument): Promise<void> {
  const root = requireRootStore();

  if (root.documents.has(doc.uri)) {
    logInfo(`Controller already exists for ${doc.uri}, skipping.`);
    return;
  }

  if (!root.enabled) {
    logInfo(`Pretty symbols disabled, not opening ${doc.fileName}`);
    return;
  }

  const entry = getLanguageEntry(doc);
  if (!entry) {
    logInfo(`No language entry for ${doc.fileName}, not opening`);
    return;
  }

  const settings = getSettings();
  const options: ControllerOptions = {
    hideTextMethod: settings.hideTextMethod,
    textMateGrammar: undefined,
    debug: settings.debug,
    outputChannel: getOutputChannel(),
  };
  options.textMateGrammar = await loadGrammarForScope(resolveScopeName(entry, root.host, doc.languageId));

  // Re-check after the await — another open may have raced us.
  if (root.documents.has(doc.uri)) {
    logInfo(`Controller was created for ${doc.uri} while waiting for grammar, skipping.`);
    return;
  }

  if (doc.isClosed) {
    logInfo(`Document ${doc.uri} closed while loading grammar, aborting.`);
    return;
  }

  try {
    const controller = createPrettyDocumentController(root.host, doc, entry, options);
    root.documents.set(doc.uri, controller);
    logInfo(`Controller created for ${doc.uri}`);
  } catch (err) {
    logError(`Error creating PrettyDocumentController for ${doc.uri}:`, err);
  }
}

export function closeDocument(doc: TextDocument): void {
  try {
    const root = requireRootStore();
    const prettyDoc = root.documents.get(doc.uri);
    if (prettyDoc) {
      prettyDoc.dispose();
      root.documents.delete(doc.uri);
    }
  } catch (e) {
    logError('closeDocument:', e);
  }
}

/** Dispose every controller; used on disable and on configuration reload. */
export function unloadAllDocuments(): void {
  const root = requireRootStore();
  for (const prettyDoc of root.documents.values()) prettyDoc.dispose();
  root.documents.clear();
}

/** Forward the active-editor change to the relevant document, if any. */
export function onActiveEditorChanged(editor: TextEditor | null): void {
  try {
    if (!editor) return;
    requireRootStore().documents.get(editor.document.uri)?.gotFocus(editor);
  } catch (e) {
    logError('onActiveEditorChanged:', e);
  }
}

/** Forward a selection change to the relevant document, if any. */
export function onSelectionChanged(event: { editor: TextEditor }): void {
  try {
    requireRootStore().documents.get(event.editor.document.uri)?.selectionChanged(event.editor);
  } catch (e) {
    logError('onSelectionChanged:', e);
  }
}

import type { TextDocument, Range } from '../host';
import { rangeFrom } from '../host';
import type { DocumentView } from './type';

type DocumentModelData = { document: TextDocument | null };

/** Builds the read-only document view the PrettyModel operates on. */
export const createDocumentModel = (state: DocumentModelData): DocumentView => ({
  getText(range?: Range): string {
    return state.document?.getText(range) ?? '';
  },
  getLine(line: number): string {
    return state.document?.lineAt(line)?.text ?? '';
  },
  getLineRange(line: number): Range {
    return state.document?.lineAt(line)?.range ?? rangeFrom(line, 0, line, 0);
  },
  getLineCount(): number {
    return state.document?.lineCount ?? 0;
  },
  validateRange(range: Range): Range {
    return state.document?.validateRange(range) ?? range;
  },
});

/**
 * The document store: a mobx-state-tree model holding all state of the
 * document feature — the engine state (formerly `PrettyModelData`) plus the
 * per-document controller state. Object literal, no classes.
 *
 * Fields that hold mutable structures (Set/Map/sparse arrays/objects whose
 * properties are reassigned) use a `passthrough` custom type: mst stores the
 * value as-is, so the native methods and in-place mutations keep working.
 */
import { types as t, type Instance, unprotect } from "mobx-state-tree";
import type { Disposable, OutputChannel, Range, Selection, TextDocument, TextEditor, TextEditorDecorationType, DecorationInstanceRenderOptions, IGrammar, StackElement, Host } from "../host";
import { rangeFrom } from "../host";
import type { HideTextMethod, PrettyCursor, UglyRevelation, LanguageEntry } from "../config/configuration";
import type { DebounceFunction } from "../editor/debounce";
import type { DocumentView, PrettySubstitution, UpdateDecorationEntry, UpdateDecorationInstanceEntry, DecorationCacheEntry, PrettyModelOptions } from "./type";
import type { PrettyModel } from "../editor/pretty-model";
import { createPrettyModel } from "../editor/pretty-model";
import { getEditors, applyDecorations, onChangeDocument } from "./editor-decorations";
import { loadDecorations } from "./decorations";
import type { ControllerOptions } from "./type";
import { reparsePretties } from "../reparse/pretties";
import { createDebounce, activeEditorDecorationTimeout, updateSelectionTimeout } from "../editor/debounce";
import {
	applyChanges as applyChangesEngine,
	recomputeDecorations as recomputeDecorationsEngine,
} from "../reparse/apply-changes";
import { chunkedFullReparse } from "../reparse/chunked";
import {
	revealSelections as revealSelectionsEngine,
	renderPrettyCursor as renderPrettyCursorEngine,
	findSymbolsOnLine as findSymbolsOnLineEngine,
} from "../resolve/reveal";
import { getDecoratedText as getDecoratedTextEngine } from "../resolve/decorated-text";
import { passthrough } from "../utils/mst-passthrough";
import { logError, logInfo } from "../config/logger";

/** Keeps only the ranges whose start line is not in the disabled set. */
const filterEnabledRanges = (disabled: Set<number>, ranges: Iterable<Range>): Range[] => {
	const out: Range[] = [];
	for (const r of ranges) {
		if (!disabled.has(r.start.line)) out.push(r);
	}
	return out;
};

export const DocumentStoreModel = t.model("DocumentStore", {
	/** The engine's view of the document: text, line offsets, version. */
	document: passthrough<DocumentView>("document"),
	/** The vscode TextDocument, when the feature is attached to one. */
	textDocument: t.optional(passthrough<TextDocument>("textDocument"), undefined),
	/** The host abstraction over the vscode API. */
	host: passthrough<Host>("host"),

	// --- engine state (formerly PrettyModelData) ---
	prettySubstitutions: passthrough<Set<PrettySubstitution>>("prettySubstitutions"),
	decorationCache: passthrough<Map<string, DecorationCacheEntry>>("decorationCache"),
	hiddeDecorationsRanges: passthrough<Set<Range>>("hiddeDecorationsRanges"),
	lineIndex: passthrough<Map<number, Range[]>>("lineIndex"),
	rangeKeyToCacheKey: passthrough<Map<string, string>>("rangeKeyToCacheKey"),
	changedUglies: t.boolean,
	hiddenDecoration: t.maybeNull(passthrough<TextEditorDecorationType>("hiddenDecoration")),
	revealedUglyDecoration: t.maybeNull(passthrough<TextEditorDecorationType>("revealedUglyDecoration")),
	boxedSymbolDecoration: t.maybeNull(passthrough<DecorationInstanceRenderOptions>("boxedSymbolDecoration")),
	debug: t.boolean,
	outputChannel: passthrough<OutputChannel>("outputChannel"),
	defaultScope: t.string,
	excludedScopes: passthrough<Set<string>>("excludedScopes"),
	hideTextMethod: t.enumeration<HideTextMethod>(["hack-fontSize", "hack-letterSpacing", "none"]),
	revealStrategy: t.enumeration<UglyRevelation>(["cursor", "cursor-inside", "active-line", "selection", "none"]),
	prettyCursor: t.enumeration<PrettyCursor>(["boxed", "none"]),
	disabledLines: passthrough<Set<number>>("disabledLines"),

	// --- per-document controller state ---
	prettyModel: t.maybeNull(t.frozen<PrettyModel>()),
	subscriptions: passthrough<Disposable[]>("subscriptions"),
	currentDecorations: t.array(t.frozen<UpdateDecorationEntry>()),
	updateActiveEditor: passthrough<DebounceFunction>("updateActiveEditor"),
	updateSelection: passthrough<DebounceFunction>("updateSelection"),
	adjustCursorMovement: t.boolean,
	lastSelections: passthrough<Map<TextEditor, Selection[]>>("lastSelections"),
	revealedRanges: t.array(t.frozen<Range>()),
	cursorRanges: t.array(t.frozen<Range>()),
})
// vscode-textmate mutates the grammar object in place (registerRule writes
// `_lastRuleId`), so it must not live in reactive (frozen) state.
// Declared *before* `.actions()` so the action factories' `self` includes it.
.volatile(() => ({
	grammar: null as IGrammar | null,
	grammarState: [] as StackElement[],
}))
.actions((self) => ({
	/** Disposes every cached decoration type and clears the grammar state. */
	disposeModel(): void {
		self.unloadDecorations();
		self.grammarState = []; // Clear grammar state
	},

	/** Disposes all decoration types owned by the model and clears all state. */
	unloadDecorations(): void {
		// Dispose all cached decoration types FIRST
		for (const cacheEntry of self.decorationCache.values()) {
			try {
				cacheEntry.decorationType.dispose();
			} catch (e) {
				console.error("Error disposing cached decoration type:", e);
			}
		}
		self.decorationCache.clear(); // Clear cache map

		// Dispose main hide/reveal decorations
		if (self.hiddenDecoration) {
			try {
				self.hiddenDecoration.dispose();
			} catch (e) {
				console.error("Error disposing hiddenDecoration:", e);
			}
			self.hiddenDecoration = null;
		}
		if (self.revealedUglyDecoration) {
			try {
				self.revealedUglyDecoration.dispose();
			} catch (e) {
				console.error("Error disposing revealedUglyDecoration:", e);
			}
			self.revealedUglyDecoration = null;
		}

		self.hiddeDecorationsRanges.clear();
		self.lineIndex.clear();
		self.rangeKeyToCacheKey.clear();
		self.prettySubstitutions.clear(); // Clear original configs too
		console.log("Unloaded decorations for model instance.");
	},

	/** Writes the adjusted selections back to the editor, falling back on failure. */
	commitSelections(editor: TextEditor, adjustedSelections: Selection[]): Selection[] | null {
		try {
			editor.selections = adjustedSelections;
		} catch (e) {
			logError("Failed to set adjusted selections:", e);
			self.lastSelections.set(editor, editor.selections);
			return null;
		}

		return adjustedSelections;
	},

	/** Clears every decoration type on the editors, disposes the model and all subscriptions. */
	disposeController(): void {
		logInfo(`Disposing PrettyDocumentController for ${self.textDocument?.uri}`);
		if (self.prettyModel) {
			const editors = getEditors(self);
			for (const editor of editors) {
				if (editor && editor.document && !editor.document.isClosed) {
					for (const decorationType of self.prettyModel.getAllDecorationTypes()) {
						try {
							editor.setDecorations(decorationType, []);
						} catch (e) {
							logError(`Error clearing decoration type in editor for ${self.textDocument?.uri}`, e);
						}
					}
				}
			}
			self.prettyModel.dispose();
		}

		for (const s of self.subscriptions) s.dispose();
		self.subscriptions.length = 0;

		self.updateActiveEditor.dispose();
		self.updateSelection.dispose();

		self.prettyModel = null;
		self.currentDecorations = [];
		self.lastSelections.clear();

		logInfo(`Finished disposing PrettyDocumentController for ${self.textDocument?.uri}`);
	},

	/** Creates the pretty model, wires the change subscription, and kicks off the initial decoration pass. */
	initializeController(settings: LanguageEntry, options: ControllerOptions): void {
		const doc = self.textDocument;
		if (!doc) return;
		self.adjustCursorMovement = settings.adjustCursorMovement ?? false;

		self.prettyModel = createPrettyModel(self.host, self.document, settings, {
			hideTextMethod: options.hideTextMethod,
			debug: options.debug,
			textMateGrammar: options.textMateGrammar,
			outputChannel: options.outputChannel,
			languageId: doc.languageId,
			skipInitialReparse: true,
		});

		self.subscriptions.push(self.host.onDidChangeTextDocument(function (doc, changes) {
			if (self.textDocument && doc.uri === self.textDocument.uri) {
				onChangeDocument(self, doc, changes);
			}
		}));

		if (!doc.isClosed) {
			if (doc.lineCount > 500 && self.prettyModel) {
				// Viewport-first: push viewport decorations immediately, then
				// process the rest of the document in background chunks.
				const editors = getEditors(self);
				const viewport = editors[0]?.visibleRanges?.[0];
				void self.prettyModel.reparseViewportFirst(viewport, function () {
					if (self.textDocument?.isClosed) return;
					applyDecorations(self, getEditors(self), Array.from(self.prettyModel?.getDecorationsList() ?? []));
				}, undefined, 3);
			} else {
				applyDecorations(self, getEditors(self), Array.from(self.prettyModel?.getDecorationsList() ?? []));
			}
		}
	},

	/** The decoration entries to apply, skipping lines with pretty symbols disabled. */
	getDecorationsList(): Set<UpdateDecorationEntry> {
		const disabled = self.disabledLines;
		const decs = new Set<UpdateDecorationEntry>();
		for (const cacheEntry of self.decorationCache.values()) {
			const ranges = filterEnabledRanges(disabled, cacheEntry.ranges);
			if (ranges.length > 0) {
				decs.add({ decoration: cacheEntry.decorationType, ranges });
			}
		}
		const hiddenRanges = filterEnabledRanges(disabled, self.hiddeDecorationsRanges);
		if (self.hiddenDecoration && hiddenRanges.length > 0) {
			decs.add({ decoration: self.hiddenDecoration, ranges: hiddenRanges });
		}
		return decs;
	},

	/** Every decoration type the model currently owns (for clearing on dispose). */
	getAllDecorationTypes(): TextEditorDecorationType[] {
		const types: TextEditorDecorationType[] = [];
		if (self.hiddenDecoration) types.push(self.hiddenDecoration);
		if (self.revealedUglyDecoration) types.push(self.revealedUglyDecoration);
		for (const cacheEntry of self.decorationCache.values()) types.push(cacheEntry.decorationType);
		return types;
	},

	/**
	 * Toggles pretty symbols on the given line (0-based). When the line has
	 * symbols, they become hidden (line is "disabled"); otherwise the line
	 * is re-enabled. Returns true if the line was disabled by this call.
	 */
	toggleLine(line: number): boolean {
		const disabledLines = self.disabledLines;
		const disabled = disabledLines.has(line);
		if (disabled) {
			disabledLines.delete(line);
		} else {
			if (findSymbolsOnLineEngine(self, line).length === 0) return false; // nothing to toggle
			disabledLines.add(line);
		}
		recomputeDecorationsEngine(self);
		return disabled;
	},

	/** Applies the document changes to the model. Returns whether anything changed. */
	applyChanges(changes: { range: Range, text: string }[]): boolean {
		if (!self.document) return false;
		return applyChangesEngine(self, changes);
	},

	/** Rebuilds the decoration ranges from the cached substitutions. */
	recomputeDecorations(): void {
		if (!self.document) return;
		recomputeDecorationsEngine(self);
	},

	/**
	 * Async viewport-first reparse: parses the viewport synchronously, then
	 * the rest in background chunks; `onChunkComplete` fires per chunk.
	 */
	reparseViewport(
		viewportRange?: Range,
		onChunkComplete?: (range: Range) => void,
		onComplete?: () => void,
		pushEvery?: number,
	): Promise<void> {
		// No full-document recompute: the store is empty (skipInitialReparse) and the
		// chunked driver fills it viewport-first; a sync recompute would block the host.
		return chunkedFullReparse(self, {
			viewportRange,
			onChunkComplete,
			onComplete,
			pushEvery,
		});
	},

	/** The decoration entry that reveals the pretty symbol under the given selections. */
	revealSelections(selections: Selection[]): UpdateDecorationEntry {
		if (!self.document) return { decoration: undefined as never, ranges: [] };
		return revealSelectionsEngine(self, selections);
	},

	/** The boxed-cursor decoration entry for the pretty symbol under the cursor, if any. */
	renderPrettyCursor(selections: Selection[]): UpdateDecorationInstanceEntry | null {
		if (!self.document) return null;
		return renderPrettyCursorEngine(self, selections);
	},

	/** All pretty symbols on the given line; used by the per-line toggle. */
	findSymbolsOnLine(line: number): Range[] {
		if (!self.document) return [];
		return findSymbolsOnLineEngine(self, line);
	},

	/** The ranges currently hidden by a pretty substitution. */
	getPrettySubstitutionsRanges(): Range[] {
		return Array.from(self.hiddeDecorationsRanges);
	},

	/** The text of the given range with pretty substitutions applied (for copy). */
	getDecoratedText(range: Range): string {
		if (!self.document) return "";
		return getDecoratedTextEngine(self, range);
	},
}));

export type { DocumentStore } from "./type";

/** Builds the document store with the controller-state defaults (no decorations loaded, no reparse). */
const createBaseDocumentStore = (
	host: Host,
	document: DocumentView,
	settings: LanguageEntry,
	options: PrettyModelOptions,
): DocumentStore => DocumentStoreModel.create({
	host,
	document,
	prettySubstitutions: new Set(),
	decorationCache: new Map(),
	hiddeDecorationsRanges: new Set(),
	lineIndex: new Map(),
	rangeKeyToCacheKey: new Map(),
	changedUglies: false,
	hiddenDecoration: null,
	revealedUglyDecoration: null,
	boxedSymbolDecoration: null,
	debug: options.debug,
	outputChannel: options.outputChannel,
	defaultScope: host.getLanguageScopeName(options.languageId) ?? `source.${options.languageId}`,
	excludedScopes: new Set(settings.excludedScopes || []),
	hideTextMethod: options.hideTextMethod,
	revealStrategy: settings.revealOn ?? "cursor",
	prettyCursor: settings.prettyCursor ?? "none",
	disabledLines: new Set(),
	// per-document controller fields: defaults, the controller owns them
	prettyModel: null,
	subscriptions: [],
	currentDecorations: [],
	updateActiveEditor: createDebounce(activeEditorDecorationTimeout),
	updateSelection: createDebounce(updateSelectionTimeout),
	adjustCursorMovement: false,
	lastSelections: new Map(),
	revealedRanges: [],
	cursorRanges: [],
});

/**
 * Creates the document store instance. The only place the document store is
 * created — actions and modules must mutate the existing instance, never build
 * a new one.
 */
export const createDocumentStore = (
	host: Host,
	document: DocumentView,
	settings: LanguageEntry,
	options: PrettyModelOptions,
): DocumentStore => {
	const state = createBaseDocumentStore(host, document, settings, options);
	unprotect(state); // the engine mutates the store in place, outside of actions

	// Volatile (non-reactive) fields: vscode-textmate mutates them in place.
	state.grammar = options.textMateGrammar || null;
	state.grammarState = [];

	loadDecorations(state, settings.substitutions);

	// Parse whole document (skip if the caller will use reparseViewportFirst).
	if (!options.skipInitialReparse) {
		const docRange = rangeFrom(0, 0, document.getLineCount(), 0);
		reparsePretties(state, docRange);
	}

	return state;
};

