	boxedSymbolDecoration: DecorationInstanceRenderOptions | null;
	debug: boolean;
	outputChannel: OutputChannel;
	defaultScope: string;
	excludedScopes: Set<string>;
	hideTextMethod: HideTextMethod;
	revealStrategy: UglyRevelation;
	prettyCursor: PrettyCursor;
	disabledLines: Set<number>;
	grammar: IGrammar | null;
	grammarState: StackElement[];

	// --- actions ---
	disposeModel(): void;
	unloadDecorations(): void;
	commitSelections(editor: TextEditor, adjustedSelections: Selection[]): Selection[] | null;
	disposeController(): void;
	getDecorationsList(): Set<UpdateDecorationEntry>;
	getAllDecorationTypes(): TextEditorDecorationType[];
	toggleLine(line: number): boolean;
	applyChanges(changes: { range: Range; text: string }[]): boolean;
	recomputeDecorations(): void;
	reparseViewport(
		viewportRange?: Range,
		onChunkComplete?: (range: Range) => void,
		onComplete?: () => void,
		pushEvery?: number,
