}

/**
 * The document feature store model: all state of the document feature — the
 * engine state (formerly `PrettyModelData`) plus the per-document controller
 * state. Object literal, no classes. Fields that hold mutable structures
 * (Set/Map/sparse arrays/objects whose properties are reassigned) use a
 * `passthrough` custom type: mst stores the value as-is, so the native
 * methods and in-place mutations keep working.
 */
export const DocumentStoreModel = t.model("DocumentStore", {
	/** The engine's view of the document: text, line offsets, version. */
	document: passthrough<DocumentView>("document"),
	/** The vscode TextDocument, when the feature is attached to one. */
	textDocument: t.optional(passthrough<TextDocument>("textDocument"), undefined),
	/** The host abstraction over the vscode API. */
	host: passthrough<Host>("host"),

	// --- engine state (formerly PrettyModelData) ---
	prettySubstitutions: passthrough<Set<PrettySubstitution>>("prettySubstitutions"),
	decorationCache: passthrough<Map<string, DecorationCacheEntry>>("decorationCache"),
	hiddeDecorationsRanges: passthrough<Set<Range>>("hiddeDecorationsRanges"),
	lineIndex: passthrough<Map<number, Range[]>>("lineIndex"),
	rangeKeyToCacheKey: passthrough<Map<string, string>>("rangeKeyToCacheKey"),
	changedUglies: t.boolean,
	hiddenDecoration: t.maybeNull(passthrough<TextEditorDecorationType>("hiddenDecoration")),
	revealedUglyDecoration: t.maybeNull(passthrough<TextEditorDecorationType>("revealedUglyDecoration")),
	boxedSymbolDecoration: t.maybeNull(passthrough<DecorationInstanceRenderOptions>("boxedSymbolDecoration")),
	debug: t.boolean,
	outputChannel: passthrough<OutputChannel>("outputChannel"),
	defaultScope: t.string,
	excludedScopes: passthrough<Set<string>>("excludedScopes"),
	hideTextMethod: t.enumeration<HideTextMethod>(["hack-fontSize", "hack-letterSpacing", "none"]),
	revealStrategy: t.enumeration<UglyRevelation>(["cursor", "cursor-inside", "active-line", "selection", "none"]),
	prettyCursor: t.enumeration<PrettyCursor>(["boxed", "none"]),
	disabledLines: passthrough<Set<number>>("disabledLines"),

	// --- per-document controller state ---
	prettyModel: t.maybeNull(t.frozen<PrettyModel>()),
	subscriptions: passthrough<Disposable[]>("subscriptions"),
	currentDecorations: t.array(t.frozen<UpdateDecorationEntry>()),
	updateActiveEditor: passthrough<DebounceFunction>("updateActiveEditor"),
	updateSelection: passthrough<DebounceFunction>("updateSelection"),
	adjustCursorMovement: t.boolean,
	lastSelections: passthrough<Map<TextEditor, Selection[]>>("lastSelections"),
	revealedRanges: t.array(t.frozen<Range>()),
	cursorRanges: t.array(t.frozen<Range>()),
});

/**
 * The grammar feature store model: the state of the grammar feature — the
 * Oniguruma WASM library promise, loaded once and shared by every TextMate
 * registry. The promise is non-serializable, so it lives in `volatile`.
 */
export const GrammarStoreModel = t.model("GrammarStore", {});

/** The reparse feature store model: cancellation-token state for reparse runs. */
export const ReparseStoreModel = t.model("ReparseStore", {});

/**
 * The resolve feature store model: the last resolved pretty range and its
 * cache key, recorded when a resolved range is added.
 */
export const ResolveStoreModel = t.model("ResolveStore", {
	/** The range last added via `addResolvedRange`, for observers/tests. */
	lastResolvedRange: t.maybeNull(passthrough<Range>("lastResolvedRange")),
	/** The cache key of the range last added via `addResolvedRange`. */
	lastResolvedCacheKey: t.string,
});

/** The document feature store instance type. */
export type DocumentStore = Instance<typeof DocumentStoreModel>;

/** The grammar feature store instance type. */
export type GrammarStore = Instance<typeof GrammarStoreModel>;

/** The reparse feature store instance type. */
export type ReparseStore = Instance<typeof ReparseStoreModel>;

/** The resolve feature store instance type. */
export type ResolveStore = Instance<typeof ResolveStoreModel>;

import type { Host, Disposable, TextDocument, TextEditor, Selection } from '../host';
import type { LanguageEntry } from '../config/configuration';
import { logInfo } from '../config/logger';
import { createPrettyModel } from './pretty-model';
import type { ControllerData, ControllerOptions } from '../document/type';
import { createDebounce, activeEditorDecorationTimeout, updateSelectionTimeout } from './debounce';
import { createDocumentModel } from '../document/model';
import { getEditors, disposeController, applyDecorations, onChangeDocument, refresh } from '../document/editor-decorations';
import { adjustCursor, selectionChanged } from '../document/cursor';

/** The controller facade: a state bag plus the operations that delegate to the `controller-*` modules. */
export interface PrettyDocumentController extends Disposable {
  gotFocus(editor: TextEditor): void;
  copyDecorated(editor: TextEditor): Promise<void>;
  refresh(): void;
  adjustCursor(editor: TextEditor): null | Selection[];
  selectionChanged(editor: TextEditor): void;
  toggleLine(line: number): boolean;
}

const gotFocusAction = (state: ControllerData, _editor: TextEditor): void => {
  if (!state.prettyModel || !state.document) return;
  applyDecorations(state, getEditors(state), state.currentDecorations);
};

const copyDecoratedAction = (state: ControllerData, editor: TextEditor): Promise<void> => {
  const model = state.prettyModel;
  if (!model || !state.document) return Promise.resolve();
  const copy: string[] = [];
  for (const sel of editor.selections) copy.push(model.getDecoratedText(sel));
  if (copy.length === 0)
    return Promise.resolve();
  else
    return state.host.copyToClipboard(copy.join('\n'));
};

/** Toggles pretty symbols on the given line (0-based). Returns true if the line was disabled. */
const toggleLineAction = (state: ControllerData, line: number): boolean => {
  if (!state.prettyModel) return false;
  const toggled = state.prettyModel.toggleLine(line);
  if (toggled) {
    applyDecorations(state, getEditors(state), Array.from(state.prettyModel.getDecorationsList()));
  }
  return toggled;
};

/** Applies the pretty model's current decorations to all editors. */
const applyCurrentDecorations = (state: ControllerData): void => {
  applyDecorations(state, getEditors(state),
    Array.from(state.prettyModel?.getDecorationsList() ?? []));
};

/** Creates the pretty model, wires the change subscription, and kicks off the initial decoration pass. */
const initializeController = (state: ControllerData, doc: TextDocument, settings: LanguageEntry, options: ControllerOptions): void => {
  state.adjustCursorMovement = settings.adjustCursorMovement ?? false;
  const useAsyncReparse = doc.lineCount > 500;

  state.prettyModel = createPrettyModel(state.host, createDocumentModel(state), settings, {
    hideTextMethod: options.hideTextMethod,
    debug: options.debug,
    textMateGrammar: options.textMateGrammar,
    outputChannel: options.outputChannel,
    languageId: doc.languageId,
    skipInitialReparse: useAsyncReparse,
  });

  state.subscriptions.push(state.host.onDidChangeTextDocument(function (doc, changes) {
    if (state.document && doc.uri === state.document.uri) {
      onChangeDocument(state, doc, changes);
    }
  }));

  if (state.document && !state.document.isClosed) {
    if (useAsyncReparse && state.prettyModel) {
      // Viewport-first: push viewport decorations immediately, then
      // process the rest of the document in background chunks.
      const editors = getEditors(state);
      const viewport = editors[0]?.visibleRanges?.[0];
      void state.prettyModel.reparseViewportFirst(viewport, function () {
        if (state.document?.isClosed) return;
        applyCurrentDecorations(state);
      }, undefined, 3);
    } else {
      applyCurrentDecorations(state);
    }
  }
};

/**
 * Creates the pretty-document controller: a facade over the state bag and
 * the functional modules in `./controller-*`. All logic lives
 * in those modules; this factory only holds the state and delegates.
 */
export const createPrettyDocumentController = (
  host: Host,
  doc: TextDocument,
  settings: LanguageEntry,
  options: ControllerOptions,
): PrettyDocumentController => {
  const state: ControllerData = {
    host,
    document: doc,
    prettyModel: null,
    subscriptions: [],
    currentDecorations: [],
    updateActiveEditor: createDebounce(activeEditorDecorationTimeout),
    updateSelection: createDebounce(updateSelectionTimeout),
    adjustCursorMovement: false,
    debug: options.debug,
    outputChannel: options.outputChannel,
    lastSelections: new Map(),
    revealedRanges: [],
    cursorRanges: [],
  };

  // Skip initialization for the prettify debug output channel
  if (doc.fileName.includes('.md-prettify')) {
    state.adjustCursorMovement = false;
    logInfo(`Skipping PrettyDocumentController initialization for debug channel: ${doc.fileName}`);
  } else {
    initializeController(state, doc, settings, options);
  }

  return {
    dispose() {
      disposeController(state);
    },
    gotFocus(editor) {
      gotFocusAction(state, editor);
    },
    copyDecorated(editor) {
      return copyDecoratedAction(state, editor);
    },
    refresh() {
      refresh(state);
    },
    adjustCursor(editor) {
      return adjustCursor(state, editor);
    },
    selectionChanged(editor) {
      selectionChanged(state, editor);
    },
    toggleLine(line) {
      return toggleLineAction(state, line);
    },
  };
};

import type { Disposable } from '../host';

export const activeEditorDecorationTimeout = 100;
export const updateSelectionTimeout = 20;

/** A debounced callback runner: `call` reschedules, `dispose` cancels. */
export interface DebounceFunction extends Disposable {
  call: (callback: () => void) => void;
}

type DebounceState = {
  timer: ReturnType<typeof setTimeout> | null;
  callback: (() => void) | null;
  timeout: number;
};

/** Creates a debounced callback runner with the given timeout in ms. */
export const createDebounce = (timeout: number): DebounceFunction => {
  const state: DebounceState = { timer: null, callback: null, timeout };
  return {
    call(callback: () => void): void {
      state.callback = callback;
      if (state.timer == null) {
        state.timer = setTimeout(function () {
          state.callback?.();
          state.callback = null;
          state.timer = null;
        }, state.timeout);
      }
    },
    dispose(): void {
      if (state.timer != null) {
        clearTimeout(state.timer);
        state.timer = null;
      }
    },
  };
};

