 *
 * Models the substitutions within a text document
 */
import type { LanguageEntry } from '../config/configuration';
import type { PrettyModelData, PrettyModelOptions, DocumentView, UpdateDecorationEntry, UpdateDecorationInstanceEntry } from '../document/type';
export type { PrettySubstitution, UpdateDecorationEntry, UpdateDecorationInstanceEntry, DocumentView } from '../document/type';

/** The pretty-model facade: a state bag plus the operations that delegate to the `./pretty-model/` modules. */
export interface PrettyModel extends Disposable {
  getDecorationsList(): Set<UpdateDecorationEntry>;
  getAllDecorationTypes(): TextEditorDecorationType[];
  applyChanges(changes: { range: Range, text: string }[]): boolean;
  recomputeDecorations(): void;
  toggleLine(line: number): boolean;
  reparseViewportFirst(
    viewportRange?: Range,
    onChunkComplete?: (range: Range) => void,
    onComplete?: () => void,
    pushEvery?: number,
  ): Promise<void>;
  getPrettySubstitutionsRanges(): Range[];
  getDecoratedText(range: Range): string;
  revealSelections(selections: Selection[]): UpdateDecorationEntry;
  findSymbolsOnLine(line: number): Range[];
  renderPrettyCursor(selections: Selection[]): UpdateDecorationInstanceEntry | null;
}

const disposeModel = (state: PrettyModelData): void => state.disposeModel();

const getDecorationsList = (state: PrettyModelData): Set<UpdateDecorationEntry> =>
  state.getDecorationsList();

const getAllDecorationTypes = (state: PrettyModelData): TextEditorDecorationType[] =>
  state.getAllDecorationTypes();

const applyChanges = (state: PrettyModelData, changes: { range: Range, text: string }[]): boolean =>
  state.applyChanges(changes);

const recomputeDecorations = (state: PrettyModelData): void => state.recomputeDecorations();

const toggleLine = (state: PrettyModelData, line: number): boolean => state.toggleLine(line);

const reparseViewportFirst = (
  state: PrettyModelData,
  viewportRange?: Range,
  onChunkComplete?: (range: Range) => void,
  onComplete?: () => void,
  pushEvery?: number,
): Promise<void> => state.reparseViewport(viewportRange, onChunkComplete, onComplete, pushEvery);

const getPrettySubstitutionsRanges = (state: PrettyModelData): Range[] =>
  state.getPrettySubstitutionsRanges();

const getDecoratedText = (state: PrettyModelData, range: Range): string =>
  state.getDecoratedText(range);

const revealSelections = (state: PrettyModelData, selections: Selection[]): UpdateDecorationEntry =>
  state.revealSelections(selections);

const findSymbolsOnLine = (state: PrettyModelData, line: number): Range[] =>
  state.findSymbolsOnLine(line);

const renderPrettyCursor = (state: PrettyModelData, selections: Selection[]): UpdateDecorationInstanceEntry | null =>
  state.renderPrettyCursor(selections);

/**
 * Creates the pretty-model: a facade over the state bag and the functional
 * modules in `./pretty-model/`. All logic lives in those modules; this
 * factory only holds the state and delegates.
 */
export const createPrettyModel = (
  host: Host,
  doc: DocumentView,
  settings: LanguageEntry,
  options: PrettyModelOptions,
  document = doc,
  hideTextMethod = options.hideTextMethod,
  store: PrettyModelData | undefined = undefined,
): PrettyModel => {
  const state: PrettyModelData = store ?? createDocumentStore(host, document, settings, {
    ...options,
    hideTextMethod,
  });

  return {
    dispose() {
      disposeModel(state);
    },
    getDecorationsList() {
      return getDecorationsList(state);
    },
    getAllDecorationTypes() {
      return getAllDecorationTypes(state);
    },
    applyChanges(changes) {
      return applyChanges(state, changes);
    },
    recomputeDecorations() {
      recomputeDecorations(state);
    },
    toggleLine(line) {
      return toggleLine(state, line);
    },
    reparseViewportFirst(viewportRange, onChunkComplete, onComplete, pushEvery) {
      return reparseViewportFirst(state, viewportRange, onChunkComplete, onComplete, pushEvery);
    },
    getPrettySubstitutionsRanges() {
      return getPrettySubstitutionsRanges(state);
    },
    getDecoratedText(range) {
      return getDecoratedText(state, range);
    },
    revealSelections(selections) {
      return revealSelections(state, selections);
    },
    findSymbolsOnLine(line) {
      return findSymbolsOnLine(state, line);
    },
    renderPrettyCursor(selections) {
      return renderPrettyCursor(state, selections);
    },
  };
};

import * as path from 'path';
import * as fs from 'fs';

import * as oniguruma from 'vscode-oniguruma';
import type { IOnigLib } from 'vscode-textmate';
import { logError, logInfo } from '../config/logger';

// Resolve the wasm via the package itself — works from any install layout
// (pnpm hoisting, the extension bundle, or a plain node_modules).
const wasmPath = (): string => {
  const onigurumaPkg = require.resolve('vscode-oniguruma/package.json');
  return path.join(path.dirname(onigurumaPkg), 'release', 'onig.wasm');
};

// The library object is stable (it only wraps the module's own functions), so
// it lives at module scope and `finishLoad` can be a zero-arg `.then` callback.
const onigLib: IOnigLib = {
  createOnigScanner: oniguruma.createOnigScanner,
  createOnigString: oniguruma.createOnigString,
};

const finishLoad = (): IOnigLib => {
  logInfo('Oniguruma WASM loaded successfully');
  return onigLib;
};

const failLoad = (err: unknown): never => {
  logError('Failed to load Oniguruma WASM:', err);
  throw err;
};

/** Load the Oniguruma WASM library. Pure: no module state — the resulting
 * promise belongs to the caller (the grammar store caches it). */
export const loadOnigLib = (): Promise<IOnigLib> => {
  const wasmFile = wasmPath();
  logInfo(`Loading Oniguruma WASM from ${wasmFile}`);
  if (!fs.existsSync(wasmFile)) {
    logError(`Oniguruma WASM file not found at ${wasmFile}`);
  }
  return oniguruma.loadWASM({ data: fs.readFileSync(wasmFile) }).then(finishLoad).catch(failLoad);
};

import * as fs from 'fs';

import * as vsctm from 'vscode-textmate';
import type { IGrammar, ITextMateRegistry, StackElement } from '../host';
import { log } from '../config/logger';

// Export IGrammarLocator interface for compatibility
export interface IGrammarLocator {
  getFilePath(scopeName: string): string;
  getInjections?(scopeName: string): string[];
}

export interface IGrammarInfo {
  readonly fileTypes: string[];
  readonly name: string;
  readonly scopeName: string;
  readonly firstLineMatch: string;
}

/**
 * Utility to read a file as a promise
 */
const readFile = (path: string): Promise<Buffer> =>
  new Promise<Buffer>(function (resolve, reject) {
    fs.readFile(path, function (error, data) {
      if (error) {
        reject(error);
      } else {
        resolve(data);
      }
    });
  });

// Dummy grammar implementation for when TextMate is not available
const dummyGrammar: IGrammar = {
  tokenizeLine(_lineText: string, prevState: StackElement) {
    return {
      tokens: [],
      ruleStack: prevState,
      stoppedEarly: false,
      fonts: [],
    };
  },
  tokenizeLine2(_lineText: string, _prevState: StackElement | null) {
    return {
      tokens: new Uint32Array(0),
      ruleStack: _prevState ?? vsctm.INITIAL,
      stoppedEarly: false,
      fonts: [],
    };
  },
};

// Loads a grammar for the given scope name via the locator.
const loadGrammarViaLocator = async (locator: IGrammarLocator, scopeName: string): Promise<vsctm.IRawGrammar | null> => {
  try {
    const grammarPath = locator.getFilePath(scopeName);
    if (!grammarPath) {
      log.warn(`Grammar file not found for scope ${scopeName}`);
      return null;
    }

    log.info(`Loading grammar file for ${scopeName} from ${grammarPath}`);
    const data = await readFile(grammarPath);
    return vsctm.parseRawGrammar(data.toString(), grammarPath);
  } catch (err) {
    log.error(`Failed to load grammar for ${scopeName}:`, err);
    return null;
  }
};

// Returns the grammar injection file paths for the given scope name.
const getInjectionsViaLocator = (locator: IGrammarLocator, scopeName: string): string[] => {
  if (locator.getInjections) {
    return locator.getInjections(scopeName);
  }
  return [];
};

// Loads a grammar from an already-created vscode-textmate registry.
const loadGrammarFromRegistry = (registry: vsctm.Registry, scopeName: string): Promise<vsctm.IGrammar> =>
  registry.loadGrammar(scopeName);

// Create TextMate registry with the grammar locator and the loaded WASM library.
export const createRegistry = (locator: IGrammarLocator, onigLibPromise: Promise<vsctm.IOnigLib>): ITextMateRegistry | null => {
  if (!vsctm) {
    log.error('TextMate module not available');
    return null;
  }

  const registry = new vsctm.Registry({
    onigLib: onigLibPromise,
    loadGrammar: function (scopeName: string) {
      return loadGrammarViaLocator(locator, scopeName);
    },
    getInjections: function (scopeName: string) {
      return getInjectionsViaLocator(locator, scopeName);
    },
  });

  return {
    INITIAL: vsctm.INITIAL,
    loadGrammar: function (scopeName: string) {
      return loadGrammarFromRegistry(registry, scopeName);
    },
  };
};

// Helper function to load grammar synchronously for fallback
export const loadGrammarSync = (scopeName: string, filePath: string): IGrammar => {
  try {
    if (!vsctm || !vsctm.parseRawGrammar) {
      return dummyGrammar;
    }

    const content = fs.readFileSync(filePath, 'utf8');
    const raw: unknown = vsctm.parseRawGrammar(content, filePath);
    return raw as IGrammar;
  } catch (err) {
    log.error(`Error loading grammar synchronously: ${err.message}`);
    return dummyGrammar;
  }
};

export const matchScope = (scope: string | string[], scopes: string[]): boolean => {
  if (!scope)
    return true;

  // If scope is an array, check if any of the scope strings match
  if (Array.isArray(scope)) {
    for (const s of scope) {
      if (matchSingleScope(s, scopes)) return true;
    }
    return false;
  }

  return matchSingleScope(scope, scopes);
};

const matchSingleScope = (scope: string, scopes: string[]): boolean => {
  // For better detection of nested scopes:
  // 1. Check whether any of the token scopes fully contains the scope we are looking for
  for (const tokenScope of scopes) {
    if (tokenScope.includes(scope)) {
      return true;
    }
  }

  // 2. Check part by part
  const parts = scope.split(/\s+/);
  for (const part of parts) {
    let found = false;
    for (const tokenScope of scopes) {
      if (tokenScope.includes(part)) {
        found = true;
        break;
      }
    }
    if (!found) {
      return false;
    }
  }

  return true;
};

/**
 * The grammar store: a mobx-state-tree model holding the state of the
 * grammar feature — the Oniguruma WASM library promise, loaded once and
 * shared by every TextMate registry. Object literal, no classes.
 *
 * The promise is non-serializable, so it lives in `volatile`; the loader
 * (`onig-wasm.ts`) is a pure function and `registry.ts` is a pure engine —
 * both receive their inputs as parameters.
 */
import { types as t } from "mobx-state-tree";
import type { IOnigLib } from "vscode-textmate";
import type { ITextMateRegistry } from "../host";
import { loadOnigLib } from "./onig-wasm";
import { createRegistry, type IGrammarLocator } from "./registry";

export const GrammarStoreModel = t.model("GrammarStore", {
})
// The WASM promise is a live, non-serializable value: volatile.
// Declared *before* `.actions()` so the actions' `self` includes it.
.volatile(() => ({
	onigLibPromise: undefined as Promise<IOnigLib> | undefined,
}))
.actions((self) => ({
	/** Load the WASM library once; the promise is cached on the store. */
	loadOnigLib(): Promise<IOnigLib> {
		if (self.onigLibPromise === undefined) {
			self.onigLibPromise = loadOnigLib();
		}
		return self.onigLibPromise;
	},

	/** Build a TextMate registry over the given locator, loading WASM if needed. */
	createRegistryAction(locator: IGrammarLocator): ITextMateRegistry | null {
		const onigLibPromise = self.onigLibPromise ?? (self.onigLibPromise = loadOnigLib());
		return createRegistry(locator, onigLibPromise);
	},
}));

