import type { Range } from '../host';
import { positionFrom, rangeFrom, rangeFromPositions, positionCompare } from '../host';
import * as textUtil from '../utils/text-deltas';
import type { DocumentData } from '../document/type';
import type { RangeDelta } from '../utils/text-deltas';
import { shiftRangeDeltaForSet } from '../resolve/cache';
import { reparsePretties } from './pretties';
import { buildLineIndex, rebuildRangeKeyMap, shiftKeyMapForSet } from '../resolve/range-index';

/** Rebuilds the derived indexes after a bulk mutation of the range sets. */
const rebuildDerivedIndexes = (state: DocumentData): void => {
  state.lineIndex = buildLineIndex(state.hiddeDecorationsRanges);
  state.rangeKeyToCacheKey = rebuildRangeKeyMap(state);
};

const outsideLineRange = (r: Range, startLine: number, endLine: number): boolean =>
  r.start.line < startLine || r.start.line > endLine;

/** Sort document changes by start position, earliest first. */
const compareChangeStart = (change1: { range: Range }, change2: { range: Range }): number =>
  -positionCompare(change1.range.start, change2.range.start);

/** Shifts every decoration range by a single change's delta and updates the derived indexes. */
const applyChangeDelta = (state: DocumentData, change: { range: Range, text: string }): RangeDelta => {
  const delta = textUtil.toRangeDelta(change.range, change.text);
  for (const cacheEntry of state.decorationCache.values()) {
    cacheEntry.ranges = shiftRangeDeltaForSet(cacheEntry.ranges, delta);
  }
  const oldHiddenRanges = state.hiddeDecorationsRanges;
  state.hiddeDecorationsRanges = shiftRangeDeltaForSet(oldHiddenRanges, delta);
  shiftKeyMapForSet(state.rangeKeyToCacheKey, oldHiddenRanges, (r) => textUtil.rangeTranslate(r, delta));
  state.lineIndex = buildLineIndex(state.hiddeDecorationsRanges);
  return delta;
};

/** Removes every range in the set that starts outside the given line range. */
const deleteRangesInLineRange = (ranges: Set<Range>, minLine: number, maxLine: number): void => {
  for (const r of ranges) {
    if (outsideLineRange(r, minLine, maxLine)) {
      ranges.delete(r);
    }
  }
};

/** Computes the line range to reparse after a bulk edit, clamped to the document. */
const reparseLineSpan = (minLine: number, maxLine: number, totalLinesDelta: number, docLineCount: number): [number, number] => {
  const finalMinLine = Math.max(0, minLine);
  const estimatedFinalMaxLine = maxLine + totalLinesDelta;
  const finalEndLine = Math.min(Math.max(0, docLineCount - 1), Math.max(estimatedFinalMaxLine, finalMinLine));
  return [finalMinLine, finalEndLine];
};

/** Clears decoration ranges within a line range and reparses that range. */
const reparseAffectedLines = (state: DocumentData, minLine: number, maxLine: number, totalLinesDelta: number): void => {
  const docLineCount = state.document.getLineCount();
  const [finalMinLine, finalEndLine] = reparseLineSpan(minLine, maxLine, totalLinesDelta, docLineCount);

  if (finalMinLine > finalEndLine) {
    state.changedUglies = false;
    return;
  }

  deleteRangesInLineRange(state.hiddeDecorationsRanges, finalMinLine, finalEndLine);
  for (const cacheEntry of state.decorationCache.values()) {
    deleteRangesInLineRange(cacheEntry.ranges, finalMinLine, finalEndLine);
  }
  rebuildDerivedIndexes(state);

  try {
    const endLineLength = finalEndLine >= 0 && finalEndLine < docLineCount
      ? state.document.getLine(finalEndLine).length
      : 0;
    const reparseRange = rangeFromPositions(positionFrom(finalMinLine, 0), positionFrom(finalEndLine, endLineLength));
    reparsePretties(state, reparseRange);
    state.changedUglies = true;
  } catch (e) {
    console.error("Error during incremental reparse:", e);
    recomputeDecorations(state);
  }
};

/** reparses the document and recreates the highlights for all editors */
export const recomputeDecorations = (state: DocumentData): void => {
  // Clear existing ranges from cache entries and hidden ranges
  for (const entry of state.decorationCache.values()) {
    entry.ranges.clear();
  }
  state.hiddeDecorationsRanges.clear();
  state.lineIndex.clear();
  state.rangeKeyToCacheKey.clear();
  state.grammarState = []; // Reset grammar state

  const docRange = rangeFrom(0, 0, state.document.getLineCount(), 0);
  reparsePretties(state, docRange); // Repopulates ranges in the cache
};

/**
 * Applies document changes to the decoration ranges: shifts all existing
 * ranges by the change deltas, then incrementally reparses the affected lines.
 * @returns true if the decorations were invalidated/updated
 */
export const applyChanges = (state: DocumentData, changes: { range: Range, text: string }[]): boolean => {
  state.changedUglies = false; // assume no changes need to be made for now
  const sortedChanges = changes.sort(compareChangeStart);
  let minAffectedLineInitial = Infinity;
  let maxAffectedLineInitial = -Infinity;
  let totalLinesDelta = 0;

  // First pass: Apply deltas and track initial affected range + total line delta
  for (const change of sortedChanges) {
    try {
      const delta = applyChangeDelta(state, change);

      minAffectedLineInitial = Math.min(minAffectedLineInitial, change.range.start.line);
      maxAffectedLineInitial = Math.max(maxAffectedLineInitial, change.range.end.line);
      totalLinesDelta += delta.linesDelta;
    } catch (e) {
      console.error("Error applying change delta:", e);
      recomputeDecorations(state); // Fallback to full recompute on error
      return true; // Indicate that decorations might have changed due to fallback
    }
  }

  // Second pass: Determine final affected range and reparse
  if (minAffectedLineInitial <= maxAffectedLineInitial) {
    reparseAffectedLines(state, minAffectedLineInitial, maxAffectedLineInitial, totalLinesDelta);
  } else {
    state.changedUglies = false;
  }
  return state.changedUglies;
};

/**
 * Async chunked reparse driver.
 *
 * Strategy: parse the viewport range synchronously (small, ~50–100 lines),
 * then process remaining lines in background chunks yielding via setImmediate
 * so the event loop stays responsive. Each chunk is a contiguous line range
 * sized from the scheduler calibration (effective range ~1024–2048 lines).
 *
 * The existing `reparsePretties` already supports partial reparse via its
 * `lineRange` parameter, so each chunk is a single call to it.
 */
import { reparsePretties } from "./pretties";
import type { DocumentData } from "../document/type";
import type { Range } from "../host";
import { rangeFrom } from "../host";

/** Default chunk size in lines. Calibrated: 2048 lines ≈ 200–400ms with
 *  the real TS grammar + 25 rules. Yields between chunks keep the event
 *  loop responsive. */
export const defaultChunkSize = 2048;

/** Maximum lines to parse synchronously in the viewport pass. The viewport
 *  is typically 50–100 lines; we cap at 500 to be safe for zoomed-out views. */
export const viewportSyncLimit = 500;

export interface ChunkedReparseOptions {
  /** The line range to parse synchronously first (viewport). */
  viewportRange?: Range;
  /** Chunk size for background passes. */
  chunkSize?: number;
  /** Called after a chunk completes with the chunk's line range.
   *  The controller uses this to push incremental decorations.
   *  Throttled by `pushEvery`; the final chunk always fires. */
  onChunkComplete?: (range: Range) => void;
  /** Push decorations every Nth background chunk (default 1 = every chunk).
   *  The viewport sync pass and the final chunk always push regardless. */
  pushEvery?: number;
  /** Called when the full reparse is done. */
  onComplete?: () => void;
  /** If set, the reparse is cancelled when a new token is issued. */
  token?: { cancelled: boolean };
}

/**
 * Runs a full-document reparse in chunks. The viewport range (if provided)
 * is parsed synchronously first; the rest is processed in background chunks
 * with setImmediate yields between them.
 *
 * Returns a Promise that resolves when all chunks are done.
 */
export const chunkedFullReparse = (
  state: DocumentData,
  opts: ChunkedReparseOptions = {},
): Promise<void> => {
  const chunkSize = opts.chunkSize ?? defaultChunkSize;
  const pushEvery = Math.max(1, opts.pushEvery ?? 1);
  const token = opts.token;
  const totalLines = state.document.getLineCount();

  // Determine the viewport sync range.
  let vpStart = 0;
  let vpEnd = 0;
  if (opts.viewportRange) {
    const vr = opts.viewportRange;
    vpStart = Math.max(0, vr.start.line - Math.floor(viewportSyncLimit / 2));
    vpEnd = Math.min(totalLines, vr.end.line + Math.ceil(viewportSyncLimit / 2));
    reparsePretties(state, rangeFrom(vpStart, 0, vpEnd, 0));
    opts.onChunkComplete?.(rangeFrom(vpStart, 0, vpEnd, 0));
  }

  // Build background chunks: everything outside [vpStart, vpEnd).
  const chunks: Range[] = [];
  for (let s = 0; s < vpStart; s += chunkSize) {
    const e = Math.min(s + chunkSize, vpStart);
    chunks.push(rangeFrom(s, 0, e, 0));
  }
  for (let s = vpEnd; s < totalLines; s += chunkSize) {
    const e = Math.min(s + chunkSize, totalLines);
    chunks.push(rangeFrom(s, 0, e, 0));
  }

  // Process chunks asynchronously.
  return processNext(state, chunks, 0, pushEvery, token, opts);
};

/** Processes one chunk, then yields to the event loop before the next. */
const processNext = (
  state: DocumentData,
  chunks: Range[],
  index: number,
  pushEvery: number,
  token: { cancelled: boolean } | undefined,
  opts: ChunkedReparseOptions,
): Promise<void> => {
  if (token?.cancelled) return Promise.resolve();
  if (index >= chunks.length) {
    opts.onComplete?.();
    return Promise.resolve();
  }
  const chunk = chunks[index];
  // Parse this chunk synchronously (blocks for ~200ms at 2048 lines).
  reparsePretties(state, chunk);
  // Throttle decoration pushes: every push re-marshals the ENTIRE growing
  // range list through setDecorations, so pushing after every chunk is
  // O(chunks × totalRanges). Fire on the final chunk unconditionally.
  const isLast = index === chunks.length - 1;
  if (isLast || (index + 1) % pushEvery === 0) {
    opts.onChunkComplete?.(chunk);
  }
  // Yield to the event loop before the next chunk.
  return new Promise<void>(function (resolve) {
    setImmediate(function () {
      if (token?.cancelled) {
        resolve();
        return;
      }
      void processNext(state, chunks, index + 1, pushEvery, token, opts).then(resolve);
    });
  });
};

/**
 * Part-by-part handling of dynamic substitutions.
 *
 * Splits the pretty text on `$N` placeholders and decorates the static parts,
 * mapping each part onto the corresponding segment of the original matched
 * text.
 */

import { positionFrom, rangeFromPositions } from '../host';
import type { DocumentData, PrettySubstitution, DecorationKeyParams } from '../document/type';
import { addResolvedRange } from '../resolve/ranges';
import { logDebug } from './tokenize';

/** Resolves the original-text segment a `$N` placeholder maps to. */
const resolveDynamicPart = (
  match: RegExpMatchArray,
  originalMatchText: string,
  paramIndex: number,
  currentOriginalIndex: number,
  part: string,
): { length: number; nextOriginalIndex: number; log: string } => {
  if (paramIndex >= match.length || match[paramIndex] === undefined) {
    return { length: 0, nextOriginalIndex: currentOriginalIndex, log: `Part '${part}' maps to invalid/unmatched group (Index ${paramIndex})` };
  }
  const groupText = match[paramIndex];
  const groupStartIndex = originalMatchText.indexOf(groupText, currentOriginalIndex);
  if (groupStartIndex === -1) {
    return { length: 0, nextOriginalIndex: currentOriginalIndex, log: `Part '${part}' (group ${paramIndex}) did not find corresponding text starting from index ${currentOriginalIndex}. Original text: "${groupText}"` };
  }
  const groupEndIndex = groupStartIndex + groupText.length;
  return { length: groupText.length, nextOriginalIndex: groupEndIndex, log: `Part '${part}' corresponds to original substring '${groupText}' [${groupStartIndex}-${groupEndIndex}]` };
};

/** Index in the original text where the next placeholder's group text starts, or the end of the match. */
const findNextPlaceholderStart = (
  prettyParts: string[],
  fromIndex: number,
  match: RegExpMatchArray,
  originalMatchText: string,
  currentOriginalIndex: number,
): number => {
  let nextPlaceholderOriginalStart = originalMatchText.length;
  const remainingParts = prettyParts.length - fromIndex;
  for (let j = 0; j < remainingParts; j++) {
    const partIndex = fromIndex + j;
    const nextPlaceholderMatch = prettyParts[partIndex].match(/^\$(\d+)$/);
    if (!nextPlaceholderMatch) continue;
    const nextParamIndex = parseInt(nextPlaceholderMatch[1], 10);
    if (nextParamIndex >= match.length || match[nextParamIndex] === undefined) continue;
    const nextGroupStartIndex = originalMatchText.indexOf(match[nextParamIndex], currentOriginalIndex);
    if (nextGroupStartIndex !== -1) {
      nextPlaceholderOriginalStart = nextGroupStartIndex;
      break;
    }
  }
  return nextPlaceholderOriginalStart;
};

/**
 * Part-by-part handling of complex substitutions with $1, $2, etc.
 * Decorations are created for the static parts, mapped to the corresponding
 * segments of the original matched text.
 */
export const handlePartByPart = (
  state: DocumentData,
  lineIdx: number,
  matchOffset: number,
  configData: PrettySubstitution,
  match: RegExpMatchArray,
  rulePriority: number,
): void => {
  const prettyParts = prettyPartsOf(configData);
  if (prettyParts.length === 0) return;

  processPrettyParts(state, lineIdx, matchOffset, configData, match, rulePriority, prettyParts);
};

/** Splits the pretty text on `$N` placeholders. */
const prettyPartsOf = (configData: PrettySubstitution): string[] => configData.pretty.split(/(\$\d+)/g);

/** Walks the pretty parts, decorating static parts and advancing through the original match. */
const processPrettyParts = (
  state: DocumentData,
  lineIdx: number,
  matchOffset: number,
  configData: PrettySubstitution,
  match: RegExpMatchArray,
  rulePriority: number,
  prettyParts: string[],
): void => {
  const originalMatchText = match[0];
  const processedParts = new Set<string>();
  let currentOriginalIndex = 0;

  for (let i = 0; i < prettyParts.length; i++) {
    const part = prettyParts[i];
    if (part === '') continue;

    const partKey = `${i}:${part}:${currentOriginalIndex}`;
    if (processedParts.has(partKey)) continue;
    processedParts.add(partKey);

    const isDynamicPlaceholder = part.match(/^\$(\d+)$/);

    if (isDynamicPlaceholder) {
      const paramIndex = parseInt(isDynamicPlaceholder[1], 10);
      const resolved = resolveDynamicPart(match, originalMatchText, paramIndex, currentOriginalIndex, part);
      logDebug(state, resolved.log);
      currentOriginalIndex = resolved.nextOriginalIndex;
      continue;
    }

    // Static part of the pretty string.
    const startPos = matchOffset + currentOriginalIndex;
    const previousPart = i > 0 ? prettyParts[i - 1] : null;
    let partOriginalLength: number;
    if (previousPart === '$0') {
      // Preceded by $0: zero-length segment after the full match.
      partOriginalLength = 0;
    } else {
      const nextStart = findNextPlaceholderStart(prettyParts, i + 1, match, originalMatchText, currentOriginalIndex);
      partOriginalLength = Math.max(0, nextStart - currentOriginalIndex);
    }

    const partOriginalText = originalMatchText.substring(currentOriginalIndex, currentOriginalIndex + partOriginalLength);
    const endPos = startPos + partOriginalLength;
    const uglyRange = rangeFromPositions(positionFrom(lineIdx, startPos), positionFrom(lineIdx, endPos));

    const dynamicPartParams: DecorationKeyParams = {
      ugly: configData.ugly,
      pretty: part,
      scope: configData.scope,
      style: configData.style,
    };
    addResolvedRange(state, dynamicPartParams, partOriginalText, part, rulePriority, uglyRange);

    currentOriginalIndex += partOriginalLength;
  }
};

/**
 * Dynamic substitution handling: the pretty text contains `$N` placeholders
 * ($0, $1, ...) that map onto segments of the original matched text.
 *
 * `handlePrettiesWithDynamicParams` is the entry point. It short-circuits the
 * two special cases (whole-match `$0` and single-capture-group replacement)
 * and otherwise falls back to `handlePartByPart` (see dynamic-part-by-part.ts).
 */

import { positionFrom, rangeFromPositions } from '../host';
import type { PrettySubstitution, DocumentData, DecorationKeyParams } from '../document/type';
import { hasPriorityScopes } from '../resolve/cache';
import { addResolvedRange } from '../resolve/ranges';
import { handlePartByPart } from './dynamic-part-by-part';
import { logDebug } from './tokenize';

/**
 * Special case: the pretty text contains only $0 and static text.
 * The whole match is replaced by the resolved text.
 * @returns true when the match was handled and the caller should stop.
 */
const handleDollarZeroOnly = (
  state: DocumentData,
  lineIdx: number,
  matchStart: number,
  matchEnd: number,
  configData: PrettySubstitution,
  match: RegExpMatchArray,
  rulePriority: number,
): boolean => {
  const containsOtherPlaceholders = /\$(?!0\b)\d+/.test(configData.pretty);
  if (containsOtherPlaceholders || !configData.pretty.includes('$0')) return false;

  const uglyRange = rangeFromPositions(positionFrom(lineIdx, matchStart), positionFrom(lineIdx, matchEnd));
  // Calculate the actual pretty text by substituting $0
  const resolvedPretty = configData.pretty.replace('$0', match[0]);

  // Add debug logging specifically for this $0 case
  logDebug(state, ` Part '$0' corresponds to original substring '${match[0]}' [${matchStart}-${matchEnd}]`);

  // Use a cache key specific to the *resolved* text to ensure unique decorations
  const keyParams: DecorationKeyParams = {
    ugly: configData.ugly, // Keep original ugly for context
    pretty: resolvedPretty, // Use RESOLVED pretty text for key
    scope: configData.scope,
    style: configData.style,
  };
  addResolvedRange(state, keyParams, match[0], resolvedPretty, rulePriority, uglyRange);
  return true; // Handled directly, skip the part-by-part logic
};

/**
 * Special case: the pretty text is a single capture-group placeholder (e.g. '$1').
 * The whole match is replaced by that captured group.
 * @returns true when the match was handled and the caller should stop.
 */
const handleWholeMatchCapture = (
  state: DocumentData,
  lineIdx: number,
  matchStart: number,
  matchEnd: number,
  configData: PrettySubstitution,
  match: RegExpMatchArray,
  rulePriority: number,
): boolean => {
  // This handles cases like /\${([^}]+)}/g with pretty: '$1'
  // Where we need to replace the entire matched text with just the captured group
  if (!(configData.pretty.match(/^\$\d+$/) && match.length > 1)) return false;

  // If pretty is just a single placeholder (like '$1')
  const paramIndex = parseInt(configData.pretty.substring(1), 10);
  if (!(paramIndex < match.length && match[paramIndex] !== undefined)) return false;

  const uglyRange = rangeFromPositions(positionFrom(lineIdx, matchStart), positionFrom(lineIdx, matchEnd));
  const capturedGroup = match[paramIndex];

  // Add debug logging for this specific case
  logDebug(state, `Entire match '${match[0]}' being replaced with captured group ${paramIndex}: '${capturedGroup}' [${matchStart}-${matchEnd}]`);

  // Use a cache key specific to the capture group text
  const keyParams: DecorationKeyParams = {
    ugly: configData.ugly,
    pretty: capturedGroup, // Use captured text as the pretty version
    scope: configData.scope,
    style: configData.style,
  };
  addResolvedRange(state, keyParams, match[0], capturedGroup, rulePriority, uglyRange);
  return true; // Handled directly, skip the part-by-part logic
};

/**
 * Handles a single match of a rule whose pretty text contains dynamic parameters
 * ($0, $1, ...). Avoids re-processing the same match on the same line.
 */
export const handlePrettiesWithDynamicParams = (
  state: DocumentData,
  lineIdx: number,
  matchStart: number,
  matchEnd: number,
  configData: PrettySubstitution,
  match: RegExpMatchArray,
  loggedDollarZeroRangesThisLine: Set<string>,
): void => {
  // Determine whether this is a high-priority rule (based on '!' in scopes)
  const isPriorityRule = hasPriorityScopes(configData.scope);
  const rulePriority = isPriorityRule ? 2 : 1;

  // Unique identifier for the match to avoid processing it twice
  const matchId = `${matchStart}:${matchEnd}:${configData.ugly.source}`;
  if (loggedDollarZeroRangesThisLine.has(matchId)) {
    return; // Skip, we already processed this match
  }
  loggedDollarZeroRangesThisLine.add(matchId);

  // --- Special Case: Handle pretties containing only $0 and static text ---
  if (handleDollarZeroOnly(state, lineIdx, matchStart, matchEnd, configData, match, rulePriority)) return;
  // --- End Special Case ---

  // --- Special Case: Handle entire match replacement with capture groups ---
  if (handleWholeMatchCapture(state, lineIdx, matchStart, matchEnd, configData, match, rulePriority)) return;
  // --- End Special Case ---

  // Original logic for handling complex substitutions with $1, $2, etc.
  handlePartByPart(state, lineIdx, matchStart, configData, match, rulePriority);
};

import type { Range } from '../host';
import { positionFrom, rangeFrom, rangeFromPositions, rangeIsEmpty } from '../host';
import * as decorations from '../resolve/ranges';
import type * as tm from '../grammar/text-mate';
import type { PrettySubstitution, DocumentData, LineSegmentData } from '../document/type';
import { getDecorationCacheKey, hasPriorityScopes, addOrUpdatePrettyRange } from '../resolve/cache';
import { refreshTokensOnLine, getLineSegmentsWithScopes, getScopesForRange, classifyRuleScopes, isScopeApplicable } from './tokenize';
import { handlePrettiesWithDynamicParams } from './dynamic';
import { logLineSegments, logExcludedSegment, isSegmentExcluded } from './segments';

/** Collects the rules of the given priority (high-priority scopes end with !). */
const rulesOfPriority = (rules: PrettySubstitution[], highPriority: boolean): PrettySubstitution[] => {
  const out: PrettySubstitution[] = [];
  for (const rule of rules) {
    if (hasPriorityScopes(rule.scope) === highPriority) out.push(rule);
  }

  return out;
};

/** Splits rules into high-priority (scopes ending with !) and normal, high-priority first. */
const rulesInPriorityOrder = (state: DocumentData): PrettySubstitution[] => [
  ...rulesOfPriority(state.prettySubstitutions, true),
  ...rulesOfPriority(state.prettySubstitutions, false),
];

/** Handles a static pretty: ensures the cache entry + decoration exist and adds the range. */
const addStaticPrettyRange = (state: DocumentData, configData: PrettySubstitution, uglyRange: Range): void => {
  const key = getDecorationCacheKey(configData);
  let cacheEntry = state.decorationCache.get(key);
  // High priority (2) if there are scopes ending with !, otherwise normal (1)
  const priority = hasPriorityScopes(configData.scope) ? 2 : 1;

  if (!cacheEntry && configData.pretty) {
    const newDecoration = decorations.makePrettyDecorationLetterSpacingHack(state.host, {
      ugly: `${configData.ugly}`, // Use original ugly regex string for context if needed
      pretty: configData.pretty,
      scope: configData.scope,
      style: configData.style,
    });
    cacheEntry = { decorationType: newDecoration, ranges: new Set(), pretty: configData.pretty, priority };
    state.decorationCache.set(key, cacheEntry);
  } else if (cacheEntry && cacheEntry.priority === undefined) {
    cacheEntry.priority = priority;
  }

  // Add the matched range only when there is a pretty version to show
  if (configData.pretty) {
    addOrUpdatePrettyRange(state, uglyRange, key);
  }
};

/** Applies a rule that passed the scope check: re-scans matches and adds each range. */
const applyApplicableRule = (
  state: DocumentData,
  lineIdx: number,
  configData: PrettySubstitution,
  regexGlobal: RegExp,
  substring: string,
  segmentData: LineSegmentData,
  loggedDollarZeroRangesThisLine: Set<string>,
): void => {
  const hasDynamicParams = /\$\d+/.test(configData.pretty);
  const matchIterator = substring.matchAll(regexGlobal);

  for (const match of matchIterator) {
    if (match.index === undefined || match[0].length === 0) continue;

    const start = segmentData.range.startIndex + match.index;
    const end = start + match[0].length;
    const uglyRange = rangeFromPositions(positionFrom(lineIdx, start), positionFrom(lineIdx, end));
    if (rangeIsEmpty(uglyRange)) continue;

    if (hasDynamicParams) {
      handlePrettiesWithDynamicParams(state, lineIdx, start, end, configData, match, loggedDollarZeroRangesThisLine);
    } else {
      addStaticPrettyRange(state, configData, uglyRange);
    }
  }
};

/** Runs one substitution rule against a segment, adding ranges for applicable matches. */
const processRuleForSegment = (
  state: DocumentData,
  lineIdx: number,
  line: string,
  tokens: tm.IToken[],
  configData: PrettySubstitution,
  segmentData: LineSegmentData,
  loggedDollarZeroRangesThisLine: Set<string>,
): void => {
  const substring = line.substring(segmentData.range.startIndex, segmentData.range.endIndex);
  const regex = configData.ugly;
  if (!(regex instanceof RegExp)) return; // Should not happen, but safe check
  const flags = regex.flags.includes('g') ? regex.flags : regex.flags + 'g'; // matchAll needs 'g'
  const regexGlobal = new RegExp(regex.source, flags);
  const matchIterator = substring.matchAll(regexGlobal);

  for (const match of matchIterator) {
    if (match.index === undefined || match[0].length === 0) continue;

    const startChar = match.index;
    const endChar = startChar + match[0].length;
    const uglyRange = rangeFromPositions(positionFrom(lineIdx, startChar), positionFrom(lineIdx, endChar));
    if (rangeIsEmpty(uglyRange)) continue;

    const matchScopes = getScopesForRange(state, tokens, startChar, endChar);
    const { positiveScopes, negativeScopesByPrefix, highPriorityScopes } = classifyRuleScopes(configData);
    if (!isScopeApplicable(positiveScopes, negativeScopesByPrefix, highPriorityScopes, matchScopes)) continue;

    applyApplicableRule(state, lineIdx, configData, regexGlobal, substring, segmentData, loggedDollarZeroRangesThisLine);
  }
};

/** Processes one line segment: matches all rules against it and adds the resulting ranges. */
const processLineSegment = (
  state: DocumentData,
  lineIdx: number,
  line: string,
  tokens: tm.IToken[],
  segmentData: LineSegmentData,
  loggedDollarZeroRangesThisLine: Set<string>,
): void => {
  const isExcluded = isSegmentExcluded(state, segmentData.scopes);
  if (isExcluded) {
    logExcludedSegment(state, line, segmentData);
    return; // Skip this segment entirely if excluded by the language entry
  }

  for (const configData of rulesInPriorityOrder(state)) {
    processRuleForSegment(state, lineIdx, line, tokens, configData, segmentData, loggedDollarZeroRangesThisLine);
  }
};

// Fills the empty grammarState lines BEFORE the range (forward from the nearest
// filled line, O(gap)) so the first in-range line tokenizes from the right prevState.
const refreshGrammarStateBefore = (state: DocumentData, startLine: number): void => {
  if (!state.grammar || startLine <= 0) return;
  let anchor = startLine - 1;
  while (anchor > 0 && !state.grammarState[anchor]) --anchor;
  for (let lineIdx = anchor + 1; lineIdx < startLine; ++lineIdx) {
    refreshTokensOnLine(state, state.document.getLine(lineIdx), lineIdx);
  }
};

/** Tracks the $0 ranges already logged on the current line. */
const loggedDollarZeroRanges = (): Set<string> => new Set<string>();

/** Processes every segment of one line against the rules. */
const processLineSegments = (
  state: DocumentData,
  lineIdx: number,
  line: string,
  tokens: tm.IToken[],
  lineSegments: Map<string, LineSegmentData>,
  loggedDollarZeroRangesThisLine: Set<string>,
): void => {
  logLineSegments(state, lineIdx, line, lineSegments);

  for (const segmentData of lineSegments.values()) {
    processLineSegment(state, lineIdx, line, tokens, segmentData, loggedDollarZeroRangesThisLine);
  }
};

/** Reparses one line: tokenizes it and processes every segment against the rules. */
const reparseLine = (state: DocumentData, lineIdx: number): void => {
  const line = state.document.getLine(lineIdx);
  const { tokens } = refreshTokensOnLine(state, line, lineIdx);
  const lineSegments = getLineSegmentsWithScopes(line, tokens);

  processLineSegments(state, lineIdx, line, tokens, lineSegments, loggedDollarZeroRanges());
};

/** Reparses the given range (or the whole document) and updates the decoration ranges. */
export const reparsePretties = (state: DocumentData, rangeToReparse?: Range) => {
  rangeToReparse = rangeToReparse || rangeFrom(0, 0, state.document.getLineCount(), 0);
  rangeToReparse = state.document.validateRange(rangeToReparse);

  const lineCount = state.document.getLineCount();
  const startLine = rangeToReparse.start.line;
  const endLine = Math.min(rangeToReparse.end.line, lineCount - 1);

  refreshGrammarStateBefore(state, startLine);

  for (let lineIdx = startLine; lineIdx <= endLine; ++lineIdx) {
    reparseLine(state, lineIdx);
  }

  state.changedUglies = true; // Uglies may have changed; precise tracking could live in addOrUpdatePrettyRange.
};

import { types as t } from 'mobx-state-tree';
import type { IToken } from '../host';
import type { LineSegmentData } from '../document/type';
import { groupAndMergeTokensByScope } from '../grammar/tokens';

export type { ReparseStore } from '../document/type';

export const ReparseStoreModel = t.model('ReparseStore', {})
  .volatile(() => ({ currentToken: undefined as { cancelled: boolean } | undefined }))
  .actions((self) => ({
    /**
     * Creates a cancellation token for a reparse operation and stores it on the
     * store. Call the returned `cancel()` to signal that a new reparse has
     * superseded this one.
     */
    createReparseToken(): { token: { cancelled: boolean }, cancel: () => void } {
      const token = { cancelled: false };
      self.currentToken = token;
      return { token, cancel() { token.cancelled = true; } };
    },
  }));

/** Collects the unique non-empty segments for one range key. */
const segmentsForRangeKey = (
  line: string,
  ranges: { startIndex: number; endIndex: number }[],
): string[] => {
  const segments: string[] = [];

  for (const range of ranges) {
    const segment = line.slice(range.startIndex, range.endIndex);
    if (segment.length > 0 && !segments.includes(segment)) segments.push(segment);
  }

  return segments;
};

export const scopeSetByRangeKey = (
  line: string,
  tokens: IToken[],
): Record<string, string[]> => {
  const scopeSetByRangeKey: Record<string, string[]> = {};

  for (const [rangeKey, ranges] of Object.entries(groupAndMergeTokensByScope(tokens))) {
    scopeSetByRangeKey[rangeKey] = segmentsForRangeKey(line, ranges);
  }

  return scopeSetByRangeKey;
};

export const segmentFromKey = (key: string): LineSegmentData => {
  const [scope, ...rest] = key.split('\n');
  const segment = rest.join('\n');
  return { scope: scope ?? '', segment };
};

export const segmentMapFromScopes = (
  scopeSetByRangeKey: Record<string, string[]>,
): Record<string, LineSegmentData> => {
  const map: Record<string, LineSegmentData> = {};

  for (const [scope, segments] of Object.entries(scopeSetByRangeKey)) {
    for (const segment of segments) {
      const key = `${scope}\n${segment}`;
      if (!(key in map)) map[key] = { scope, segment };
    }
  }

  return map;
};

export const logLineSegments = (
  logger: { debug: (msg: string) => void },
  lineIndex: number,
  line: string,
  tokens: IToken[],
): void => {
  const scopesByRange = groupAndMergeTokensByScope(tokens);

  for (const [scope, ranges] of Object.entries(scopesByRange)) {
    for (const range of ranges) {
      const segment = line.slice(range.startIndex, range.endIndex);
      logger.debug(
        `[line ${lineIndex}] scope=${scope} segment="${segment}" range=[${range.startIndex},${range.endIndex})`,
      );
    }
  }
};

export const logExcludedSegment = (
  logger: { debug: (msg: string) => void },
  lineIndex: number,
  scope: string,
  segment: string,
  reason: string,
): void => {
  logger.debug(
    `[line ${lineIndex}] EXCLUDED scope=${scope} segment="${segment}" reason=${reason}`,
  );
};

export const isSegmentExcluded = (
  scope: string,
  segment: string,
  isHidden: (scope: string) => boolean,
): boolean => {
  const trimmed = segment.trim();
  if (trimmed.length === 0) return true;
  if (trimmed.startsWith('##')) return true;
  if (isHidden(scope)) return true;
  return false;
};

/**
 * The reparse store: a mobx-state-tree model holding the state of the reparse
 * feature — the cancellation token for the in-flight reparse. Object literal,
 * no classes.
 *
 * The per-document reparse engine state (grammar, grammarState, pretty
 * substitutions) lives on the document store; the engine functions in this
 * folder operate on it, and the actions below expose them.
 */
import { types as t, type Instance } from "mobx-state-tree";

export type ReparseStore = Instance<typeof ReparseStoreModel>;

export const ReparseStoreModel = t.model("ReparseStore", {})
.volatile(() => ({ currentToken: undefined as { cancelled: boolean } | undefined }))
.actions((self) => ({
	/**
	 * Creates a cancellation token for a reparse operation and stores it on the
	 * store. Call the returned `cancel()` to signal that a new reparse has
	 * superseded this one.
	 */
	createReparseToken(): { token: { cancelled: boolean }, cancel: () => void } {
		const token = { cancelled: false };
		self.currentToken = token;
		return { token, cancel() { token.cancelled = true; } };
	},
}));

import type { IToken } from '../host';
import type { DocumentData, PrettySubstitution } from '../document/type';
import { scopeSetByRangeKey, segmentMapFromScopes } from './segments';

export const refreshTokensOnLine = (state: DocumentData, line: string, lineNumber: number): { tokens: IToken[], invalidated: boolean } => {
  if (!state.grammar)
    return { tokens: [], invalidated: false };
  try {
    const prevState = state.grammarState[lineNumber - 1] || null;
    const lineTokens = state.grammar.tokenizeLine(line, prevState);
    const invalidated = !state.grammarState[lineNumber] || !lineTokens.ruleStack.equals(state.grammarState[lineNumber])
    state.grammarState[lineNumber] = lineTokens.ruleStack;
    return { tokens: lineTokens.tokens, invalidated: invalidated };
  } catch (err) {
    console.error(`Error when refresh tokens on line '${line}', lineNumber: ${lineNumber}`, err);
    return { tokens: [], invalidated: false };
  }
};

export const getLineSegmentsWithScopes = (line: string, tokens: IToken[]) => {
  return segmentMapFromScopes(scopeSetByRangeKey(line, tokens));
};

/** Collects the scopes of tokens whose span intersects the target character range. */
const collectIntersectingScopes = (
  lineTokens: IToken[],
  targetRangeStartChar: number,
  targetRangeEndChar: number,
): Set<string> => {
  const intersectingScopes = new Set<string>();
  for (const token of lineTokens) {
    if (token.endIndex <= targetRangeStartChar || token.startIndex >= targetRangeEndChar) continue;
    for (const scope of token.scopes) {
      intersectingScopes.add(scope);
    }
  }
  return intersectingScopes;
};

/** Helper function to get all unique scopes intersecting a given character range on a line */
export const getScopesForRange = (state: DocumentData, lineTokens: IToken[], targetRangeStartChar: number, targetRangeEndChar: number): Set<string> => {
  if (!state.grammar || !lineTokens) return new Set<string>();
  const intersectingScopes = collectIntersectingScopes(lineTokens, targetRangeStartChar, targetRangeEndChar);
  if (intersectingScopes.size === 0 && state.defaultScope) {
    intersectingScopes.add(state.defaultScope);
  }
  return intersectingScopes;
};

/**
 * Classifies the scopes of a rule into three groups:
 * - positive: plain scopes the match location must intersect
 * - negative: scopes (without the leading '!') that veto the rule if intersected
 * - high-priority: scopes ending with '!' that bypass the positive match requirement
 */
const ruleScopeList = (configData: PrettySubstitution): unknown[] =>
  configData.scope ? (Array.isArray(configData.scope) ? configData.scope : [configData.scope]) : [];

const isPositiveScope = (scope: unknown): scope is string =>
  typeof scope === 'string' && !scope.startsWith('!') && !scope.endsWith('!');

const isNegativeScope = (scope: unknown): scope is string =>
  typeof scope === 'string' && scope.startsWith('!') && scope.length > 1;

const isHighPriorityScope = (scope: unknown): scope is string =>
  typeof scope === 'string' && scope.endsWith('!');

/** Collects the scopes matching the predicate, applying the per-group normalization. */
const scopeSet = (
  ruleScopes: unknown[],
  matches: (scope: unknown) => scope is string,
  normalize: (scope: string) => string,
): Set<string> => {
  const collected = new Set<string>();
  for (const scope of ruleScopes) {
    if (matches(scope)) collected.add(normalize(scope));
  }

  return collected;
};

const identityScope = (scope: string): string => scope;

const stripLeadingBang = (scope: string): string => scope.substring(1);

const stripTrailingBang = (scope: string): string => scope.substring(0, scope.length - 1);

export const classifyRuleScopes = (configData: PrettySubstitution): {
  positiveScopes: Set<string>,
  negativeScopesByPrefix: Set<string>,
  highPriorityScopes: Set<string>,
} => {
  const ruleScopes = ruleScopeList(configData);

  return {
    positiveScopes: scopeSet(ruleScopes, isPositiveScope, identityScope),
    negativeScopesByPrefix: scopeSet(ruleScopes, isNegativeScope, stripLeadingBang),
    highPriorityScopes: scopeSet(ruleScopes, isHighPriorityScope, stripTrailingBang),
  };
};

/** True when any match scope starts with the given prefix. */
const anyScopeStartsWith = (matchScopes: Set<string>, prefix: string): boolean => {
  for (const matchScope of matchScopes) {
    if (matchScope.startsWith(prefix)) return true;
  }
  return false;
};

/** True when any rule scope matches a match scope by prefix in either direction. */
const anyScopeMatchesEitherDirection = (ruleScopes: Set<string>, matchScopes: Set<string>): boolean => {
  for (const ruleScope of ruleScopes) {
    for (const matchScope of matchScopes) {
      // matchScope starts with ruleScope OR ruleScope starts with matchScope
      if (matchScope.startsWith(ruleScope) || ruleScope.startsWith(matchScope)) return true;
    }
  }
  return false;
};

/**
 * Decides whether a rule applies at a match location, given the scopes intersecting the match.
 * The rule applies when (a high-priority scope matched OR a positive scope matched)
 * AND no negative scope matched.
 */
export const isScopeApplicable = (
  positiveScopes: Set<string>,
  negativeScopesByPrefix: Set<string>,
  highPriorityScopes: Set<string>,
  matchScopes: Set<string>,
): boolean => {
  // High-priority scopes bypass the positive match requirement.
  const hasHighPriorityMatch = [...highPriorityScopes].some((s) => anyScopeStartsWith(matchScopes, s));
  const ruleNeedsPositiveMatch = positiveScopes.size > 0 || highPriorityScopes.size > 0;
  const hasPositiveMatch = hasHighPriorityMatch
    || (ruleNeedsPositiveMatch && positiveScopes.size > 0 && anyScopeMatchesEitherDirection(positiveScopes, matchScopes));
  const hasNegativeMatch = anyScopeMatchesEitherDirection(negativeScopesByPrefix, matchScopes);

  // Apply the rule only if:
  // 1. High-priority condition met OR regular positive condition met AND
  // 2. Negative condition NOT met.
  return (hasHighPriorityMatch || hasPositiveMatch) && !hasNegativeMatch;
};

/** Appends a line to the output channel when debug logging is enabled. */
export const logDebug = (state: DocumentData, message: string): void => {
  if (state.debug && state.outputChannel) state.outputChannel.appendLine(message);
};

import type { Range } from '../host';
import { rangeIntersection, rangeContains, rangeIsEqual } from '../host';
import { mapSet } from '../utils/range';
import * as textUtil from '../utils/text-deltas';
import * as decorations from './ranges';
import type { PrettySubstitution, DocumentData, DecorationKeyParams, DecorationCacheEntry } from '../document/type';
import { indexInsert, indexRemove, overlapCandidates, rangeKey, keyMapRemove } from './range-index';

/**
 * Generates a unique string key for caching decorations based on substitution parameters.
 */
export const getDecorationCacheKey = (params: DecorationKeyParams): string => {
  const scopeStr = Array.isArray(params.scope) ? [...params.scope].sort().join(",") : params.scope || '';
  const styleStr = params.style ? JSON.stringify(Object.entries(params.style).sort()) : '';
  const uglyStr = params.ugly instanceof RegExp ? `${params.ugly.source}|${params.ugly.flags}` : params.ugly;
  // Using a separator unlikely to appear in the strings themselves
  return `${uglyStr}:::${params.pretty}:::${scopeStr}:::${styleStr}`;
};

/** Helper to check if scope array has a priority rule (ends with !) */
export const hasPriorityScopes = (scopeArray?: string | string[]): boolean => {
  if (!scopeArray) return false;

  const scopes = Array.isArray(scopeArray) ? scopeArray : [scopeArray];
  for (const scope of scopes) {
    if (typeof scope === 'string' && scope.endsWith('!')) {
      return true;
    }
  }
  return false;
};

/** Helper to get the priority level of a cache key (based on scopes) */
export const getCacheKeyPriority = (state: DocumentData, cacheKey: string): number => {
  const cacheEntry = state.decorationCache.get(cacheKey);

  // If we already determined the priority for this key, use it
  if (cacheEntry?.priority !== undefined) {
    return cacheEntry.priority;
  }

  // For now, we just have two priority levels:
  // 2 = rule with ! at the end of scope
  // 1 = normal rule
  let foundPriority = 1; // Normal priority by default

  // Find the matching rule and check its priority
  for (const configData of state.prettySubstitutions) {
    const key = getDecorationCacheKey(configData);
    if (key === cacheKey) {
      // Check for a scope ending with !
      if (hasPriorityScopes(configData.scope)) {
        foundPriority = 2; // High priority
      }
      break; // Found the rule, stop searching
    }
  }

  // Store the found priority in the cache for later use
  if (cacheEntry) {
    cacheEntry.priority = foundPriority;
  }

  return foundPriority;
};

/** Helper function to shift ranges in a Set */
export const shiftRangeDeltaForSet = (set: Set<Range>, delta: textUtil.RangeDelta): Set<Range> =>
  mapSet(set, (range) => textUtil.rangeTranslate(range, delta));

/**
 * Compares one existing overlapping range against the new one by priority and
 * containment. Returns 'dominated' when the new range must not be added.
 */
const overlapVerdict = (
  existingRange: Range,
  newRange: Range,
  existingRulePriority: number,
  newRulePriority: number,
): 'dominated' | 'remove' | 'keep' => {
  if (rangeContains(existingRange, newRange) && !rangeIsEqual(existingRange, newRange)) {
    return newRulePriority > existingRulePriority ? 'remove' : 'dominated';
  }
  if (rangeContains(newRange, existingRange)) {
    return newRulePriority >= existingRulePriority ? 'remove' : 'keep';
  }
  if (existingRulePriority > newRulePriority) return 'dominated';
  if (newRulePriority > existingRulePriority) return 'remove';
  return 'keep';
};

/** Collects the existing ranges the new range dominates, or null when dominated itself. */
const collectDominatedRanges = (state: DocumentData, newRange: Range, newCacheKey: string): Set<Range> | null => {
  const newRulePriority = getCacheKeyPriority(state, newCacheKey);
  const rangesToRemove = new Set<Range>();
  for (const existingRange of overlapCandidates(state.lineIndex, state.hiddeDecorationsRanges, newRange)) {
    if (!state.hiddeDecorationsRanges.has(existingRange)) continue;
    if (!rangeIntersection(existingRange, newRange)) continue;
    const existingCacheKey = state.rangeKeyToCacheKey.get(rangeKey(existingRange)) || '';
    const existingRulePriority = getCacheKeyPriority(state, existingCacheKey);
    const verdict = overlapVerdict(existingRange, newRange, existingRulePriority, newRulePriority);
    if (verdict === 'dominated') return null;
    if (verdict === 'remove') rangesToRemove.add(existingRange);
  }
  return rangesToRemove;
};

/** Removes dominated ranges from the active set, derived indexes, and cache entries. */
const removeDominatedRanges = (state: DocumentData, rangesToRemove: Set<Range>): void => {
  for (const r of rangesToRemove) {
    state.hiddeDecorationsRanges.delete(r);
    indexRemove(state.lineIndex, r);
    keyMapRemove(state.rangeKeyToCacheKey, [r]);
  }
  for (const entry of state.decorationCache.values()) {
    for (const r of rangesToRemove) {
      entry.ranges.delete(r);
    }
  }
};

/** Finds the substitution whose cache key matches, if any. */
const findSubstitutionByKey = (state: DocumentData, cacheKey: string): PrettySubstitution | undefined => {
  for (const sub of state.prettySubstitutions) {
    if (getDecorationCacheKey(sub) === cacheKey) return sub;
  }
  return undefined;
};

/** Returns the cache entry for the key, creating a placeholder entry when missing. */
const getOrCreateCacheEntry = (state: DocumentData, cacheKey: string): DecorationCacheEntry | undefined => {
  const existing = state.decorationCache.get(cacheKey);
  if (existing) return existing;
  console.warn(`Cache entry not found for key ${cacheKey} when adding range. Creating placeholder.`);
  const configData = findSubstitutionByKey(state, cacheKey);
  if (!configData || !configData.pretty) {
    console.error(`Could not create cache entry for ${cacheKey}. Range not added to cache.`);
    return undefined;
  }
  const newDecoration = decorations.makePrettyDecorationLetterSpacingHack(state.host, {
    ugly: `${configData.ugly}`,
    pretty: configData.pretty,
    scope: configData.scope,
    style: configData.style,
  });
  const entry: DecorationCacheEntry = { decorationType: newDecoration, ranges: new Set(), pretty: configData.pretty };
  state.decorationCache.set(cacheKey, entry);
  return entry;
};

/**
 * Adds a new range for a pretty substitution, handling overlaps by priority:
 * a higher-priority range replaces the one it contains; a lower-priority range
 * is ignored when contained. Partial overlaps are resolved by priority too.
 *
 * Overlap candidates come from the derived line index (`state.lineIndex`), so
 * this is O(k) in ranges on the overlapping lines instead of O(M) in all
 * active ranges; the owning cache key is read from `state.rangeKeyToCacheKey`.
 */
export const addOrUpdatePrettyRange = (state: DocumentData, newRange: Range, newCacheKey: string): void => {
  const rangesToRemove = collectDominatedRanges(state, newRange, newCacheKey);
  if (rangesToRemove === null) return; // Do not add this new range

  removeDominatedRanges(state, rangesToRemove);

  // Add the new range (it wasn't dominated)
  state.hiddeDecorationsRanges.add(newRange);
  indexInsert(state.lineIndex, newRange);

  // Add the new range to its corresponding cache entry, creating it if missing
  const cacheEntry = getOrCreateCacheEntry(state, newCacheKey);
  if (!cacheEntry) return; // Cannot add to cache if entry cannot be ensured

  cacheEntry.ranges.add(newRange);
  // Record the owning cache key only once the range is in the cache entry,
  // mirroring the old map (which was rebuilt from cache entries ∩ active set).
  state.rangeKeyToCacheKey.set(rangeKey(newRange), newCacheKey);
};

import type { Range } from '../host';
import type { DocumentData } from '../document/type';
import { findSymbolsIn } from './lookup';

/**
 * Returns what the contents of the document would appear to be after decorations
 * (i.e. with substitutions applied to the text) for the given range.
 *
 * Linear algorithm: builds a line-offset table by scanning newlines in
 * originalText (O(totalTextLength)), computes each substitution's offsets
 * in O(1), then assembles the result in a single forward pass.
 * Total: O(M log M + totalTextLength) where M = number of active ranges.
 */
/**
 * Converts a document position to an offset within `originalText`, using the
 * precomputed line-offset table. Returns -1 when the position is outside the
 * range or beyond the text.
 */
const toOffset = (range: Range, lineCount: number, offsetOfLine: number[], textLength: number, line: number, character: number): number => {
  const relLine = line - range.start.line;
  if (relLine < 0 || relLine > lineCount - 1) return -1;
  if (relLine === 0) {
    const offset = character - range.start.character;
    return offset >= 0 ? offset : -1;
  }
  const offset = offsetOfLine[relLine] + character;
  return offset <= textLength ? offset : -1;
};

type SubstitutionSpan = { start: number, end: number, subst: string };

/**
 * Builds a line-offset table: offsetOfLine[i] = character offset within
 * originalText where line (range.start.line + i) begins.
 */
const lineOffsetTable = (range: Range, originalText: string): number[] => {
  const lineCount = range.end.line - range.start.line + 1;
  const offsetOfLine = new Array<number>(lineCount + 1);
  offsetOfLine[0] = 0;
  let scanPos = 0;
  for (let i = 0; i < lineCount; i++) {
    const nlIdx = originalText.indexOf('\n', scanPos);
    if (nlIdx === -1) {
      offsetOfLine[i + 1] = originalText.length;
      for (let j = i + 2; j <= lineCount; j++) offsetOfLine[j] = originalText.length;
      break;
    }
    scanPos = nlIdx + 1;
    offsetOfLine[i + 1] = scanPos;
  }

  return offsetOfLine;
};

/** Collects the spans of the active substitutions, sorted by start (longer first on ties). */
const collectSubstitutionSpans = (
  state: DocumentData,
  range: Range,
  originalText: string,
  offsetOfLine: number[],
  activeHiddenRanges: Set<Range>,
): SubstitutionSpan[] => {
  const lineCount = range.end.line - range.start.line + 1;
  const subs: SubstitutionSpan[] = [];

  for (const cacheEntry of state.decorationCache.values()) {
    for (const sr of cacheEntry.ranges) {
      if (!activeHiddenRanges.has(sr)) continue;
      const start = toOffset(range, lineCount, offsetOfLine, originalText.length, sr.start.line, sr.start.character);
      const end = toOffset(range, lineCount, offsetOfLine, originalText.length, sr.end.line, sr.end.character);
      if (start !== -1 && end !== -1 && start < end) {
        subs.push({ start, end, subst: cacheEntry.pretty });
      }
    }
  }

  // Sort by start offset ascending; for equal starts, longer range first
  // (outer range wins in the overlap skip below).
  subs.sort(compareSubstitutionSpans);

  return subs;
};

/** Sorts by start offset ascending; for equal starts, longer range first. */
const compareSubstitutionSpans = (a: SubstitutionSpan, b: SubstitutionSpan): number =>
  a.start - b.start || (b.end - b.start) - (a.end - a.start);

/** Single forward pass: appends unchanged text segments + substitution text. */
const decoratedTextParts = (originalText: string, subs: SubstitutionSpan[]): string[] => {
  const parts: string[] = [];
  let cursor = 0;
  for (const s of subs) {
    if (s.start < cursor) continue; // overlaps previous — skip
    if (s.start > cursor) parts.push(originalText.slice(cursor, s.start));
    parts.push(s.subst);
    cursor = s.end;
  }
  if (cursor < originalText.length) parts.push(originalText.slice(cursor));

  return parts;
};

/** The active hidden ranges (pretty symbols) intersecting the given range. */
const activeHiddenRanges = (state: DocumentData, range: Range): Set<Range> => findSymbolsIn(state, range);

/** The substitution spans for the text of the given range. */
const substitutionSpans = (state: DocumentData, range: Range, originalText: string): SubstitutionSpan[] =>
  collectSubstitutionSpans(state, range, originalText, lineOffsetTable(range, originalText), activeHiddenRanges(state, range));

/** Assembles the decorated text from the original text and its substitution spans. */
const decoratedTextFor = (originalText: string, subs: SubstitutionSpan[]): string =>
  decoratedTextParts(originalText, subs).join('');

export const getDecoratedText = (state: DocumentData, range: Range): string => {
  if (!state.document) return '';
  range = state.document.validateRange(range);
  const originalText = state.document.getText(range);

  return decoratedTextFor(originalText, substitutionSpans(state, range, originalText));
};

import type { Position, Range } from '../host';
import { rangeContains, positionIsEqual, rangeIntersection } from '../host';
import type { DocumentData } from '../document/type';

const isPositionAtStart = (range: Range, pos: Position): boolean => positionIsEqual(range.start, pos);
const isPositionAtEnd = (range: Range, pos: Position): boolean => positionIsEqual(range.end, pos);

/**
 * Checks whether a position is contained in a range with the given edge-inclusion options.
 */
const rangeContainsPosition = (range: Range, pos: Position, options: { excludeStart: boolean, includeEnd: boolean }): boolean => {
  const contained = rangeContains(range, pos);
  const atStart = isPositionAtStart(range, pos);
  const atEnd = isPositionAtEnd(range, pos);

  if (options.excludeStart) {
    if (options.includeEnd) {
      return contained && !atStart;
    }
    return contained && !atStart && !atEnd;
  }
  if (options.includeEnd) {
    return contained || atEnd;
  }
  return contained;
};

/**
 * Finds the hidden range containing the given position.
 */
export const findSymbolAt = (state: DocumentData, pos: Position, options: { excludeStart?: boolean, includeEnd?: boolean } = { excludeStart: false, includeEnd: false }): Range | undefined => {
  for (const range of state.hiddeDecorationsRanges) {
    if (rangeContainsPosition(range, pos, { excludeStart: options.excludeStart, includeEnd: options.includeEnd })) {
      return range;
    }
  }
  return undefined;
};

/**
 * Finds all hidden ranges overlapping the given range.
 */
export const findSymbolsIn = (state: DocumentData, range: Range): Set<Range> => {
  const overlappingRanges = new Set<Range>();
  state.hiddeDecorationsRanges.forEach((hiddenRange) => {
    if (rangeIntersection(range, hiddenRange)) { // Check for intersection (overlap)
      overlappingRanges.add(hiddenRange);
    }
  });
  return overlappingRanges;
};

/**
 * Derived indexes over `state.hiddeDecorationsRanges` (the source of truth).
 *
 * `addOrUpdatePrettyRange` used to scan every active range per call (O(M²)
 * over a reparse). These structures make that scan O(k), where k is the
 * number of ranges whose line span overlaps the new range's:
 *  - `lineIndex`  — Map<start.line, Range[]> for overlap candidate lookup
 *  - `rangeKeyToCacheKey` — Map<rangeKey, cacheKey> so the owning rule's
 *    priority can be read without rebuilding a map over all cache entries
 *
 * Ranges are immutable value objects, so identity (===) works for removal.
 */
import type { Range } from '../host';
import type { DocumentData } from '../document/type';

/** String key identifying a range by its exact start/end positions. */
export const rangeKey = (r: Range): string =>
  `${r.start.line}:${r.start.character}-${r.end.line}:${r.end.character}`;

/** Builds the line index from a set of ranges (bulk rebuild). */
export const buildLineIndex = (set: Set<Range>): Map<number, Range[]> => {
  const index = new Map<number, Range[]>();
  for (const r of set) {
    indexInsert(index, r);
  }
  return index;
};

/** Inserts a single range into the line index (incremental maintenance). */
export const indexInsert = (index: Map<number, Range[]>, r: Range): void => {
  let bucket = index.get(r.start.line);
  if (!bucket) {
    bucket = [];
    index.set(r.start.line, bucket);
  }
  bucket.push(r);
};

/** Removes a single range from the line index (incremental maintenance). */
export const indexRemove = (index: Map<number, Range[]>, r: Range): void => {
  const bucket = index.get(r.start.line);
  if (!bucket) return;
  const i = bucket.indexOf(r);
  if (i === -1) return;
  bucket.splice(i, 1);
  if (bucket.length === 0) index.delete(r.start.line);
};

/**
 * Ranges in the index whose line span overlaps the given range's line span.
 * A range starting on line L can intersect `r` only if L is in
 * [r.start.line, r.end.line]. Multi-line ranges are rare, so the bucket scan
 * is capped; beyond the cap we fall back to the full set (still correct).
 *
 * Note: the overlap/priority outcome in `addOrUpdatePrettyRange` is
 * order-independent — a `break` only fires when the new range is rejected,
 * in which case the accumulated removals are discarded — so bucket order
 * does not affect the final set of active ranges.
 */
/** Full-set fallback when the range's line span exceeds the bucket cap. */
const allRanges = (set: Set<Range>): Range[] => [...set];

/** Appends one index bucket's ranges to the candidate list. */
const appendBucket = (out: Range[], bucket: Range[] | undefined): void => {
  if (bucket) out.push(...bucket);
};

/** Collects the candidate ranges from the index buckets the range spans. */
const bucketCandidates = (index: Map<number, Range[]>, r: Range): Range[] => {
  const out: Range[] = [];
  for (let line = r.start.line; line <= r.end.line; line++) appendBucket(out, index.get(line));

  return out;
};

export const overlapCandidates = (
  index: Map<number, Range[]>,
  set: Set<Range>,
  r: Range,
  maxBuckets = 64,
): Range[] => {
  const span = r.end.line - r.start.line;
  if (span >= maxBuckets) return allRanges(set);

  return bucketCandidates(index, r);
};

/**
 * Rebuilds `rangeKeyToCacheKey` from the cache: for every cache entry, each
 * of its ranges that is also active (in `hiddeDecorationsRanges`) maps its
 * range key to the entry's cache key.
 */
export const rebuildRangeKeyMap = (
  state: Pick<DocumentData, 'decorationCache' | 'hiddeDecorationsRanges'>,
): Map<string, string> => {
  const map = new Map<string, string>();
  for (const [key, entry] of state.decorationCache.entries()) {
    for (const existingRange of entry.ranges) {
      if (state.hiddeDecorationsRanges.has(existingRange)) {
        map.set(rangeKey(existingRange), key);
      }
    }
  }
  return map;
};

/** Maintains the range->key map while shifting a set by a delta (per range). */
export const shiftKeyMapForSet = (
  map: Map<string, string>,
  set: Set<Range>,
  shift: (r: Range) => Range,
): void => {
  for (const r of set) {
    const k = rangeKey(r);
    const key = map.get(k);
    if (key !== undefined) {
      map.delete(k);
      map.set(rangeKey(shift(r)), key);
    }
  }
};

/** Removes the given ranges' keys from the range->key map. */
export const keyMapRemove = (map: Map<string, string>, ranges: Iterable<Range>): void => {
  for (const r of ranges) map.delete(rangeKey(r));
};

import type { Range, Host, DecorationRenderOptions } from '../host';
import { DecorationRangeBehavior } from '../host';
import type { Substitution } from '../config/configuration';
import { assignStyleProperties } from '../config/configuration';
import type { DocumentData, DecorationKeyParams } from '../document/type';
import { getDecorationCacheKey, addOrUpdatePrettyRange } from './cache';

export function makePrettyDecorationLetterSpacingHack(host: Host, prettySubst: Substitution) {
  // const showAttachmentStyling = '; font-size: 10em; letter-spacing: normal; visibility: visible';
  const showAttachmentStyling = 'letter-spacing: normal; visibility: visible;';

  let styling: DecorationRenderOptions = {
    after: {},
    dark: { after: {} },
    light: { after: {} },
    rangeBehavior: DecorationRangeBehavior.ClosedClosed,
  };

  if (prettySubst.style) {
    styling.after = assignStyleProperties(styling.after, prettySubst.style);
    if (prettySubst.style.dark)
      styling.dark.after = assignStyleProperties(styling.dark.after, prettySubst.style.dark);
    if (prettySubst.style.light)
      styling.light.after = assignStyleProperties(styling.light.after, prettySubst.style.light);
  }
  styling.after.contentText = prettySubst.pretty;

  // Use a dirty hack to change the font size (code injection)
  styling.after.textDecoration = showAttachmentStyling + (styling.after.textDecoration || 'none;');
  // and make sure the user's textDecoration does not break our hack
  if (styling.light.after.textDecoration)
    styling.light.after.textDecoration = showAttachmentStyling + styling.light.after.textDecoration;
  if (styling.dark.after.textDecoration)
    styling.dark.after.textDecoration = showAttachmentStyling + styling.dark.after.textDecoration;

  return host.createDecorationType(styling);
}

export function makePrettyDecorationNoPretty(host: Host, prettySubst: Substitution) {
  let styling: DecorationRenderOptions = {
    dark: {},
    light: {},
    rangeBehavior: DecorationRangeBehavior.ClosedClosed,
  };
  if (prettySubst.style) {
    styling = assignStyleProperties(styling, prettySubst.style);
    if (prettySubst.style.dark)
      styling.dark = assignStyleProperties(styling.dark, prettySubst.style.dark);
    if (prettySubst.style.light)
      styling.light = assignStyleProperties(styling.light, prettySubst.style.light);
  }

  return host.createDecorationType(styling);
}

export function makeDecorationsFontSizeHack(host: Host) {
  return {
    uglyDecoration: host.createDecorationType({
      textDecoration: 'none; font-size: 0.001em',
      rangeBehavior: DecorationRangeBehavior.ClosedClosed,
    }),
    revealedUglyDecoration: host.createDecorationType({
      textDecoration: 'none; font-size: inherit !important',
      rangeBehavior: DecorationRangeBehavior.ClosedClosed,
      after: {
        textDecoration: 'none; font-size: 0pt',
      }
    }),
    boxedSymbolDecoration: {
      rangeBehavior: DecorationRangeBehavior.ClosedClosed,
      after: {
        border: '0.1em solid',
        margin: '-0em -0.05em -0em -0.1em',
      }
    },
  }
}

export function makeDecorationsLetterSpacingHack(host: Host) {
  return {
    uglyDecoration: host.createDecorationType({
      letterSpacing: "-0.55em; font-size: 0.1em; visibility: hidden",
      rangeBehavior: DecorationRangeBehavior.ClosedClosed,
