/**
 * Creates the cache entry (and decoration) for a resolved pretty text if missing,
 * ensuring the priority is set, and adds the range with overlap handling.
 */
export const addResolvedRange = (
  state: DocumentData,
  params: DecorationKeyParams,
  uglyContext: string,
  resolvedPretty: string,
  rulePriority: number,
  uglyRange: Range,
): void => {
  const key = getDecorationCacheKey(params);
  let cacheEntry = state.decorationCache.get(key);

  if (!cacheEntry) {
    const newDecoration = makePrettyDecorationLetterSpacingHack(state.host, {
      ugly: uglyContext,
      pretty: resolvedPretty,
      scope: params.scope,
      style: params.style,
    });
    cacheEntry = { decorationType: newDecoration, ranges: new Set(), pretty: resolvedPretty, priority: rulePriority };
    state.decorationCache.set(key, cacheEntry);
  } else if (cacheEntry.priority === undefined) {
    // Set the priority if it has not been determined yet
    cacheEntry.priority = rulePriority;
  }

  addOrUpdatePrettyRange(state, uglyRange, key);
};

import type { Range, Selection } from '../host';
import { rangeFromPositions } from '../host';
import { mapSet } from '../utils/range';
import type { DocumentData, UpdateDecorationEntry, UpdateDecorationInstanceEntry } from '../document/type';
import { findSymbolAt, findSymbolsIn } from './lookup';

type GetRanges = (sel: Selection) => Range | Set<Range> | undefined;
type GetRange = (sel: Selection) => Range | undefined;

/** Normalizes a single getRanges result into an iterable of ranges. */
const rangeList = (r: Range | Set<Range>): Iterable<Range> => (r instanceof Set ? r : [r]);

/** The ranges found for one selection, skipping disabled lines. */
const selectionRanges = (state: DocumentData, selection: Selection, getRanges: GetRanges): Set<Range> => {
  const r = getRanges(selection);
  if (!r) return new Set<Range>();

  return mapSet(new Set(rangeList(r)), (range) => (state.disabledLines.has(range.start.line) ? undefined : range));
};

/** Collects all ranges found by `getRanges` across the given selections, skipping disabled lines. */
const collectRanges = (state: DocumentData, selections: Selection[], getRanges: GetRanges): Set<Range> => {
  const found = new Set<Range>();
  for (const selection of selections) {
    for (const range of selectionRanges(state, selection, getRanges)) found.add(range);
  }
  return found;
};

const revealRangesForCursor = (
  state: DocumentData,
  sel: Selection,
  options: { includeEnd?: boolean, excludeStart?: boolean },
): Range | undefined => findSymbolAt(state, sel.active, options);

const revealRangesForActiveLine = (state: DocumentData, sel: Selection): Range | Set<Range> | undefined =>
  findSymbolsIn(state, state.document.getLineRange(sel.active.line));

const revealRangesForSelection = (state: DocumentData, sel: Selection): Range | Set<Range> | undefined =>
  findSymbolsIn(state, rangeFromPositions(sel.start, sel.end));

const boxRangesForCursor = (state: DocumentData, sel: Selection): Range | undefined =>
  findSymbolAt(state, sel.active);

/** Builds the reveal decoration entry for the ranges collected across the selections. */
const reveal = (state: DocumentData, selections: Selection[], getRanges: GetRanges): UpdateDecorationEntry => {
  const decoration = state.revealedUglyDecoration || state.host.createDecorationType({});
  return {
    decoration,
    ranges: Array.from(collectRanges(state, selections, getRanges)),
  };
};

/**
 * Computes the decoration entry that reveals the ugly text under the given selections,
 * depending on the configured reveal strategy.
 */
export const revealSelections = (state: DocumentData, selections: Selection[]): UpdateDecorationEntry => {
  // add the new intersections
  switch (state.revealStrategy) {
    case 'cursor':
    case 'cursor-inside': {
      const cursorOptions = state.revealStrategy === 'cursor' ? { includeEnd: true } : { excludeStart: true };
      return reveal(state, selections, function (sel) { return revealRangesForCursor(state, sel, cursorOptions); });
    }
    case 'active-line':
      return reveal(state, selections, function (sel) { return revealRangesForActiveLine(state, sel); });
    case 'selection':
      return reveal(state, selections, function (sel) { return revealRangesForSelection(state, sel); });
    default:
      return { decoration: state.revealedUglyDecoration || state.host.createDecorationType({}), ranges: [] };
  }
};

/**
 * Finds all pretty symbols on the given line; used by the per-line toggle.
 */
export const findSymbolsOnLine = (state: DocumentData, line: number): Range[] => {
  return Array.from(findSymbolsIn(state, state.document.getLineRange(line)));
};

/** Builds the boxed-cursor decoration entry around the pretty symbol under the cursor. */
const boxPretty = (state: DocumentData, selections: Selection[], getRange: GetRange): UpdateDecorationInstanceEntry | null => {
  try {
    return {
      decoration: state.boxedSymbolDecoration || {},
      ranges: collectRanges(state, selections, getRange),
    };
  } catch (err) {
    console.error(err);
    console.error('\n');
    return null;
  }
};

/**
 * Computes the decoration entry that draws a box around the pretty symbol
 * under the cursor, depending on the configured pretty cursor style.
 */
export const renderPrettyCursor = (state: DocumentData, selections: Selection[]): UpdateDecorationInstanceEntry | null => {
  switch (state.prettyCursor) {
    case 'boxed': {
      return boxPretty(state, selections, function (sel) { return boxRangesForCursor(state, sel); });
    }
    default:
      return null;
  }
};

/**
 * The resolve store: a mobx-state-tree model holding the state of the resolve
 * feature — the last resolved pretty range and its cache key, recorded when a
 * resolved range is added. Object literal, no classes.
 *
 * The overlap/range engine state (hiddeDecorationsRanges, lineIndex,
 * decorationCache, rangeKeyToCacheKey) lives on the document store; the engine
 * functions in this folder operate on it. The thin per-selection reveal/lookup
 * actions used to live here are gone — the document store exposes the same
 * operations against its own `self`, so callers go there.
 */
import { types as t } from "mobx-state-tree";
import type { Range } from "../host";
import type { DecorationKeyParams, DocumentData } from "../document/type";
import { getDecorationCacheKey } from "./cache";
import { addResolvedRange as addResolvedRangeEngine } from "./ranges";
import { passthrough } from "../utils/mst-passthrough";

export const ResolveStoreModel = t.model("ResolveStore", {
	/** The range last added via `addResolvedRange`, for observers/tests. */
	lastResolvedRange: t.maybeNull(passthrough<Range>("lastResolvedRange")),
	/** The cache key of the range last added via `addResolvedRange`. */
	lastResolvedCacheKey: t.string,
})
.actions((self) => ({
	/** The unique cache key for a substitution's parameters. */
	getDecorationCacheKey(params: DecorationKeyParams): string {
		return getDecorationCacheKey({ ...params });
	},

	/**
	 * Creates the cache entry for a resolved pretty text if missing and adds the
	 * range with overlap handling; records the resolved range on the store.
	 */
	addResolvedRange(
		state: DocumentData,
		params: DecorationKeyParams,
		uglyContext: string,
		resolvedPretty: string,
		rulePriority: number,
		uglyRange: Range,
	): void {
		addResolvedRangeEngine(state, params, uglyContext, resolvedPretty, rulePriority, uglyRange);
		self.lastResolvedRange = uglyRange;
		self.lastResolvedCacheKey = getDecorationCacheKey(params);
	},
}));

export type { ResolveStore } from "../document/type";

/**
 * The root store: a mobx-state-tree model holding the extension's runtime
 * state, created once at the extension's entry point (packages/<ide>/activate.ts)
 * and passed explicitly to the backend wiring — there are no module singletons.
 *
 * Holds the host, the TextMate registry, the grammar cache, every open
 * document's controller, the resolve feature store, and the enable/disable
 * state.
 *
 * The grammar and controller maps use inline `t.custom` passthrough types:
 * mst stores the value as-is, so the in-place mutations vscode-textmate makes
 * on grammars (and the controllers' own live state) keep working. Non-serializable
 * IDE API objects (host, registry, channels, config state) live in `volatile`.
 *
 * The config feature state (settings, predefined configs, the logger channel,
 * programmatic substitutions) also lives here, so feature code reads it through
 * getRootStore/requireRootStore instead of per-feature store modules.
 */
import { types as t, type Instance, unprotect } from "mobx-state-tree";
import type { Host, IGrammar, ITextMateRegistry, OutputChannel } from "./host";
import type { LanguageEntry, PredefinedConfig, Settings } from "./config/configuration";
import type { PrettyDocumentController } from "./editor/controller";
import { GrammarStoreModel } from "./grammar/store";
import { ReparseStoreModel } from "./reparse/segments";
import { ResolveStoreModel } from "./resolve/store";

export type OnEnabledChangeHandler = (enabled: boolean) => void;

/** A passthrough map value: stored as-is, no snapshot processing or proxying. */
const grammarValue = t.custom<IGrammar, IGrammar>({
	name: "IGrammar",
	fromSnapshot: (s) => s,
	toSnapshot: (s) => s,
	isTargetType: () => true,
	getValidationMessage: () => "",
});

const controllerValue = t.custom<PrettyDocumentController, PrettyDocumentController>({
	name: "PrettyDocumentController",
	fromSnapshot: (s) => s,
	toSnapshot: (s) => s,
	isTargetType: () => true,
	getValidationMessage: () => "",
});

export const RootStoreModel = t.model("RootStore", {
	/** Cache for loaded grammars, keyed by scope name. */
	loadedGrammars: t.map(grammarValue),
	/** Every open document's controller, keyed by document uri. */
	documents: t.map(controllerValue),
	/** Whether pretty symbols are enabled at all. */
	enabled: t.boolean,
	/** The grammar feature store (the loaded Oniguruma WASM promise). */
	grammar: GrammarStoreModel,
	/** The reparse feature store (the in-flight reparse cancellation token). */
	reparse: ReparseStoreModel,
	/** The resolve feature store (last resolved range + its cache key). */
	resolve: ResolveStoreModel,
})
// Host/registry/handlers and the config feature state are IDE API objects or
// live collections: not serializable, not observable.
.volatile(() => ({
	host: undefined as Host | undefined,
	textMateRegistry: undefined as ITextMateRegistry | undefined,
	enabledHandlers: new Set<OnEnabledChangeHandler>(),
	// Config feature state (formerly the settings/logger/predefined stores):
	loggerChannel: undefined as OutputChannel | undefined,
	predefinedConfigs: new Map<string, PredefinedConfig>(),
	settings: undefined as Settings,
	outputChannel: undefined as OutputChannel,
	predefined: new Map<string, LanguageEntry>(),
	additionalSubstitutions: new Set<LanguageEntry>(),
}));

export type RootStore = Instance<typeof RootStoreModel>;

/** The created root store, if any; set by createRootStore (last call wins). */
const rootStoreRef = { current: undefined as RootStore | undefined };

/** The root store, or undefined before createRootStore has run. */
export const getRootStore = (): RootStore | undefined => rootStoreRef.current;

/** The root store, or an error if it has not been created yet. */
export const requireRootStore = (): RootStore => {
	const store = rootStoreRef.current;
	if (!store) throw new Error("Root store not created; call createRootStore() first");
	return store;
};

/** Creates the root store; called by the extension's entry point. */
export const createRootStore = (): RootStore => {
	const store = RootStoreModel.create({
		enabled: true,
		grammar: GrammarStoreModel.create(),
		reparse: ReparseStoreModel.create(),
		resolve: ResolveStoreModel.create({ lastResolvedRange: null, lastResolvedCacheKey: "" }),
	});

	unprotect(store);

	rootStoreRef.current = store;

	return store;
};

import * as assert from "assert";
import { rangeFrom } from "../host";
import type { Host, TextEditorDecorationType, DecorationRenderOptions, OutputChannel, Disposable } from "../host";
import { getDecorationCacheKey, hasPriorityScopes, getCacheKeyPriority, addOrUpdatePrettyRange } from '../resolve/cache';
import { DocumentStoreModel } from '../document/store';
import type { DocumentView, PrettyModelData, PrettySubstitution } from '../document/type';
import type { DebounceFunction } from '../editor/debounce';

class FakeHost implements Host {
  textDocuments: never[] = [];
  visibleTextEditors: never[] = [];
  activeTextEditor = null;
  registerCommand(): Disposable { return { dispose: () => {} }; }
  getConfiguration(): unknown { return {}; }
  matchLanguage(): number { return 1; }
  getGrammarFilePath(): string | null { return null; }
  getGrammarInjections(): { scopeName: string; path: string }[] { return []; }
  getLanguageScopeName(): string | null { return "source.ts"; }
  copyToClipboard(): Promise<void> { return Promise.resolve(); }
  createDecorationType(options: DecorationRenderOptions): TextEditorDecorationType {
    return { key: "deco", options, dispose: () => {} };
  }
  createOutputChannel(): OutputChannel { return { appendLine: () => {}, dispose: () => {} }; }
  onDidOpenTextDocument(): Disposable { return { dispose: () => {} }; }
  onDidCloseTextDocument(): Disposable { return { dispose: () => {} }; }
  onDidChangeTextDocument(): Disposable { return { dispose: () => {} }; }
  onDidChangeConfiguration(): Disposable { return { dispose: () => {} }; }
  onDidChangeActiveTextEditor(): Disposable { return { dispose: () => {} }; }
  onDidChangeTextEditorSelection(): Disposable { return { dispose: () => {} }; }
}

const rule = (ugly: RegExp, pretty: string, scope?: string | string[]): PrettySubstitution => ({ ugly, pretty, scope });

const keyOf = (r: PrettySubstitution) => getDecorationCacheKey(r);

const noopDebounce: DebounceFunction = { call: () => {}, dispose: () => {} };

/** An empty document view: the cache tests only exercise the engine's
 *  range/cache bookkeeping, never the text. */
const emptyDocument: DocumentView = {
  getText: () => "",
  getLine: () => "",
  getLineRange: (line: number) => rangeFrom(line, 0, line, 0),
  getLineCount: () => 0,
  validateRange: (r) => r,
};

const makeState = (rules: PrettySubstitution[]): PrettyModelData =>
  DocumentStoreModel.create({
    document: emptyDocument,
    host: new FakeHost(),
    prettySubstitutions: new Set(rules),
    decorationCache: new Map(),
    hiddeDecorationsRanges: new Set(),
    lineIndex: new Map(),
    rangeKeyToCacheKey: new Map(),
    changedUglies: false,
    hiddenDecoration: null,
    revealedUglyDecoration: null,
    boxedSymbolDecoration: null,
    debug: false,
    outputChannel: { appendLine: () => {}, dispose: () => {} },
    defaultScope: '',
    excludedScopes: new Set(),
    hideTextMethod: 'none',
    revealStrategy: 'none',
    prettyCursor: 'none',
    disabledLines: new Set(),
    subscriptions: [],
    currentDecorations: [],
    updateActiveEditor: noopDebounce,
    updateSelection: noopDebounce,
    adjustCursorMovement: false,
    lastSelections: new Map(),
    revealedRanges: [],
    cursorRanges: [],
  });

suite("cache", () => {
  test("getDecorationCacheKey formats regex ugly, sorted scopes, and sorted style entries", () => {
    // key = `${ugly}|${flags}:::${pretty}:::${scopeStr}:::${styleStr}` (empty scope/style still keep their separators)
    assert.strictEqual(getDecorationCacheKey(rule(/a/g, "A")), "a|g:::A::::::");
    assert.strictEqual(getDecorationCacheKey(rule(/a/g, "A", ["s2", "s1"])), "a|g:::A:::s1,s2:::");
    assert.strictEqual(getDecorationCacheKey({ ugly: /a/g, pretty: "A", style: { color: "red" } }), "a|g:::A::::::[[\"color\",\"red\"]]");
  });

  test("hasPriorityScopes and getCacheKeyPriority recognize the trailing ! suffix", () => {
    assert.strictEqual(hasPriorityScopes(["s1"]), false);
    assert.strictEqual(hasPriorityScopes(["s1", "s2!"]), true);
    const low = rule(/a/g, "A", "s1");
    const high = rule(/b/g, "B", "s1!");
    const state = makeState([low, high]);
    assert.strictEqual(getCacheKeyPriority(state, keyOf(low)), 1);
    assert.strictEqual(getCacheKeyPriority(state, keyOf(high)), 2);
    assert.strictEqual(getCacheKeyPriority(state, "unknown:::key::::::"), 1, "no matching rule defaults to 1");
  });

  test("addOrUpdatePrettyRange adds a range and creates a cache entry from the rule", () => {
    const r = rule(/ab/g, "AB", "s1");
    const state = makeState([r]);
    addOrUpdatePrettyRange(state, rangeFrom(0, 0, 0, 2), keyOf(r));
    assert.strictEqual(state.hiddeDecorationsRanges.size, 1);
    const entry = state.decorationCache.get(keyOf(r));
    assert.ok(entry, "cache entry created");
    assert.strictEqual(entry.ranges.size, 1);
    assert.strictEqual(entry.pretty, "AB");
    assert.strictEqual(state.rangeKeyToCacheKey.size, 1);
  });

  test("a lower-priority range contained in a higher-priority range is rejected", () => {
    const high = rule(/abcd/g, "ABCD", "!s1");
    const low = rule(/bc/g, "BC", "s1");
    const state = makeState([high, low]);
    addOrUpdatePrettyRange(state, rangeFrom(0, 0, 0, 4), keyOf(high));
    addOrUpdatePrettyRange(state, rangeFrom(0, 1, 0, 3), keyOf(low));
    assert.strictEqual(state.hiddeDecorationsRanges.size, 1, "new range not added");
  });

  test("a higher-priority range replaces the lower-priority range that contains it", () => {
    const high = rule(/bc/g, "BC", "s1!");
    const low = rule(/abcd/g, "ABCD", "s1");
    const state = makeState([high, low]);
    addOrUpdatePrettyRange(state, rangeFrom(0, 0, 0, 4), keyOf(low));
    addOrUpdatePrettyRange(state, rangeFrom(0, 1, 0, 3), keyOf(high));
    assert.strictEqual(state.hiddeDecorationsRanges.size, 1);
    const [only] = [...state.hiddeDecorationsRanges];
    assert.deepStrictEqual([only.start.character, only.end.character], [1, 3]);
  });

  test("a new range containing an existing one at equal priority replaces the existing one", () => {
    const wide = rule(/abcd/g, "ABCD", "s1");
    const narrow = rule(/ab/g, "AB", "s1");
    const state = makeState([wide, narrow]);
    addOrUpdatePrettyRange(state, rangeFrom(0, 0, 0, 2), keyOf(narrow));
    addOrUpdatePrettyRange(state, rangeFrom(0, 0, 0, 4), keyOf(wide));
    assert.strictEqual(state.hiddeDecorationsRanges.size, 1);
    const [only] = [...state.hiddeDecorationsRanges];
    assert.strictEqual(only.end.character, 4);
  });

  test("partial overlaps are won by the higher-priority range regardless of order", () => {
    const high = rule(/cdef/g, "CDEF", "s1!");
    const low = rule(/abc/g, "ABC", "s1");
    const first = makeState([high, low]);
    addOrUpdatePrettyRange(first, rangeFrom(0, 0, 0, 3), keyOf(low));
    addOrUpdatePrettyRange(first, rangeFrom(0, 2, 0, 6), keyOf(high));
    assert.strictEqual(first.hiddeDecorationsRanges.size, 1);
    const [winner] = [...first.hiddeDecorationsRanges];
    assert.strictEqual(winner.start.character, 2, "high-priority range wins");

    const second = makeState([high, low]);
    addOrUpdatePrettyRange(second, rangeFrom(0, 2, 0, 6), keyOf(high));
    addOrUpdatePrettyRange(second, rangeFrom(0, 0, 0, 3), keyOf(low));
    assert.strictEqual(second.hiddeDecorationsRanges.size, 1, "lower-priority partial overlap rejected");
  });

  test("re-adding an equal range under another key replaces the previous owner", () => {
    const a = rule(/ab/g, "AB", "s1");
    const b = rule(/ab/g, "CD", "s1");
    const state = makeState([a, b]);
    addOrUpdatePrettyRange(state, rangeFrom(0, 0, 0, 2), keyOf(a));
    addOrUpdatePrettyRange(state, rangeFrom(0, 0, 0, 2), keyOf(b));
    assert.strictEqual(state.hiddeDecorationsRanges.size, 1);
    assert.strictEqual(state.rangeKeyToCacheKey.get("0:0-0:2"), keyOf(b), "index points at the newest key");
    assert.strictEqual(state.decorationCache.get(keyOf(a))?.ranges.size, 0, "old entry emptied");
    assert.strictEqual(state.decorationCache.get(keyOf(b))?.ranges.size, 1);
  });
});

import * as assert from "assert";
import type { Range } from "../host";
import { rangeFrom } from "../host";
import type { Host, TextEditorDecorationType, DecorationRenderOptions, OutputChannel, Disposable } from "../host";
import { createPrettyModel } from '../editor/pretty-model';
import type { DocumentView } from '../document/type';
import type { LanguageEntry } from '../config/configuration';
