const patch = (id: string, mod: unknown): void => {
  const M = Module as typeof Module & Loadable;
  const orig = M._load;
  M._load = (request: string, parent: unknown, isMain: boolean) =>
    request === id ? mod : orig(request, parent, isMain);
};
