import * as assert from "assert";
import { rangeFrom } from "../host";
import type { Host, TextEditorDecorationType, DecorationRenderOptions, OutputChannel, Disposable } from "../host";
import { createPrettyModel } from '../editor/pretty-model';
import type { DocumentView } from '../document/type';
import type { LanguageEntry } from '../config/configuration';
import { parseRawGrammar, Registry } from '../grammar/text-mate';
import type { IGrammar } from '../grammar/text-mate';
import { loadOnigLib } from '../grammar/onig-wasm';
import { grammarJson } from "./synthetic-ts-grammar";

const onigLibPromise = loadOnigLib();

// C3 regression test: the O(M^2) decoration-cache scan (pre-fix: ~15.6 s for
// 5k lines, ~73 s for 10k) must stay bounded. The document is a synthetic
// TypeScript file (functions, arrows, &&/||, try/catch) tokenized by the
// shared synthetic TS grammar (source.ts) — the same scopes the
// typescript-to-python predefined config targets.
//
// 10k lines: at 5k the regressed full-set scan (~2.7 s on a fast machine) can
// slip under the budget; at 10k it is unambiguously over it (~15 s) while the
// fixed path stays ~10x under budget. The budget covers the FIRST (cold) model
// construction — the user-visible "open file" path. No warmup run: a prior
// construction would JIT-warm the hot loop and let a regressed run slip under.

const LINE_COUNT = 10000;
const BUDGET_MS = 5000; // ~12x the fixed path; only fails if the O(M^2) regression returns.

class FakeHost implements Host {
  textDocuments: never[] = [];
  visibleTextEditors: never[] = [];
  activeTextEditor = null;
  registerCommand(): Disposable { return { dispose: () => {} }; }
  getConfiguration(): unknown { return {}; }
  matchLanguage(): number { return 1; }
  getGrammarFilePath(): string | null { return null; }
  getGrammarInjections(): { scopeName: string; path: string }[] { return []; }
  getLanguageScopeName(): string | null { return "source.ts"; }
  copyToClipboard(): Promise<void> { return Promise.resolve(); }
  createDecorationType(options: DecorationRenderOptions): TextEditorDecorationType {
    return { key: `deco-${Math.random()}`, options, dispose: () => {} };
  }
  createOutputChannel(): OutputChannel { return { appendLine: () => {}, dispose: () => {} }; }
  onDidOpenTextDocument(): Disposable { return { dispose: () => {} }; }
  onDidCloseTextDocument(): Disposable { return { dispose: () => {} }; }
  onDidChangeTextDocument(): Disposable { return { dispose: () => {} }; }
  onDidChangeConfiguration(): Disposable { return { dispose: () => {} }; }
  onDidChangeActiveTextEditor(): Disposable { return { dispose: () => {} }; }
  onDidChangeTextEditorSelection(): Disposable { return { dispose: () => {} }; }
}

// The dynamic rule ($1$2 substitution) is what drives the O(M^2) cache path.
const RULES = [
  { ugly: "([a-z]{4,})([a-z]{4,})([a-z]{4,})", pretty: "$1$2$1$2$1$2$1$2$1$2" },
  { ugly: "(&&)", pretty: "AND", scope: "source.ts" },
  { ugly: "(\\|\\|)", pretty: "OR", scope: "source.ts" },
  { ugly: "function\\s+([A-Za-z_]\\w*)", pretty: "fun $1", scope: "meta.function.ts" },
];
const SETTINGS: LanguageEntry = { language: "typescript", substitutions: RULES, combineIdenticalScopes: false };
const OPTIONS = {
  hideTextMethod: "hack-letterSpacing" as const,
  debug: false,
  outputChannel: { appendLine: () => {}, dispose: () => {} },
  languageId: "typescript",
};

const HOT_LINE_IDX = 500;
const HOT_WORD = "abc".repeat(667); // ~2000-char match -> worst-case part-by-part

const buildDocument = (n: number): string[] => {
  const lines = new Array<string>(n);
  for (let i = 0; i < n; i++) {
    if (i === HOT_LINE_IDX) {
      lines[i] = `const hot = ${HOT_WORD};`;
    } else if (i % 25 === 0) {
      lines[i] = `function sectionHeading${i}(a: number): number {`;
    } else if (i % 3 === 0) {
      lines[i] = `const arrow${i} = (x: number): boolean => x > 0 || x < 0;`;
    } else if (i % 7 === 0) {
      lines[i] = `const flag${i} = a && b;`;
    } else {
      lines[i] = i % 10 === 4
        ? `try { const v${i} = 1; } catch (e) { throw e; }`
        : `const plain${i} = i;`;
    }
  }
  return lines;
};

const makeDocModel = (lines: string[]): DocumentView => {
  const text = lines.join("\n");
  const offsets = new Array<number>(lines.length + 1);
  offsets[0] = 0;
  for (let i = 0; i < lines.length; i++) offsets[i + 1] = offsets[i] + lines[i].length + 1;
  return {
    getText: (r) => text.slice(offsets[r.start.line] + r.start.character, offsets[r.end.line] + r.end.character),
    getLine: (line) => lines[line] ?? "",
    getLineRange: (line) => rangeFrom(line, 0, line, (lines[line] ?? "").length),
    getLineCount: () => lines.length,
    validateRange: (r) => r,
  };
};

const loadGrammar = async (): Promise<IGrammar> => {
  assert.ok(Registry && parseRawGrammar, "vscode-textmate available");
  const registry = new Registry({
    onigLib: onigLibPromise,
    loadGrammar: () => Promise.resolve(parseRawGrammar(grammarJson, "synthetic-ts.json")),
  });
  const grammar = await registry.loadGrammar("source.ts");
  assert.ok(grammar, "synthetic typescript grammar loaded");
  return grammar;
};

suite("large document", () => {
  test("computes all decorations on a 10k-line typescript document within budget", async () => {
    const grammar = await loadGrammar();
    const lines = buildDocument(LINE_COUNT);
    const doc = makeDocModel(lines);
    const makeModel = () => createPrettyModel(new FakeHost(), doc, SETTINGS, { ...OPTIONS, textMateGrammar: grammar });

    const t0 = process.hrtime.bigint();
    const model = makeModel();
    const ms = Number(process.hrtime.bigint() - t0) / 1e6;

    assert.ok(
      ms < BUDGET_MS,
      `decoration computation for ${LINE_COUNT} lines took ${ms.toFixed(0)}ms (budget ${BUDGET_MS}ms; ` +
        `the pre-fix O(M^2) cache scan took ~15600ms)`
    );

    // Correctness invariant: ranges were actually produced, and a second
    // recompute from scratch yields the identical count (idempotency).
    const firstCount = model.getPrettySubstitutionsRanges().length;
    assert.ok(firstCount > 0, `expected decoration ranges, got ${firstCount}`);

    const second = makeModel();
    const secondCount = second.getPrettySubstitutionsRanges().length;
    assert.strictEqual(secondCount, firstCount, `recompute produced ${secondCount} ranges, expected ${firstCount}`);
  });
});

import * as assert from 'assert';
import * as fs from 'fs';
import * as path from 'path';

/**
 * Guard test: the IDE-agnostic apps (backend, and any future frontend) must
 * never import an IDE SDK (`vscode`, `webstorm`, ...). Only the adapter
 * packages (packages/vscode-extension, packages/webstorm-extension) may import
 * an IDE module. This test walks every TypeScript source file under `apps/`
 * and fails if any of them references an IDE module.
 *
 * The test is location-independent: it walks up from its own compiled location
 * until it finds the repo root (a directory holding both `apps` and
 * `pnpm-workspace.yaml`), so it works whether it is compiled under the backend
 * or under an adapter package's out/.
 */

const findRepoRoot = (start: string): string | null => {
  let dir = start;
  for (let i = 0; i < 10; i++) {
    if (
      fs.existsSync(path.join(dir, 'apps')) &&
      fs.existsSync(path.join(dir, 'pnpm-workspace.yaml'))
    ) {
      return dir;
    }
    const parent = path.dirname(dir);
    if (parent === dir) return null;
    dir = parent;
  }
  return null;
};

const walkTs = (dir: string, out: string[]): void => {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    if (entry.name === 'node_modules' || entry.name === 'out' || entry.name.startsWith('.')) continue;
    const p = path.join(dir, entry.name);
    if (entry.isDirectory()) walkTs(p, out);
    else if (/\.(ts|tsx)$/.test(entry.name)) out.push(p);
  }
};

// An import/require of an IDE module. Catches every form of pulling in the
// `vscode` or `webstorm` SDK by name (default, namespace, or require).
const IDE_IMPORT = /\b(?:import\b[\s\S]*?from\s*|require\s*\(\s*)["'](vscode|webstorm)["']/;

const repoRoot = findRepoRoot(__dirname);

suite('no IDE imports in apps', () => {
  test('repo root is resolvable', () => {
    assert.ok(repoRoot, `could not resolve repo root from ${__dirname}`);
  });

  test('apps/** never imports an IDE module', () => {
    if (!repoRoot) return;
    const files: string[] = [];
    walkTs(path.join(repoRoot, 'apps'), files);
    assert.ok(files.length > 0, 'found at least one apps source file');

    const offenders: string[] = [];
    for (const file of files) {
      const src = fs.readFileSync(file, 'utf8');
      if (IDE_IMPORT.test(src)) {
        offenders.push(path.relative(repoRoot, file));
      }
    }
    assert.deepStrictEqual(
      offenders,
      [],
      `apps must not import an IDE module; offenders: ${offenders.join(', ')}`,
    );
  });
});

import * as assert from "assert";
import { rangeFrom } from "../host";
import type { Range } from "../host";
import type { Host, TextEditorDecorationType, DecorationRenderOptions, OutputChannel, Disposable } from "../host";
import { createPrettyModel } from '../editor/pretty-model';
import type { DocumentView } from '../document/type';
import { parseRawGrammar, Registry } from '../grammar/text-mate';
import type { IGrammar } from '../grammar/text-mate';
import { loadOnigLib } from '../grammar/onig-wasm';
import { grammarJson } from "./synthetic-ts-grammar";

const onigLibPromise = loadOnigLib();

const noop = (): Disposable => ({ dispose: () => {} });

const makeFakeHost = (): Host => {
  const host: Host = {
    textDocuments: [],
    visibleTextEditors: [],
    activeTextEditor: null,
    registerCommand: noop,
    getConfiguration(): unknown { return {}; },
    matchLanguage(): number { return 1; },
    getGrammarFilePath(): string | null { return null; },
    getGrammarInjections(): { scopeName: string; path: string }[] { return []; },
    getLanguageScopeName(): string | null { return "source.ts"; },
    copyToClipboard(): Promise<void> { return Promise.resolve(); },
    createDecorationType(o: DecorationRenderOptions): TextEditorDecorationType { return { key: "k", options: o, dispose: () => {} }; },
    createOutputChannel(): OutputChannel { return { appendLine: () => {}, dispose: () => {} }; },
    onDidOpenTextDocument: noop,
    onDidCloseTextDocument: noop,
    onDidChangeTextDocument: noop,
    onDidChangeConfiguration: noop,
    onDidChangeActiveTextEditor: noop,
    onDidChangeTextEditorSelection: noop,
  };
  return host;
};

const makeDocModel = (lines: string[]): DocumentView => {
  const text = lines.join("\n");
  const offsets = new Array<number>(lines.length + 1);
  offsets[0] = 0;
  for (let i = 0; i < lines.length; i++) offsets[i + 1] = offsets[i] + lines[i].length + 1;
  return {
    getText: (r) => text.slice(offsets[r.start.line] + r.start.character, offsets[r.end.line] + r.end.character),
    getLine: (line) => lines[line] ?? "",
    getLineRange: (line) => rangeFrom(line, 0, line, (lines[line] ?? "").length),
    getLineCount: () => lines.length,
    validateRange: (r) => r,
  };
};

// A document model whose backing lines can be mutated to simulate an IDE edit.
const makeMutableDocModel = (initial: string[]): { doc: DocumentView; setLines: (l: string[]) => void } => {
  let lines = initial;
  const textOf = () => lines.join("\n");
  const sliceRange = (r: Range) => {
    const text = textOf();
    const offsets = new Array<number>(lines.length + 1);
    offsets[0] = 0;
    for (let i = 0; i < lines.length; i++) offsets[i + 1] = offsets[i] + lines[i].length + 1;
    return text.slice(offsets[r.start.line] + r.start.character, offsets[r.end.line] + r.end.character);
  };
  const doc: DocumentView = {
    getText: sliceRange,
    getLine: (line) => lines[line] ?? "",
    getLineRange: (line) => rangeFrom(line, 0, line, (lines[line] ?? "").length),
    getLineCount: () => lines.length,
    validateRange: (r) => r,
  };
  return { doc, setLines: (l) => { lines = l; } };
};

const OPTIONS = {
  hideTextMethod: "hack-letterSpacing" as const,
  debug: false,
  outputChannel: { appendLine: () => {}, dispose: () => {} },
  languageId: "typescript",
};

const loadGrammar = async (): Promise<IGrammar> => {
  const registry = new Registry({ onigLib: onigLibPromise, loadGrammar: () => Promise.resolve(parseRawGrammar(grammarJson, "synthetic-ts.json")) });
  const grammar = await registry.loadGrammar("source.ts");
  assert.ok(grammar, "grammar loaded");
  return grammar;
};

const rangeAt = (r: Range): [number, number, number, number] => [r.start.line, r.start.character, r.end.line, r.end.character];

suite("PrettyModel (synthetic TypeScript grammar)", () => {
  test("finds substitution ranges in plain source scope", async () => {
    const grammar = await loadGrammar();
    const lines = ["const r = a && b;"];
    const doc = makeDocModel(lines);
    const settings = {
      language: "typescript",
      substitutions: [{ ugly: "&&", pretty: "AND" }],
      combineIdenticalScopes: true,
    };
    const model = createPrettyModel(makeFakeHost(), doc, settings, { ...OPTIONS, textMateGrammar: grammar });
    const ranges = model.getPrettySubstitutionsRanges();
    assert.strictEqual(ranges.length, 1);
    // "const r = a " = 12 chars; "&&" spans indices 12..14
    assert.deepStrictEqual(rangeAt(ranges[0]), [0, 12, 0, 14]);
    assert.strictEqual(model.getDecoratedText(rangeFrom(0, 0, 0, 18)), "const r = a AND b;");
  });

  test("scope-restricted rules only match inside their scope", async () => {
    const grammar = await loadGrammar();
    const lines = [
      "function alpha() {",
      "\treturn 1;",
      "}",
      "const x = 1;",
    ];
    const doc = makeDocModel(lines);
    // `function` -> fun is restricted to meta.function.ts, so the keyword
    // only matches where the grammar actually opened that scope.
    const settings = {
      language: "typescript",
      substitutions: [{ ugly: "function", pretty: "fun", scope: "meta.function.ts" }],
      combineIdenticalScopes: true,
    };
    const model = createPrettyModel(makeFakeHost(), doc, settings, { ...OPTIONS, textMateGrammar: grammar });
    const ranges = model.getPrettySubstitutionsRanges();
    assert.strictEqual(ranges.length, 1, "only the in-scope `function` keyword matches");
    assert.strictEqual(ranges[0].start.line, 0);
    // "function alpha() {" (18 chars) decorates to "fun alpha() {" (shorter).
    assert.strictEqual(model.getDecoratedText(rangeFrom(0, 0, 0, 18)), "fun alpha() {");
  });

  test("a scope that never appears in the grammar matches nothing", async () => {
    const grammar = await loadGrammar();
    const lines = ["const r = a && b;"];
    const doc = makeDocModel(lines);
    // A scope the synthetic grammar never produces: no match.
    const settings = {
      language: "typescript",
      substitutions: [{ ugly: "&&", pretty: "AND", scope: "meta.arrow.ts" }],
      combineIdenticalScopes: true,
    };
    const model = createPrettyModel(makeFakeHost(), doc, settings, { ...OPTIONS, textMateGrammar: grammar });
    assert.strictEqual(model.getPrettySubstitutionsRanges().length, 0, "scope never present in this grammar");
  });

  test("excludedScopes skip substitution on excluded segments", async () => {
    const grammar = await loadGrammar();
    const lines = ["// && in a comment"];
    const doc = makeDocModel(lines);
    const settings = {
      language: "typescript",
      substitutions: [{ ugly: "&&", pretty: "AND" }],
      excludedScopes: ["comment.line.double-slash.ts"],
      combineIdenticalScopes: true,
    };
    const model = createPrettyModel(makeFakeHost(), doc, settings, { ...OPTIONS, textMateGrammar: grammar });
    assert.strictEqual(model.getPrettySubstitutionsRanges().length, 0, "comment segment excluded");
  });

  test("applyChanges shifts ranges after an insertion and reparses", async () => {
    const grammar = await loadGrammar();
    const { doc, setLines } = makeMutableDocModel(["const a = x && y;", "const b = p && q;"]);
    const settings = {
      language: "typescript",
      substitutions: [{ ugly: "&&", pretty: "AND" }],
      combineIdenticalScopes: true,
    };
    const model = createPrettyModel(makeFakeHost(), doc, settings, { ...OPTIONS, textMateGrammar: grammar });
    assert.strictEqual(model.getPrettySubstitutionsRanges().length, 2, "one marker per line");

    // Insert a new blank line at the very top of the document.
    const change = { range: rangeFrom(0, 0, 0, 0), text: "inserted\n" };
    setLines(["inserted", "const a = x && y;", "const b = p && q;"]);
    const changed = model.applyChanges([change]);
    assert.strictEqual(changed, true, "changes reported");
    const after = model.getPrettySubstitutionsRanges();
    assert.strictEqual(after.length, 2, "same number of markers after the shift");
    for (const r of after) assert.ok(r.start.line >= 1, `range not shifted: ${r.start.line}:${r.start.character}`);
  });

  test("recomputeDecorations is idempotent", async () => {
    const grammar = await loadGrammar();
    const lines = ["const a = x && y;", "plain"];
    const doc = makeDocModel(lines);
    const settings = {
      language: "typescript",
      substitutions: [{ ugly: "&&", pretty: "AND" }],
      combineIdenticalScopes: true,
    };
    const model = createPrettyModel(makeFakeHost(), doc, settings, { ...OPTIONS, textMateGrammar: grammar });
    const first = model.getPrettySubstitutionsRanges().length;
    model.recomputeDecorations();
    const second = model.getPrettySubstitutionsRanges().length;
    assert.strictEqual(first, 1);
    assert.strictEqual(second, first, "recompute is stable");
  });
});

import * as assert from "assert";
import type { Range } from "../host";
import { rangeFrom, rangeTranslate } from "../host";
import {
  rangeKey,
  buildLineIndex,
  indexInsert,
  indexRemove,
  overlapCandidates,
  rebuildRangeKeyMap,
  shiftKeyMapForSet,
  keyMapRemove,
} from '../resolve/range-index';

suite("range-index", () => {
  test("rangeKey encodes start and end positions", () => {
    assert.strictEqual(rangeKey(rangeFrom(1, 2, 3, 4)), "1:2-3:4");
    assert.strictEqual(rangeKey(rangeFrom(0, 0, 0, 5)), "0:0-0:5");
  });

  test("buildLineIndex buckets ranges by start line", () => {
    const a = rangeFrom(0, 1, 0, 4);
    const b = rangeFrom(2, 0, 2, 3);
    const c = rangeFrom(0, 9, 0, 12);
    const index = buildLineIndex(new Set([a, b, c]));
    assert.deepStrictEqual([...index.keys()].sort(), [0, 2]);
    assert.deepStrictEqual(index.get(0), [a, c]);
    assert.deepStrictEqual(index.get(2), [b]);
  });

  test("indexInsert and indexRemove maintain the index incrementally", () => {
    const index = new Map<number, Range[]>();
    const a = rangeFrom(1, 0, 1, 3);
    const b = rangeFrom(1, 5, 1, 8);
    indexInsert(index, a);
    indexInsert(index, b);
    assert.deepStrictEqual(index.get(1), [a, b]);
    indexRemove(index, a);
    assert.deepStrictEqual(index.get(1), [b]);
    indexRemove(index, b);
    assert.strictEqual(index.has(1), false, "empty bucket is deleted");
  });

  test("overlapCandidates returns ranges on overlapping lines only", () => {
    const l0 = rangeFrom(0, 0, 0, 3);
    const l1 = rangeFrom(1, 0, 1, 3);
    const l5 = rangeFrom(5, 0, 5, 3);
    const set = new Set([l0, l1, l5]);
    const index = buildLineIndex(set);
    assert.deepStrictEqual(overlapCandidates(index, set, rangeFrom(0, 0, 1, 9)), [l0, l1]);
    assert.deepStrictEqual(overlapCandidates(index, set, rangeFrom(5, 0, 5, 1)), [l5]);
    assert.deepStrictEqual(overlapCandidates(index, set, rangeFrom(2, 0, 2, 1)), []);
  });

  test("overlapCandidates falls back to the full set for wide spans", () => {
    const a = rangeFrom(0, 0, 0, 3);
    const b = rangeFrom(100, 0, 100, 3);
    const set = new Set([a, b]);
    const index = buildLineIndex(set);
    const wide = rangeFrom(0, 0, 70, 0);
    assert.deepStrictEqual(overlapCandidates(index, set, wide).sort(), [a, b].sort());
  });

  test("rebuildRangeKeyMap maps only active ranges to their cache key", () => {
    const active = rangeFrom(0, 1, 0, 3);
    const stale = rangeFrom(1, 1, 1, 3);
    const entry = (ranges: Range[]) => ({ decorationType: null, ranges: new Set(ranges), pretty: "" });
    const state = {
      decorationCache: new Map([
        ["keyA", entry([active, stale])],
        ["keyB", entry([stale])],
      ]),
      hiddeDecorationsRanges: new Set([active]),
    };
    const map = rebuildRangeKeyMap(state);
    assert.deepStrictEqual(map, new Map([[rangeKey(active), "keyA"]]));
  });

  test("shiftKeyMapForSet remaps keys of shifted ranges", () => {
    const r = rangeFrom(0, 2, 0, 5);
    const map = new Map([[rangeKey(r), "k"]]);
    shiftKeyMapForSet(map, new Set([r]), (x) => rangeTranslate(x, 0, 1));
    assert.deepStrictEqual(map, new Map([[rangeKey(rangeFrom(0, 3, 0, 6)), "k"]]));
  });

  test("keyMapRemove deletes the given ranges' keys", () => {
    const a = rangeFrom(0, 0, 0, 1);
    const b = rangeFrom(1, 0, 1, 1);
    const map = new Map([[rangeKey(a), "a"], [rangeKey(b), "b"]]);
    keyMapRemove(map, [a]);
    assert.deepStrictEqual(map, new Map([[rangeKey(b), "b"]]));
  });
});

import * as assert from "assert";
import { classifyRuleScopes, isScopeApplicable } from '../reparse/tokenize';

suite("scope-check", () => {
  test("classifyRuleScopes sorts scopes into positive, negative and high-priority", () => {
    const { positiveScopes, negativeScopesByPrefix, highPriorityScopes } = classifyRuleScopes({
      ugly: /x/g,
      pretty: "y",
      scope: ["meta.function.ts", "!meta.block.ts", "meta.important!"],
    });
    assert.deepStrictEqual(positiveScopes, new Set(["meta.function.ts"]));
    assert.deepStrictEqual(negativeScopesByPrefix, new Set(["meta.block.ts"]));
    assert.deepStrictEqual(highPriorityScopes, new Set(["meta.important"]));
  });

  test("classifyRuleScopes handles a single string scope and no scope", () => {
    const single = classifyRuleScopes({ ugly: /x/g, pretty: "y", scope: "a.b" });
    assert.deepStrictEqual(single.positiveScopes, new Set(["a.b"]));
    const none = classifyRuleScopes({ ugly: /x/g, pretty: "y" });
    assert.strictEqual(none.positiveScopes.size, 0);
    assert.strictEqual(none.negativeScopesByPrefix.size, 0);
    assert.strictEqual(none.highPriorityScopes.size, 0);
  });

  test("a rule with no scopes never applies (no positive match possible)", () => {
    const c = classifyRuleScopes({ ugly: /x/g, pretty: "y" });
    assert.strictEqual(isScopeApplicable(c.positiveScopes, c.negativeScopesByPrefix, c.highPriorityScopes, new Set(["source.ts"])), false);
  });

  test("a positive scope applies when the token scope starts with it", () => {
    const c = classifyRuleScopes({ ugly: /x/g, pretty: "y", scope: "meta.function" });
    assert.strictEqual(isScopeApplicable(c.positiveScopes, c.negativeScopesByPrefix, c.highPriorityScopes, new Set(["meta.function.ts"])), true);
    assert.strictEqual(isScopeApplicable(c.positiveScopes, c.negativeScopesByPrefix, c.highPriorityScopes, new Set(["meta.arrow.ts"])), false);
  });

  test("a high-priority scope (trailing !) applies without a positive scope", () => {
    const c = classifyRuleScopes({ ugly: /x/g, pretty: "y", scope: "meta.important!" });
    assert.strictEqual(isScopeApplicable(c.positiveScopes, c.negativeScopesByPrefix, c.highPriorityScopes, new Set(["meta.important.ts"])), true);
    assert.strictEqual(isScopeApplicable(c.positiveScopes, c.negativeScopesByPrefix, c.highPriorityScopes, new Set(["other.scope"])), false);
  });

  test("a negative scope (leading !) vetoes the rule even when a positive scope matches", () => {
    const c = classifyRuleScopes({ ugly: /x/g, pretty: "y", scope: ["meta.function", "!meta.block"] });
    assert.strictEqual(isScopeApplicable(c.positiveScopes, c.negativeScopesByPrefix, c.highPriorityScopes, new Set(["meta.function.ts", "meta.block.ts"])), false);
    assert.strictEqual(isScopeApplicable(c.positiveScopes, c.negativeScopesByPrefix, c.highPriorityScopes, new Set(["meta.function.ts"])), true);
  });

  test("high-priority match still respects negative scopes", () => {
    const c = classifyRuleScopes({ ugly: /x/g, pretty: "y", scope: ["meta.important!", "!meta.block"] });
    assert.strictEqual(isScopeApplicable(c.positiveScopes, c.negativeScopesByPrefix, c.highPriorityScopes, new Set(["meta.important.ts", "meta.block.ts"])), false);
  });
});

// Shared synthetic TypeScript TextMate grammar for unit tests.
//
// The real VS Code TypeScript grammar (typescript-basics) is a large
// tmLanguage; the unit tests only need a grammar that produces the same
// scope names the typescript-to-python predefined config targets:
//   - meta.function.ts / meta.function.tsx   (named function declarations)
//   - meta.arrow.ts / meta.arrow.tsx         (arrow functions)
//   - meta.block.ts                          (curly-brace blocks)
//   - meta.objectliteral.ts                  (object literals)
//   - comment.line.ts                        (// comments, excluded by config)
//
// Keep the scope names in sync with apps/backend/package.json
// (mdPrettify.predefinedConfigurations.typescript-to-python).

export const tsScope = "source.ts";

export const grammarJson = JSON.stringify({
  scopeName: "source.ts",
  patterns: [
    { include: "#comment" },
    { include: "#function" },
    { include: "#arrow" },
    { include: "#block" },
  ],
  repository: {
    comment: {
      match: "//.*$",
      name: "comment.line.double-slash.ts",
    },
    function: {
      begin: "function\\s+[A-Za-z_]\\w*",
      end: "(?=\\{)",
      name: "meta.function.ts",
      patterns: [{ match: "[A-Za-z_]\\w*", name: "entity.name.function.ts" }],
    },
    arrow: {
      begin: "=>",
      end: "$",
      name: "meta.arrow.ts",
    },
    block: {
      begin: "\\{",
      end: "\\}",
      name: "meta.block.ts",
    },
  },
});

import * as assert from "assert";
import { combineIdenticalTokenScopes, groupAndMergeTokensByScope, matchScope, groupSubstitutionsByScope } from '../grammar/text-mate';
import type { IToken } from "../host";

const tok = (startIndex: number, endIndex: number, ...scopes: string[]): IToken => ({ startIndex, endIndex, scopes });

suite("text-mate pure helpers", () => {
  test("combineIdenticalTokenScopes merges adjacent tokens with identical scopes", () => {
    const tokens = [tok(0, 3, "a"), tok(3, 6, "a"), tok(6, 9, "b")];
    assert.deepStrictEqual(combineIdenticalTokenScopes(tokens), [tok(0, 6, "a"), tok(6, 9, "b")]);
  });

  test("combineIdenticalTokenScopes keeps tokens with gaps or differing scopes", () => {
    const gap = [tok(0, 3, "a"), tok(5, 8, "a")];
    assert.deepStrictEqual(combineIdenticalTokenScopes(gap), gap);
    const diff = [tok(0, 3, "a"), tok(3, 6, "b")];
    assert.deepStrictEqual(combineIdenticalTokenScopes(diff), diff);
    assert.deepStrictEqual(combineIdenticalTokenScopes([]), []);
  });

  test("combineIdenticalTokenScopes does not mutate the source tokens", () => {
    const first = tok(0, 3, "a");
    const second = tok(3, 6, "a");
    const out = combineIdenticalTokenScopes([first, second]);
    assert.strictEqual(first.endIndex, 3, "source token unchanged");
    assert.strictEqual(out[0].endIndex, 6);
  });

  test("groupAndMergeTokensByScope merges touching ranges but keeps gapped ones separate", () => {
    const tokens = [
      tok(0, 4, "a", "x"),
      tok(4, 8, "a"),
      tok(10, 14, "a"),
    ];
    const grouped = groupAndMergeTokensByScope(tokens);
    // (0,4) and (4,8) touch and merge to (0,8); (10,14) has a gap (8..10) and stays separate
    assert.deepStrictEqual(grouped["a"], [{ startIndex: 0, endIndex: 8 }, { startIndex: 10, endIndex: 14 }]);
    assert.deepStrictEqual(grouped["x"], [{ startIndex: 0, endIndex: 4 }]);
    assert.deepStrictEqual(groupAndMergeTokensByScope([]), {});
  });

  test("matchScope matches when any token scope contains the scope", () => {
    const scopes = ["source.ts", "meta.function.ts"];
    assert.strictEqual(matchScope("meta.function.ts", scopes), true);
    assert.strictEqual(matchScope(["meta.function.ts", "other"], scopes), true);
    assert.strictEqual(matchScope("meta.arrow.ts", scopes), false);
    assert.strictEqual(matchScope("", scopes), true, "empty scope matches everything");
  });

  test("matchScope falls back to per-part matching for multi-part scopes", () => {
    const scopes = ["source.ts", "meta.paragraph.ts"];
    assert.strictEqual(matchScope("meta.paragraph.ts", scopes), true);
    assert.strictEqual(matchScope("meta.paragraph.foobar", scopes), false, "one missing part fails");
  });

  test("groupSubstitutionsByScope buckets substitutions by scope, defaulting to defaultScope", () => {
    const withScope = { ugly: /a/g, pretty: "A", scope: "s1" };
    const multi = { ugly: /b/g, pretty: "B", scope: ["s1", "s2"] };
    const bare = { ugly: /c/g, pretty: "C" };
    const grouped = groupSubstitutionsByScope([withScope, multi, bare], "default");
    assert.deepStrictEqual(grouped["s1"], [withScope, multi]);
    assert.deepStrictEqual(grouped["s2"], [multi]);
    assert.deepStrictEqual(grouped["default"], [bare]);
  });
});

import * as assert from "assert";
import { positionFrom, rangeFrom } from "../host";
import { offsetAt, relativeOffsetAtAbsolutePosition, positionAt } from "../utils/text-offsets";
import { toRangeDelta, rangeTranslate, rangeContains, maxPosition } from "../utils/text-deltas";

suite("text", () => {
  test("offsetAt maps a position to a character offset", () => {
    const text = "abc\ndef";
    assert.strictEqual(offsetAt(text, positionFrom(0, 1)), 1);
    assert.strictEqual(offsetAt(text, positionFrom(1, 2)), 6);
    assert.strictEqual(offsetAt(text, positionFrom(5, 0)), -1, "beyond end of text");
  });

  test("positionAt maps a character offset to a position", () => {
    const text = "abc\ndef";
    assert.deepStrictEqual([positionAt(text, 0).line, positionAt(text, 0).character], [0, 0]);
    assert.deepStrictEqual([positionAt(text, 4).line, positionAt(text, 4).character], [1, 0]);
    assert.deepStrictEqual([positionAt(text, 99).line, positionAt(text, 99).character], [1, 3], "clamped to text end");
  });

  test("relativeOffsetAtAbsolutePosition computes the offset within a text slice", () => {
    const text = "hello world";
    const start = positionFrom(0, 0);
    assert.strictEqual(relativeOffsetAtAbsolutePosition(text, start, positionFrom(0, 6)), 6);
    assert.strictEqual(relativeOffsetAtAbsolutePosition(text, positionFrom(0, 6), positionFrom(0, 9)), 3);
    assert.strictEqual(relativeOffsetAtAbsolutePosition(text, positionFrom(0, 6), positionFrom(0, 3)), -1, "before text start");
  });

  test("toRangeDelta reports line and character deltas for an insertion", () => {
    const delta = toRangeDelta(rangeFrom(0, 3, 0, 3), "x\ny");
    // The empty range end lands at (1,1): one line down, one character on the new line
    assert.strictEqual(delta.linesDelta, 1);
    assert.strictEqual(delta.endCharactersDelta, 1);
  });

  test("toRangeDelta reports deltas for a multi-line deletion", () => {
    const delta = toRangeDelta(rangeFrom(0, 0, 2, 4), "");
    assert.strictEqual(delta.linesDelta, -2);
    assert.strictEqual(delta.endCharactersDelta, -4);
  });

  test("rangeTranslate shifts ranges after and inside the changed line", () => {
    // Insert "ab" at (0, 5): characters on line 0 after col 5 shift right by 2,
    // later lines shift down by 0 lines but the end-column delta applies.
    const delta = toRangeDelta(rangeFrom(0, 5, 0, 5), "ab");
    const before = rangeTranslate(rangeFrom(0, 0, 0, 3), delta);
    assert.deepStrictEqual([before.start.line, before.start.character, before.end.line, before.end.character], [0, 0, 0, 3]);
    const after = rangeTranslate(rangeFrom(0, 8, 0, 11), delta);
    assert.deepStrictEqual([after.start.line, after.start.character, after.end.line, after.end.character], [0, 10, 0, 13]);
  });

  test("rangeTranslate shifts ranges on later lines down by the line delta", () => {
    const delta = toRangeDelta(rangeFrom(0, 0, 0, 0), "x\ny\n");
    const shifted = rangeTranslate(rangeFrom(2, 1, 2, 4), delta);
    assert.deepStrictEqual([shifted.start.line, shifted.start.character, shifted.end.line, shifted.end.character], [4, 1, 4, 4]);
  });

  test("rangeContains honors the start/end inclusivity flags", () => {
    const r = rangeFrom(0, 2, 0, 8);
    const mid = positionFrom(0, 5);
    assert.strictEqual(rangeContains(r, mid), true);
    assert.strictEqual(rangeContains(r, positionFrom(0, 2)), true, "start inclusive by default");
    assert.strictEqual(rangeContains(r, positionFrom(0, 2), true), false, "excludeStart");
    assert.strictEqual(rangeContains(r, positionFrom(0, 8)), false, "end exclusive by default");
    assert.strictEqual(rangeContains(r, positionFrom(0, 8), false, true), true, "includeEnd");
  });

  test("maxPosition returns the later line regardless of character", () => {
    // Regression: the old code compared x to itself, so a later line with a
    // smaller character was discarded (returned the earlier line instead).
    const a = positionFrom(5, 9);
    const b = positionFrom(2, 1);
    assert.deepStrictEqual(maxPosition(a, b), a, "later line wins");
    assert.deepStrictEqual(maxPosition(b, a), a, "argument order does not matter");
    assert.deepStrictEqual(maxPosition(positionFrom(5, 1), positionFrom(2, 9)), positionFrom(5, 1), "later line with smaller character still wins");
  });

  test("maxPosition compares characters on the same line", () => {
    assert.deepStrictEqual(maxPosition(positionFrom(3, 2), positionFrom(3, 7)), positionFrom(3, 7));
    assert.deepStrictEqual(maxPosition(positionFrom(3, 7), positionFrom(3, 2)), positionFrom(3, 7));
  });

  test("maxPosition returns either argument for equal positions", () => {
    const p = positionFrom(4, 4);
    assert.deepStrictEqual(maxPosition(p, p), p);
  });
});

