/**
 * The host's editor value types: the visible editor surface the backend can
 * read and write (selections), the document line/document views, and the
 * selection-change event.
 */
import type { Position, Range, Selection } from './host-geometry';
import type { TextEditorDecorationType } from './host-types';

export interface TextLine {
  readonly text: string;
  readonly range: Range;
  readonly firstOrOnlyRange: Range;
  readonly rangeIncludingLineBreak: Range;
  readonly lineNumber: number;
  rangeOfNonWhitespaceCharacters(): Range;
  offsetAt(character: number): number;
  positionAt(offset: number): Position;
}

export interface TextDocument {
  readonly uri: string;
  readonly languageId: string;
  readonly fileName: string;
  readonly isClosed: boolean;
  readonly lineCount: number;
  getText(range?: Range): string;
  lineAt(line: number): TextLine;
  positionAt(offset: number): Position;
  offsetAt(position: Position): number;
  validateRange(range: Range): Range;
}

export interface TextEditor {
  readonly document: TextDocument;
  /** Readable and writable — the controller adjusts cursors by writing here. */
  selections: Selection[];
  /** The currently visible portion of the document (viewport). Optional —
   *  adapters that cannot determine the viewport omit this. */
  readonly visibleRanges?: Range[];
  setDecorations(decorationType: TextEditorDecorationType, ranges: Range[]): void;
}

export interface TextEditorSelectionEvent {
  readonly editor: TextEditor;
  readonly selections: Selection[];
}

/**
 * Decoration types for the host contract: range behavior, render options,
 * and the decoration type handle the adapter maps to a real IDE decoration.
 */
import type { Disposable } from '../config/host-events';

/**
 * Mirrors vscode.DecorationRangeBehavior: how the decoration range reacts
 * to cursor movement. A const object (usable as a value) plus the string
 * union type of the same name.
 */
export const DecorationRangeBehavior = {
  OpenOpen: 'OpenOpen',
  ClosedClosed: 'ClosedClosed',
  OpenClosed: 'OpenClosed',
  ClosedOpen: 'ClosedOpen',
} as const;

export type DecorationRangeBehaviorValue =
  (typeof DecorationRangeBehavior)[keyof typeof DecorationRangeBehavior];

// The members the two render-options shapes share (mirrors vscode).
interface DecorationRenderOptionsBase {
  readonly rangeBehavior?: DecorationRangeBehaviorValue;
  readonly color?: string;
  readonly letterSpacing?: string;
  readonly fontStyle?: string;
  readonly fontWeight?: string;
  readonly backgroundColor?: string;
  readonly outline?: string;
  readonly border?: string;
  readonly borderRadius?: string;
  readonly textDecoration?: string;
  readonly cursor?: string;
  readonly iconPath?: string;
}

// The inline `before`/`after` content block (mirrors vscode).
interface DecorationContent {
  contentText?: string;
  contentIcon?: string;
  textDecoration?: string;
}

export interface DecorationRenderOptions extends DecorationRenderOptionsBase {
  readonly before?: DecorationContent;
  readonly after?: DecorationContent;
  readonly dark?: Partial<DecorationRenderOptions>;
  readonly light?: Partial<DecorationRenderOptions>;
}

export interface DecorationInstanceRenderOptions extends DecorationRenderOptionsBase {
  readonly before?: DecorationContent & { border?: string; margin?: string };
  readonly after?: DecorationContent & { border?: string; margin?: string };
}

/**
 * A decoration type handle. The backend creates these via
 * `Host.createDecorationType` and passes them to `TextEditor.setDecorations`.
 * The adapter maps the `key` to a real IDE decoration type.
 */
export interface TextEditorDecorationType extends Disposable {
  readonly key: string;
  readonly options: DecorationRenderOptions;
}

/**
 * A mobx-state-tree custom type that stores the value as-is: no snapshot
 * processing, no proxying. Used for Set/Map/sparse arrays and objects mutated
 * in place (e.g. vscode Range/TextDocument/Host instances).
 */
import { types as t } from "mobx-state-tree";

const identitySnapshot = <T,>(s: T): T => s;
const identityTarget = (): boolean => true;
const noValidation = (): string => "";

export const passthrough = <T,>(name: string) =>
	t.custom<T, T>({
		name,
		fromSnapshot: identitySnapshot,
		toSnapshot: identitySnapshot,
		isTargetType: identityTarget,
		getValidationMessage: noValidation,
	});

import type { Position, Range, TextDocument } from '../host';
import { positionCompare } from './range';

const isStrictlyInside = (range: Range, p: Position): boolean => {
  const afterStart = positionCompare(p, range.start) > 0;
  const beforeEnd = positionCompare(p, range.end) < 0;
  return afterStart && beforeEnd;
};

/** Binary search for the range that strictly contains `end`; undefined when none does. */
const findRangeContaining = (avoidRanges: Range[], end: Position): { range: Range, index: number } | undefined => {
  let begin = 0;
  let endIdx = avoidRanges.length;
  while (begin < endIdx) {
    const idx = (begin + endIdx) >> 1;
    const range = avoidRanges[idx];
    if (isStrictlyInside(range, end)) {
      return { range, index: idx };
    }
    const beforeStart = positionCompare(end, range.start) < 0;
    if (beforeStart) {
      endIdx = idx;
    } else {
      begin = idx + 1;
    }
  }
  return undefined;
};

/** Snaps the cursor to the edge of the range it would have crossed, based on movement direction. */
const snapToRangeEdge = (start: Position, end: Position, range: Range): { pos: Position, range: Range } => {
  if (start.line === end.line && start.character > end.character) {
    return { pos: range.start, range }; // moving left
  }
  if (start.line === end.line && start.character < end.character) {
    return { pos: range.end, range }; // moving right
  }
  return { pos: end, range: undefined };
};

export function adjustCursorMovement(start: Position, end: Position, doc: TextDocument, avoidRanges: Range[]): {pos: Position, range: Range} {
  try {
    const match = findRangeContaining(avoidRanges, end);
    if (match) {
      return snapToRangeEdge(start, end, match.range);
    }
  } catch (err) {
    // cursor movement adjustment failed — fall through to the plain position
  }
  return {pos: end, range: undefined};
}

/**
 * The host's own geometry value types: Position, Range, Selection.
 *
 * The backend owns its geometry — an IDE adapter converts IDE geometry to
 * these via the `*From` factories and back. Kept in the decorations feature
 * because decoration ranges are built from them.
 *
 * Functional by design: the types are plain interfaces and all behavior is
 * module-scope free functions (the backend is functional + mobx, no classes).
 */

export interface Position {
  readonly line: number;
  readonly character: number;
}

export interface Range {
  /** Brand: lets `isRange` tell a Range apart from a Position. */
  readonly __range: true;
  readonly start: Position;
  readonly end: Position;
}

export interface Selection extends Range {
  readonly anchor: Position;
  readonly active: Position;
}

// ---------------------------------------------------------------------------
// Position
// ---------------------------------------------------------------------------

export const positionFrom = (line: number, character: number): Position => ({
  line,
  character,
});

export const positionCompare = (a: Position, b: Position): number => {
  if (a.line < b.line) return -1;
  if (a.line > b.line) return 1;
  if (a.character < b.character) return -1;
  if (a.character > b.character) return 1;
  return 0;
};

export const positionIsEqual = (a: Position, b: Position): boolean =>
  a.line === b.line && a.character === b.character;

export const positionIsNull = (p: Position): boolean =>
  p.line < 0 && p.character < 0;

export const positionTranslate = (p: Position, lineDelta = 0, charDelta = 0): Position => ({
  line: p.line + lineDelta,
  character: p.character + charDelta,
});

export const positionWith = (p: Position, line?: number, character?: number): Position => {
  if (line === undefined && character === undefined) return p;
  return { line: line ?? p.line, character: character ?? p.character };
};

// ---------------------------------------------------------------------------
// Range
// ---------------------------------------------------------------------------

/** 4-arg form, mirroring `vscode.Range`: (startLine, startChar, endLine, endChar). */
export const rangeFrom = (
  startLine: number,
  startCharacter: number,
  endLine: number,
  endCharacter: number,
): Range => ({
  __range: true,
  start: { line: startLine, character: startCharacter },
  end: { line: endLine, character: endCharacter },
});

/** 2-arg form: (start: Position, end: Position). */
export const rangeFromPositions = (start: Position, end: Position): Range => ({
  __range: true,
  start,
  end,
});

/** Type guard: distinguishes a Range from a Position. */
export const isRange = (value: Position | Range): value is Range =>
  (value as Range).__range === true;

export const rangeIsEmpty = (r: Range): boolean =>
  r.start.line === r.end.line && r.start.character === r.end.character;

export const rangeIsEqual = (a: Range, b: Range): boolean =>
  a.start.line === b.start.line && a.start.character === b.start.character &&
  a.end.line === b.end.line && a.end.character === b.end.character;

export const rangeIsSingleLine = (r: Range): boolean =>
  r.start.line === r.end.line;

export const rangeIsValid = (r: Range): boolean =>
  !(r.start.line > r.end.line || (r.start.line === r.end.line && r.start.character > r.end.character));

/** True when `p` is not before `start` and not after `end` (both inclusive). */
const positionWithinBounds = (p: Position, start: Position, end: Position): boolean =>
  positionCompare(p, start) >= 0 && positionCompare(p, end) <= 0;

export const rangeContains = (range: Range, positionOrRange: Position | Range): boolean => {
  const r = positionOrRange as Range;
  if (r.__range === true) {
    return positionWithinBounds(r.start, range.start, range.end) && positionWithinBounds(r.end, range.start, range.end);
  }
  const p = positionOrRange as Position;
  return positionWithinBounds(p, range.start, range.end);
};

export const rangeIntersection = (range: Range, other: Range): Range | null => {
  const start = positionCompare(range.start, other.start) > 0 ? range.start : other.start;
  const end = positionCompare(range.end, other.end) < 0 ? range.end : other.end;
  if (positionCompare(start, end) > 0) return null;
  return { __range: true, start, end };
};

export const rangeUnion = (range: Range, other: Range): Range => {
  const startBefore = range.start.line < other.start.line || (range.start.line === other.start.line && range.start.character < other.start.character);
  const start = startBefore ? range.start : other.start;
  const endAfter = range.end.line > other.end.line || (range.end.line === other.end.line && range.end.character > other.end.character);
  const end = endAfter ? range.end : other.end;
  return { __range: true, start, end };
};

export const rangeEndIsAt = (r: Range, line: number, character: number): boolean =>
  r.end.line === line && r.end.character === character;

export const rangeTranslate = (range: Range, lineDelta = 0, charDelta = 0): Range => ({
  __range: true,
  start: { line: range.start.line + lineDelta, character: range.start.character + charDelta },
  end: { line: range.end.line + lineDelta, character: range.end.character + charDelta },
});

export const rangeWith = (range: Range, start?: Position, end?: Position): Range =>
  ({ __range: true, start: start ?? range.start, end: end ?? range.end });

/** Maps every element of a set through `fn`, collecting non-undefined results into a new set. */
export const mapSet = <T, U>(set: Set<T>, fn: (item: T) => U | undefined): Set<U> => {
  const out = new Set<U>();
  for (const item of set) {
    const mapped = fn(item);
    if (mapped !== undefined) out.add(mapped);
  }
  return out;
};

// ---------------------------------------------------------------------------
// Selection
// ---------------------------------------------------------------------------

export const selectionFrom = (anchor: Position, active: Position): Selection => ({
  __range: true,
  start: anchor,
  end: active,
  anchor,
  active,
});

import type { Position, Range } from '../host';

// 'sticky' flag is not yet supported :(
export interface RangeDelta {
  start: Position;
  end: Position;
  linesDelta: number;
  endCharactersDelta: number; // delta for positions on the same line as the end position
}

/**
 * @returns the lines and characters represented by the text
 */
export function toRangeDelta(oldRange: Range, text: string): RangeDelta {
  // position of the end of `text`
  let newEndLine = 0;
  let newEndCharacter = 0;
  let i = 0;
  while (i < text.length) {
    const ch = text[i];
    if (ch === '\n') { newEndLine++; newEndCharacter = 0; i++; }
    else if (ch === '\r') {
      newEndLine++; newEndCharacter = 0; i++;
      if (text[i] === '\n') i++;
    }
    else { newEndCharacter++; i++; }
  }
  let charsDelta;
  if (oldRange.start.line == oldRange.end.line)
    charsDelta = newEndCharacter - (oldRange.end.character - oldRange.start.character);
  else
    charsDelta = newEndCharacter - oldRange.end.character;

  return {
    start: oldRange.start,
    end: oldRange.end,
    linesDelta: newEndLine - (oldRange.end.line - oldRange.start.line),
    endCharactersDelta: charsDelta,
  };
}

export function rangeDeltaNewRange(delta: RangeDelta): Range {
  let x: number;
  if (delta.linesDelta > 0)
    x = delta.endCharactersDelta;
  else if (delta.linesDelta < 0 && delta.start.line == delta.end.line + delta.linesDelta)
    x = delta.end.character + delta.endCharactersDelta + delta.start.character;
  else
    x = delta.end.character + delta.endCharactersDelta;
  return { __range: true, start: delta.start, end: { line: delta.end.line + delta.linesDelta, character: x } };
}

/** Adjusts a character offset for a delta that ends on the same line. */
const adjustSameLineCharacter = (character: number, delta: RangeDelta): number => {
  let x = character + delta.endCharactersDelta;
  if (delta.linesDelta > 0) {
    x = x - delta.end.character;
  } else if (delta.start.line == delta.end.line + delta.linesDelta && delta.linesDelta < 0) {
    x = x + delta.start.character;
  }
  return x;
};

/** Translates one end of a range by a delta, given whether it sits before, on, or after the delta end. */
const translatePosition = (p: Position, delta: RangeDelta, onEndLine: boolean, beforeEnd: boolean): Position => {
  if (beforeEnd) {
    return { line: p.line, character: p.character };
  }
  if (onEndLine) {
    return { line: p.line + delta.linesDelta, character: adjustSameLineCharacter(p.character, delta) };
  }
  return { line: p.line + delta.linesDelta, character: p.character };
};

export function rangeTranslate(range: Range, delta: RangeDelta): Range {
  const startOnEndLine = delta.end.line == range.start.line;
  const startBeforeEnd = range.start.line < delta.end.line || (startOnEndLine && range.start.character < delta.end.character);
  const endOnEndLine = delta.end.line == range.end.line;
  const endBeforeEnd = range.end.line < delta.end.line || (endOnEndLine && range.end.character <= delta.end.character);
  return {
    __range: true,
    start: translatePosition(range.start, delta, startOnEndLine, startBeforeEnd),
    end: translatePosition(range.end, delta, endOnEndLine, endBeforeEnd),
  };
}

const isAtRangeStart = (range: Range, pos: Position): boolean =>
  range.start.line === pos.line && range.start.character === pos.character;
const isAtOrAfterRangeStart = (range: Range, pos: Position): boolean =>
  range.start.line < pos.line || (range.start.line === pos.line && range.start.character <= pos.character);
const isAtRangeEnd = (range: Range, pos: Position): boolean =>
  range.end.line === pos.line && range.end.character === pos.character;
const isBeforeRangeEnd = (range: Range, pos: Position): boolean =>
  pos.line < range.end.line || (pos.line === range.end.line && pos.character < range.end.character);

export function rangeContains(range: Range, pos: Position, exclStart = false, inclEnd = false): boolean {
  if (!isAtOrAfterRangeStart(range, pos)) return false;
  if (exclStart && isAtRangeStart(range, pos)) return false;
  if (inclEnd && isAtRangeEnd(range, pos)) return true;
  return isBeforeRangeEnd(range, pos);
}

export function maxPosition(x: Position, y: Position): Position {
  if (x.line < y.line)
    return y;
  if (x.line > y.line)
    return x;
  if (x.character < y.character)
    return y;
  else
    return x;
}

import type { Position } from '../host';

/** Index just past the line ending at or after `from`, or text.length when there is none. */
const nextLineEnd = (text: string, from: number): number => {
  let index = 0;
  for (index = from; index < text.length; index++) {
    if (text[index] === '\n' || text[index] === '\r') break;
  }
  if (index >= text.length) return text.length;
  if (text[index] === '\r' && text[index + 1] === '\n') return index + 2;
  return index + 1;
};

export function offsetAt(text: string, pos: Position): number {
  let line = pos.line;
  let lastIndex = 0;
  while (line > 0) {
    let i = lastIndex;
    let found = false;
    while (i < text.length) {
      const ch = text[i];
      if (ch === '\n') { i++; found = true; break; }
      if (ch === '\r') {
        i++;
        if (text[i] === '\n') i++;
        found = true;
        break;
      }
      i++;
    }
    if (!found) return -1; // the position is beyond the length of text
    lastIndex = i;
    line--;
  }
  return lastIndex + pos.character;
}

/** Calculates the offset into text of pos, where textStart is the position where text starts and both pos and textStart are absolute positions.
 * @return the offset into text indicated by pos, or -1 if pos is out of range
 *
 * 'abc\ndef'
 * 'acbX\ndef'
 * +++*** --> +++_***
 * */
/** Advances `offset` past `count` line endings, or returns -1 if the text runs out first. */
const skipLines = (text: string, offset: number, count: number): number => {
  for (let n = 0; n < count; n++) {
    offset = nextLineEnd(text, offset);
    if (offset >= text.length) return -1;
  }
  return offset;
};

export function relativeOffsetAtAbsolutePosition(text: string, textStart: Position, pos: Position): number {
  if (textStart.line > pos.line) return -1;
  if (textStart.line === pos.line) {
    const d = pos.character - textStart.character;
    return d < 0 ? -1 : d;
  }
  const lineOffset = skipLines(text, 0, pos.line - textStart.line);
  if (lineOffset < 0) return -1;
  const d = pos.character + lineOffset;
  return d < 0 ? -1 : d;
}

/**
 * @returns the Position (line, column) for the location (character position), assuming that text begins at start
 */
/** Walks line endings in `text` until the line containing `offset`, then builds the position. */
const positionFromLineStart = (text: string, offset: number, startLine: number, startCharacter: number): Position => {
  let lastIndex = 0;
  let lineEnd = nextLineEnd(text, lastIndex);
  let crossed = 0;
  while (lineEnd < offset) {
    lastIndex = lineEnd;
    crossed += 1;
    lineEnd = nextLineEnd(text, lastIndex);
  }

  const line = startLine + crossed;
  const character = crossed === 0 ? startCharacter + (offset - lastIndex) : offset - lastIndex;

  return { line, character };
};

export function positionAtRelative(start: Position, text: string, offset: number): Position {
  if (offset > text.length) offset = text.length;
  return positionFromLineStart(text, offset, start.line, start.character);
}

/**
 * @returns the Position (line, column) for the location (character position)
 */
export function positionAt(text: string, offset: number): Position {
  if (offset > text.length) offset = text.length;
  return positionFromLineStart(text, offset, 0, 0);
}
